/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20190311-3","meetingId":"r01-c-budget","date":"2019年3月11日","dateIso":"2019-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を163件整理しています。","topics":[{"id":"topic-01","title":"平成３１年度品川区一般会計予算","agenda":"平成３１年度品川区一般会計予算","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、ページ２７２の保健予防費のうち、予防接種費から定期予防接種、任意予防接種についてお尋ねいたします。風しんについては補正でお聞きしたので、衛生費では麻しん流行についてお伺いします。","respondent":"鷹箸保健予防課長","answer":"国は、２月１８日に、大流行を受けまして「麻しん発生報告数の増加に伴う注意喚起について」というものを全国一斉に発出いたしました。","id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"質問","question":"アメリカでも、反ワクチン運動が盛んなワシントン州、ニューヨーク州、テキサス州など５カ所で流行が起こり、現在、１００人以上が発病しています。麻しん流行がなぜ問題になるのか、わかりやすくご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"感染後１０年、年間５例から１０例という非常に少ない数になりましたけれども、それでも毎年患者が発生しております。症状の進行を何とか、今現在の治療で遅らせることはできても、最終的に治療法がなく亡くなってしまう非常に重篤な疾患だというものです。","id":"exchange-002"},{"speaker":"鈴木（博）委員","kind":"質問","question":"犬公方で有名な徳川綱吉も６４歳のとき、麻しんに感染して死亡しました。Vaccine Hesitancyとはどういうことなのか簡単にご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"そういう方々はお薬も飲まないとか、いろいろな考え方があるように伺っておりますけれども、そういう方々が一部いらっしゃることは伺っています。","id":"exchange-003"},{"speaker":"鈴木（博）委員","kind":"質問","question":"約１,１５０万円の金を受けとっていたこと、この論文の掲載を取り消し、この人物はイギリスの医師免許を剥奪されました。このようなＷＨＯが掲げるVaccine Hesitancyに関して、品川区はどのように対応されているのか、簡単にご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"勧奨対象者が大体１１％ぐらいいるのですけれども、最終的な接種率は９８％まで上がっておりますので、個別勧奨の効果はあると考えております。場合によってはネグレクト、虐待の可能性なども考えまして、個別訪問などもしています。","id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"質問","question":"特に接種率を上げたい成人のＭＲ５期などでは、検討してもよいのではないかと考えます。いろいろな方策があるので、それについてもご説明したと思いますが、それに関して区のご見解をお伺いします。","respondent":"鷹箸保健予防課長","answer":"ＭＲ５期に関しましては、国が全国どこでも受けられるような接種体制を進めていることから、それから抗体検査の受診率の向上に努めていきたいと考えております。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、おたふくかぜワクチン、以下、ムンプスワクチンと呼びますが、それについて伺います。ムンプスワクチン２回接種の具体的な事業内容をご説明ください。","respondent":"鷹箸保健予防課長","answer":"これまで任意で１回接種のみ全額助成とさせていただいていましたムンプスワクチンですが、１歳から小学校就学前までの２回接種を全額助成とするものです。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"意見","question":"最低限の接種費用助成を行わない区が８区もある中で、２３区中トップクラスだと専門家の間では実際高く評価されているのです。今回のムンプスワクチン２回接種の意義について、いま一度、区の抱負を説明を求めました。","respondent":"鷹箸保健予防課長","answer":"ムンプスワクチンの１回接種で８８％、２回接種で９９％、発症者を減らせると言われておりまして、この２回接種は日本小児科学会でも推奨しています。","id":"exchange-007"},{"speaker":"新妻委員","kind":"提案","question":"２０１１年第１回定例会の一般質問におきまして、同年決算特別委員会では、助成制度の創設や相談体制の整備を提案してまいりました。そこに「適切な検査を治療をすることで８０％以上が出産できる」との一文をぜひ追加をしてほしいと求めましたが、いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"不妊と不育という２つの症例ですので、現在、区のホームページに掲載させていただいているところです。８割以上の方が適切なカウンセリングとか治療を受けることによって、その辺は、工夫をしていきたいと考えております。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"こういうことがあるということもしっかりと認識をし、周知をしてほしいと求めましたので、どうぞよろしくお願いいたします。品川においても適切な支援がされますように対応してほしいと求めましたが、都の認識とあわせて、対応についてご見解をお伺いいたします。","respondent":"仁平品川保健センター所長","answer":"東京都の一般質問の関係で不育症の対策といいますか、助成に取組んでいくというお話がありますので、区といたしましては、東京都の動向を見ながら適切な対応をとっていきたいと考えております。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"こういう中で公衆浴場商業協同組合からのご要望をつなげて、現在、公衆浴場への設置につながっております。これまでもコンビニへの設置を要望してまいりましたが、または今後、コンビニへの設置に向けて品川区のお考えをお聞かせほしいと求めました。","respondent":"川島健康課長","answer":"今回７月からコンビニにＡＥＤを設置したということでお話を聞いてみたところ、今、なかなか難しいという感想を持っているところです。そちらのほうに何とかＡＥＤを設置できないかというようなお話をさせていただいているところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"来年度開催のＥＣＯフェスティバルにおいては、どう対応されるのかお伺いいたします。前回は場所が悪く、なかなか区民の方がわかりづらいという声がありましたので、実施場所についてご検討されているのかお伺いいたします。","respondent":"小林環境課長","answer":"今度の５月に開催される予定のＥＣＯフェスティバルにつきましても、今、検討を進めているところです。今現在、詳細を詰めている最中ですが、目立つ場所での実施を引き続き検討してまいりたいと考えています。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"食品ロス削減が学べる場であってほしい、フードドライブの常設化となるような環境未来館であってほしいと考えていますが、ご見解を伺います。ぜひこの環境未来館においてフードドライブの常設を求めたいと思いますが、ご所見を伺います。","respondent":"小林環境課長","answer":"２点のご質問の中の最初の現状の検討状況ですが、昨年１０月に議会のほうへ説明して以降、導入機能の整理をしたところです。ご提案のフードドライブの常設設置につきましては、この取組みを継続して進めてまいりたいというふうに考えているところです。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"一般質問では、中小企業社員のがん検診、がん対策の強化を求めて、がん検診推進を要望いたしました。そういう要望をさせていただきましたが、具体的なことがもしあるようであれば教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"現在、がん対策に関します啓発の周知チラシなどにつきましては、中小企業センターに設置をして周知を行っているところです。チラシ、冊子の配布など、具体的に取組みをするということを考えているところです。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後もしっかり進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２７８ページ、環境対策費、２８２ページ、リサイクル推進費、そして２８４ページの清掃費全般について、環境問題などを含めてお伺いします。まず、品川区がＳＤＧｓ先進度調査の中で何位なのかわかれば、教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"おそらく委員がおっしゃっているのは、日経のほうで調査しているものであったかと思いますけれども、４６位であったかと思います。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"幅広いところでの評価なので、新聞では４０位までしか出ていなかったので、品川区はどうなのかと思ってお聞きしました。危機感が、私はあまり感じられない予算であるなと思って受けとめているのですが、どこに力点を置いているのか説明を求めました。","respondent":"小林環境課長、柏原企画調整課長、工藤品川区清掃事務所長","answer":"今回、戸越公園に設置する新たな施設の開設に伴って、しっかりそういったところを啓発してまいりたいと考えているところです。… 先ほどの順位を訂正させてください。４９位です。プラスチックの削減につきまして、今回、周知啓発を図ってまいるです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特にＣＯ２排出量を減らす意味でも、プラスチックのごみ対策にすごく今、重点が置かれるべきであると思っています。どう進めていこうとしているのか、１点お聞かせいただきたいのと、ざっくりでいいので説明を求めました。","respondent":"工藤品川区清掃事務所長、小林環境課長","answer":"平成２８年度が１,４７０トン、平成２９年度が１,４６９トンということで、微増から横ばいとなっています。平成２８年度が１,１４１トン… ２月に開催しました環境講演会では、海洋プラスチックに関する課題として、パネル展示を実施したところです。… こちら、２３区の清掃工場のごみの中身について、燃やされる量の分析です。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"提案","question":"前回、決算特別委員会のときに幾つか提案をしたのですが、その点がどうなっているのかお聞かせほしいと求めました。いいＤＶＤの教材があるので、地域をあちこち回って温暖化防止の啓発に力を入れていただきたいのですが、いかがか尋ねました。","respondent":"工藤品川区清掃事務所長、小林環境課長","answer":"過去５年を見ますと、大体６,０００トン前後で推移しており、横ばいの状況です。ペットボトルはいろいろとリサイクルされておりますけれども、有効利用率は、統計資料の中では約８３.９％ということになっているです。 一般的にも知られていないのが現状かと考えていますので、イベント等の状況も把握してまいりたいというふうに考えてあります。啓発事業につきましては、引き続き、さまざまな形で進めてまいりたいと考えています。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"２８３ページ、もったいないプロジェクト、２９１ページ、商店街の訪日外国人に対する取組みについて教えてほしいと求めました。今もう既に取組みを進めていただいているお店等への、その後のアプローチがあるのかどうか教えてほしいと求めました。","respondent":"小林環境課長、山崎商業・ものづくり課長","answer":"もったいない推進事業の方針ですが、当初の目標ですが、東京２０２０大会までに１５０店舗を登録していくべく進めているところです。あるいはＰＲが進むような場所を今後も重点的に進めていきながら… 非常に会話が成立するというようなことで、商連をはじめ団体も、そうした対応を推奨しているような状況です。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"今、さらに一歩踏み出すような取組みについて推進していくことは非常に大事かと思っているのですが、その点について教えてほしいと求めました。もったいないプロジェクトについてもう一度伺います。","respondent":"小林環境課長","answer":"ただ、食品ロス削減に向けて、さまざまな取組みは今後も区としても続けていかなければいけないというふうに考えてあります。高校生向けの事業として、引き続き幅広い世代に対して広く食品ロスの大切さを学んでいただく事業を進めてまいりたいというふうに考えてあります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"そして、償還管理などはどういうふうにしているのか、確実にやっているのかお伺いします。次に、１つの団体の助成金としてはかなり大きな額だと思っているのですが、コストパフォーマンスとしてはどうか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"自己資金の３分の１はあるのですが、イベントを実施する際に事業資金が足りないといいますか、そういったときに貸し付けを行うようなものです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"今は違うのではないですかという質問で、償還管理などはどのようにしているのかという質問だったので、もう一度ご答弁いただきたい。保健センターごとにそんなに変わると思わないのですけれども、なぜ３つ共通ではないかについてお伺いします。","respondent":"山崎商業・ものづくり課長、川島健康課長","answer":"貸付は、区が商連に対してお金を支出しまして、商連がそれぞれの商店街への貸付金額でありますとか、内容を確認してやりとりをします。… 保健センターの管理運営費ですが、こちらはそれぞれ広さですとか大きさ、それから例えば荏原保健センターですと複合施設になっているということで、内容がそれぞれ異なった維持管理の経費がかかるです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"それと、予算額が１８万円と非常に控えめな金額ですが、報道されている化学物質あるいはダニなどのハウスダストも含まれるのでしょうか。その辺の確認と、最近の傾向を質問したいのですが、件数は増加傾向にあるのかと、今後の方向性についてお伺いします。","respondent":"鈴木生活衛生課長","answer":"お尋ねのありました環境関係の調査ですが、これは国の調査を受けて、区のほうでも区民の健康状況の管理のために行っているものです。検査まで区のほうで対応したものは現在ございませんので、１８万円は基本的な事務経費だとか、その辺の部分を毎年計上しているものです。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもの権利条約を知り、みんなに広げていきたいと訴え、全ての親が持つ母子手帳に載せたいと母子手帳への子どもの権利条約の掲載を区長へ要望し。独立した人格であることを確認する機会につながるよう、子どもの権利条約が掲載されるよう求めますが、いかがか尋ねました。","respondent":"鷹箸保健予防課長、川島健康課長","answer":"逆に、必要な予防接種については、定期も任意も全て母子手帳には載っております。特段意識をして積極的な勧奨を差し控えるというふうに対応するものではございません。 ちょっと私どものほうで、今、母子手帳にそれが掲載されていない経緯については承知しておりません。これをどうするか、今この場ではお答えできないのですが、どうするかということを進めていきたいと考えています。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"民生費でも伺ったのですが、生活者ネットワークは、保護者が具体的に産褥期について学べる場や情報提供の強化を求めています。そのホームページがすぐにつながるような体制を整え、母子の命をつなげる取組みを始めてほしいと求めますが、見解を伺います。","respondent":"鷹箸保健予防課長、川島健康課長、仁平品川保健センター所長","answer":"母子手帳へのＨＰＶワクチンの記載についてですけれども、先ほどの国の方針、接種勧奨差し控えの方向性が出たのが平成２５年です。今後の方針について… 自治体の任意様式というところで国に示された部分に沿った形でつくられている母子手帳を購入しているところです。… 引き続き、最新の情報等を提供できるように進めてまいりたいと考えております。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"２０１８年予算特別委員会で香害について質問しました。その配慮について啓発を求めますが、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"区のほうでも、体調によりにおいが嫌な方とかということについては把握しておりますが、保健所のほうには具体的なご相談はまだいただいておりません。保健所として、今、啓発は控えているところです。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"２９３ページ、３０１ページ、消費者育成および支援についてをお伺いいたします。教育との連携を効果的に実施していただきたいのですが、加害防止のための学習の機会について、区のご見解をお伺いいたします。","respondent":"工藤品川区清掃事務所長、山崎商業・ものづくり課長","answer":"来年度の見通しが実績としてこのような部分が見込まれるということで若干増えてあります。昨年度と比べて、ほぼ同様の部分の予算計上をさせていただいているところです。もともとビルの２階、３階に東京都の認証保育所が入っておりまして、そうしたことをもって適正に運営をしてまいりたいと考えておるところです。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほどの事故防止の観点からも、職員の心身のケアにも注視していただきたいというふうに要望しますが、こちらはお答えほしいと求めました。動物の部分についてですけれども、アニマルウェルフェアの考え方を区としてどのように捉えていますか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"私ども清掃事務所では、安全衛生委員会というものを法律に基づいて、条例に基づいて設置しております。腰痛予防のためにどういった姿勢を取るのかとか、研修を企画したり、そのような対応をしながらケアに努めているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"２９７ページ、２９９ページ、街路灯に関連してお聞きいたします。当然、今の健康大学しながわのご案内ページの改善を行っていただきたいのですけれども、それについてはいかがお考えか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"平成２８年度からは、実際に地域で健康づくり活動をされる方を育成しているというようなものが、この健康大学しながわです。６月ごろになりますので、今後、もう少しわかりやすいページにしていくように考えたいと思います。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"健康大学しながわに入りたいという方は結構潜在的に多くいらっしゃると思いますので、よろしくお願いします。今現在は荏原保健センターですけれども、品川保健センターにおいても開講するというお考えはないか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"かつて約７年間ほどは品川保健センターで所管としてやっておりました。３保健センターにおきましては、所管はありますけれども、協力しながらやっている事業の１つです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"禁煙外来治療費助成についてお伺いしますけれども、この禁煙外来を受けに来ている方は増えているのでしょうか。今現在の状況を説明を求めました。","respondent":"川島健康課長","answer":"禁煙外来助成の申請の状況です。３月、治療が完了して申請していただいた方が２９人という状況で、昨年度よりも多くの方に申請していただいている状況です。","id":"exchange-031"},{"speaker":"筒井委員","kind":"意見","question":"次に、環境調査測定費に関連しまして、平成３０年度予算には、航空機騒音調査があったかと思うのですけれども、今年はなくなっております。その理由をお知らせくださいとの意見を述べました。","respondent":"小林環境課長","answer":"具体的な設置場所については何も示されていない中、区として、状況把握の一環で設置する予算措置を講じたところです。国は引き続き設置場所の検討を進めるですが、現段階で区内に複数箇所設置することで検討を進めているということで、現在。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"国の動向が見えてきたから計上しないということでいいのでしょうか。ちょっとよくわからなかったのでもう１回ご説明をお願いします。","respondent":"小林環境課長","answer":"そもそもまずは国がしっかり整備すべきものですが、区としても予算要求しながらというのが今までの状況かというふうに思っております。設置場所については区内で複数箇所設置するということが今検討で進められているところですため、国が今、検討を進めているところですので。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"今、また、航空機騒音に対しては４５デシベルを下回るようにということを発表しております。ＷＨＯとかの基準を超えるわけですから、これは引き続き注視していただきたいのですけれども、区としてはどのような態度で臨むのか尋ねました。","respondent":"小林環境課長","answer":"ＷＨＯなどからさまざまな情報が示されているところかと考えていますが、国は引き続き精査していくということを伺っておりますので、その精査の状況をしっかり動向を把握していきたいというふうに考えてあります。","id":"exchange-034"},{"speaker":"つる委員","kind":"質問","question":"２７５ページ、小児がん等で失われてしまった免疫のワクチンの定期予防接種の再接種に対する助成について何度か伺っておりますが。一般質問のときにも、どういうふうにすることによってそれが可能となるのか、その手続の部分について説明を求めました。","respondent":"鷹箸保健予防課長","answer":"委員ご指摘の小児がんなどで免疫の治療をされた方については、せっかくこれまでワクチンを受け続けてきたわけですので、これまでは対象ではなかった方を新たに区として対象とするというような要綱整備などの手続が必要かというふうに考えています。","id":"exchange-035"},{"speaker":"つる委員","kind":"質問・要望","question":"改めて求めたいと思います。その辺に関して、区として何らかの支援策として考えられるものがあるとすれば、どうしたことが想定できるのか、考えがあれば説明を求めました。","respondent":"仁平品川保健センター所長","answer":"アレルギー除去食品の区の支援の考え方ですけれども、そういう相談支援が我々の役目になっているのかと考えているところです。それぞれの判断基準をつくっていくのはなかなか難しいことかと考えているところですので、実際には難しいかと考えております。","id":"exchange-036"},{"speaker":"つる委員","kind":"質問・要望","question":"これはずっと求めてきて、東京都全体として都社協の場での対応等もしていただいて、一律３,０００円の助成がつきます。６０人が要再検査というふうになっている部分がありましたので、その辺をどのように周知啓発、また実施していくのか説明を求めました。","respondent":"仁平品川保健センター所長","answer":"この制度は４月１日から実施される事業になりまして、こういう助成制度が始まったので積極的に検査の勧奨を行っていきたいと考えているところです。既にもう４月以降の出産予定の方は、妊娠届出が終わっていらっしゃいます。","id":"exchange-037"},{"speaker":"つる委員","kind":"質問・要望","question":"そういうところでの支援策を私もずっと伺ってきた中で、そうしたリスクを未然に回避していくことの支援策にしてもらいたいという声も伺いましたので。２７８ページ、２９０ページ、町工場を営む方からいろいろお話を伺う中でこういう話がありました。","respondent":"山崎商業・ものづくり課長","answer":"企業立地継続支援事業というものがあります。こういった苦情などを環境部門で受けまして、私どもが騒音低減となるサッシの二重化などの工事費の一部助成というような具体的な助成制度はあります。","id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"２９０ページ、ぜひ産業経済費というか、商業・ものづくり課としての観点から支援の構築をぜひつくってほしいと求めました。これは私は１つのポイントとして、また民間も含めた枠組み、そうした検討があれば説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"そうした国が推奨する一定比率の雇用も１つの課題だというようなところでお話をお伺いする機会が多うあります。そうした障害者の方の雇用の条件といいますか、これを同時にご理解を賜るような啓発というようなところで今はやらせていただいているような状況です。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"もう少し大きい枠組みという部分でお聞きしたので、また改めて機会があれば伺っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"芹澤委員","kind":"質問","question":"私からは、２９５ページ、知的財産権取得支援、２９７ページ、五反田バレー情報発信についてお伺いいたします。これから予算執行ということで非常に期待しておりますが、まず五反田バレーの範囲についてお伺いいたします。","respondent":"山崎商業・ものづくり課長","answer":"したがいまして、丁目などで区切るような、そうした明確な基準は持ってございません。一般的にはまだ小規模の事業所、いわゆる２０人以下のベンチャー企業が多いというようなところで捉えているところです。","id":"exchange-041"},{"speaker":"芹澤委員","kind":"質問","question":"支援項目に著作権も含むべきなのかと考えておりますが、まず支援項目を絞った理由を伺わせてください。周知させるという意味合いでは、著作権をやはり含めるべきなのかと思うのですが、なぜ絞ったのかという理由をあわせて説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"企業の知的財産を取得する支援の理由です。ご支援をさせていただいているということと、それから実用新案というような分野も含めて支援をさせていただいているというようなことであります。","id":"exchange-042"},{"speaker":"芹澤委員","kind":"質問・要望","question":"現在の周知方法をまずお聞かせいただきたいのと、人から案内があるべきかと思いますが、ご見解をお聞かせください。企業だけではなく、五反田というまち、品川区という自治体のブランディング向上を図ることも検討してはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"東京商工会議所品川支部などの集会の機会で積極的にＰＲを図るというようなことを引き続きやってまいりたいと考えております。こちらの東商も賛助会員として近々加わるというようなことを区のほうでコーディネートをさせていただいているようなところです。","id":"exchange-043"},{"speaker":"おくの委員","kind":"質問","question":"私は区民の皆さんの声をなるべく直接に伺いたいのと、都合のつく限り参加しようと思い、このうち５回の説明会に参加してきました。区は、この点について、どのような対策、対応をお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"Ｌｄｅｎ６２を超える場合は対象ということで、今回、品川区内の住宅があるエリアにはかかってこないというお話でした。区としましては、この案が当初出た当時から、住宅も含めたさまざまな騒音環境軽減に向けた取組みを国に求めてきたです。","id":"exchange-044"},{"speaker":"おくの委員","kind":"質問","question":"そう考えると、建物の防音工事をしさえすれば、騒音問題は解決するというわけにはいかないのではないでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"これまでは飛行回数、国は平成２９年４月から、環境に配慮した飛行機を使う場合は使用料を軽減するというような取組みも開始しています。そうした総合的な取組みを区では求めておりまして、国でも今、実施あるいは制度化してきているところです。","id":"exchange-045"},{"speaker":"おくの委員","kind":"質問","question":"それで、もう１つ伺います。伺います。","respondent":"鈴木都市計画課長","answer":"教室型説明会では、具体的にどれぐらいの音か、どこに行けば体感できるのかというようなお尋ねもございました。歩行に困難が生じるとか、そういった声は、伊丹に確認したところではなかったです。","id":"exchange-046"},{"speaker":"おくの委員","kind":"質問・要望","question":"６回目の第三日野小学校の説明会では、健康診断を五反田あたりでもやってほしいのだという要望も住民の皆さんから出されたように記憶しております。そういう健康問題に関するご要望に関して、区としてはどのように考えておられますか。","respondent":"小林環境課長","answer":"過去の飛行ルートの関係というところもございまして、大井第一地区を対象に、空港振興・環境整備支援機構が実施しています。引き続きそれについては拡大、拡充等を検討していきたいですので、その動向はしっかりと区としても把握していきたいと考えています。","id":"exchange-047"},{"speaker":"おくの委員","kind":"質問","question":"今伺った範囲内で、不十分な国交省の説明に対して、非常に怒りが高まっていく様子が私には見てとれたのです。それを言って終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"木村委員","kind":"質問・要望","question":"総合事業へ移行するにあたり、地域特性に合わせた事業展開が求められています。本区としては、区民の皆さんにどのような行動や考え方を期待しているのか尋ねました。","respondent":"川島健康課長","answer":"それを支援するために今一番推奨している事業が、ウォーキングマップをつくったり、しながわ健康ポイント事業も歩くことを促す事業です。そういった考えで事業を行っているものです。","id":"exchange-049"},{"speaker":"木村委員","kind":"質問・要望","question":"適度な飲酒ということですね。今お答えになったことを、区民の皆さんにしっかりと指導してほしいと求めましたが、その方法があれば説明を求めました。","respondent":"川島健康課長","answer":"先ほども申しましたが、まずは歩くことは気軽にできて誰でもできるというようなところですので、それをやるきっかけとなるような事業は健康づくり支援事業の中で幾つかご提案させていただいているところです。","id":"exchange-050"},{"speaker":"木村委員","kind":"質問・要望","question":"それは区民の皆さんに直接届かなければ、宝の持ち腐れになってしまいますので、ぜひ区民の皆さんにお伝えほしいと求めました。まずは行動を起こすことが必要ですけれども、どうすれば重い腰を起こすことができるのか、何か策があれば教えてほしいと求めました。","respondent":"川島健康課長","answer":"例えば、気軽に運動する場として、健康センターを２カ所設けてあります。インセンティブが付与されるということで、運動するきっかけ、後押しになるようなものではないかと考えています。","id":"exchange-051"},{"speaker":"木村委員","kind":"質問・要望","question":"なぜ健康が必要なのか、自覚していただくことが一番大事ではないかと思います。よき指導をお願いしたいのですが、何かもっともっと区民の皆さんの心に入っていく指導の仕方が何かあればお話をほしいと求めました。","respondent":"川島健康課長","answer":"非常に難しいところでもあるのかという気がしますが、常に新しい事業だけではなくて、いろいろ運動するきっかけになるような事業をご用意して、それを利用していただけるように周知をすることに努めてまいりたいと思います。","id":"exchange-052"},{"speaker":"木村委員","kind":"質問","question":"年間約３万人、平成１０年が２,７４０人ということで、２,５００人から２,９００人の横ばい状態で推移しているということをお聞きしました。本区でも自殺者数の横ばい状態が続いていると思いますけれども、平成３０年度の品川区での自殺者数がわかれば説明を求めました。","respondent":"鷹箸保健予防課長","answer":"自殺者の統計ですが、平成３０年度については、まだ集計中でございまして、一番直近のところでは、平成２９年度になりますけれども、５９名です。５９名が自殺で亡くなっていらっしゃいます。","id":"exchange-053"},{"speaker":"木村委員","kind":"質問・要望","question":"品川、荏原両医師会、区内の４警察署が参加して、今後の取組み方や方向性、内容について検討があったということをお聞きしております。そういう点におきまして、先ほどから何度も答えていただいておりますけれども、本区の考えをぜひお答えをほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"来年度には品川区の自殺と現状などをしっかり検討した上で、新しい品川区独自の自殺予防対策計画を策定していく予定にしています。現在、保健予防課だけではこの問題に対応できないことは明らかですので、経済対策も含めて全庁を挙げて自殺予防に取組んでいるところです。","id":"exchange-054"},{"speaker":"木村委員","kind":"質問・要望","question":"いかに品川区が悩んでいる方々に対して、上手にフォローしてあげることができるかどうかではないかと思います。ぜひ行政としても頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問","question":"２８１ページで、体験型環境学習施設のことを伺います。この点を伺えればと思います。","respondent":"小林環境課長","answer":"こちらに来た方がそちらのほうに行っていただくような仕組みづくりも今後検討できればというところで考えていきますと。特にこの施設、具体的なところにつきましてはこれから細かく検討していくつもりではありますが、地域のニーズの把握しながら考えていきたいです。","id":"exchange-056"},{"speaker":"渡辺委員","kind":"質問","question":"それに関連して２点ほど伺います。そういう意味では、建てる際に、行政施設として多機能的な利用、この辺をまず所管の範囲で構いませんので、どう考えているか説明を求めました。","respondent":"小林環境課長","answer":"授業の一環でも使っていただきたいというところで、委員のほうからご紹介ありましたような多目的室というのは整備する予定で考えてあります。この施設、環境だけではなく、地域とともにある施設として考えていきたいというふうに考えてあります。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問","question":"２８５ページのプラスチック容器中間処理経費、あわせて２８５ページ、普及啓発費からお伺いしたいと思います。１番目は、プラン２１中間評価について、品川区版のがん対策総合推進計画について伺いたいと思います。","respondent":"川島健康課長","answer":"こちらは今、委員がおっしゃったとおり、しながわ健康プラン中間見直しの予算の中にこちらが組み込まれているです。予算はそのような形ですが、独立したがん計画ということでしっかりつくっていく予定で、今、準備しています。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一般質問、また決算特別委員会でも改めてしつこいくらい確認をさせていただいたのですが、そこのところを確認させていただきました。効果的なものを策定していただきたいというお願いをさせていただいたのですけれども、現段階でお答えができれば教えてほしいと求めました。","respondent":"川島健康課長","answer":"がん計画の策定にあたりましては、がん対策推進計画策定委員会というものを設けまして検討していくということです。専門家の方に入っていただきまして検討していく予定で、今、準備をしています。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私もここでは伺いませんけれども、先ほども午前中に質問がありましたが、ぜひ横串を差すような総合計画をつくってほしいと求めました。できればかかわっていただきたいという思いで質問しているのですが、その辺の意識について伺いたいと思います。","respondent":"川島健康課長","answer":"区役所の内部の委員がどの課になるのかはこれから検討していくというところですので、いろいろな要素が入ってくると思いますので、それはこれから考えさせていただければと思います。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問・要望","question":"予防接種費のところで、ワクチンスケジューラーアプリ、しながわ予防接種ナビについて伺いたいと思います。昨年１１月から現在までに、これを登録されている方が何人いるのか、わかれば教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"当初は今年度７月にスケジュールアプリを開始するということで準備を進めていたところですが、両課、その話を進めてきました。親御さんの端末に情報が届く、うまく接種が終われば次に、例えば体調が悪くて予定していた接種日に接種できないと。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１つは、要望なのですけれども、今までどういうものを受けましたかという並びが違うということ。できるだけここは使いやすいような形にしてくださいというような要望があったのですけれども、これについて何かご検討いただけないか尋ねました。","respondent":"鷹箸保健予防課長","answer":"予防接種が定期化された数が多いものですから、ちょうどこの５年ぐらいで母子手帳の予防接種の並びが変わっているのは委員ご指摘のとおりです。昨年１１月に導入を始めたということで、わかりにくい場合は、ぜひ保健所にお問い合わせいただければと考えています。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まだ始まってから４カ月ぐらいですか、ですから、要望として。今の時代、求められているのではないのかと思うのですが、その辺の見解について伺いたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"確実に国内で処理されているですので、そういったこともわかりやすく伝えてまいれば、もう少しご理解が進むかというふうに思ってあります。検討してまいりたいと思ってありますので、ご理解のほど、よろしくお願いいたします。","id":"exchange-063"},{"speaker":"あくつ委員","kind":"意見","question":"絶対に変なところには流れていないというところをお話をしていただければ、おそらくリサイクルの分別等のより強いモチベーションになるかと思います。今も努力はしていただいているとは思うのですが、さらなる見える化をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"２７３ページ、また２９０ページ、産業経済費にかかわって消費税１０％への増税による区内への影響について伺います。この健診が２０歳から７０歳に拡大されておりますが、歯並び、かみ合わせがあるのか伺います。","respondent":"川島健康課長","answer":"品川区の成人歯科健診の検査項目ですけれども、その他の所見というところで、歯列咬合という部分がございまして、記録表が区に回ってくるような形になっております。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"この健診項目に入っている理由と、歯列咬合を治すために矯正することで、何が改善されるのか伺います。","respondent":"川島健康課長","answer":"やはり物を食べたりするのが食べやすくなるですとか、発音の状態ですとか、いろいろ影響はあるのだと思いますが、その影響があってどうなるのかという詳しいところはまだ私ども把握していないところです。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"子どもにとっては職業選択にも影響します。健診で矯正すべきと言われる人は、どのくらいいるのか伺います。","respondent":"川島健康課長","answer":"矯正すべきという報告の上がり方ではなくて、所見の有無のみということになります。正確な数はまだわからないということですが、今後は数が積み重なっていけば、経年でどうなったかということがわかるような形になる状態です。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"区内のあるお子さんは、治療開始時に約１００万円、また、受診するごとに５,０００円かかるので、大きな負担だという話を伺いました。区は、矯正治療の保険適用の必要性をどのように認識しているのか伺います。","respondent":"川島健康課長","answer":"私どもの立場としますと、保険診療に適用されるかどうかというところはなかなか踏み込めない部分です。どうしていくべきかという部分はなかなかお答えしかねるです。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"その後の治療費なども少なくて済むと思いますし、そういったところでぜひ国に歯科矯正を保険適用してほしいと要望してほしいと求めましたが、いかがか尋ねました。","respondent":"川島健康課長","answer":"ただ、それも指定歯科で、区内には２カ所しかないのですけれども、指定歯科で治療した場合は保険診療が認められるという形になっております。それ以外の部分はなかなか判断が難しいところだと考えています。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ国に５０項目以外も歯の矯正のところも保険適用されるように求めてほしいと求めました。子どもの保険適用を特にぜひやっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"いわゆる医療が必要な病気を５０疾病という形で指定されているというところですので、見た目ですとか、そういった美容面の話とはまた別物になるです。話は違ってくるとは思いますけれども、現状、何か問題意識を持ってやるというようなところでは考えてございません。","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"続いて、消費税の区内への影響について伺いたいと思います。そういった中で、なぜ高くないのか改めて伺いたいと思います。","respondent":"品川財政課長","answer":"なぜ高くないのかというところですけれども、そもそも消費税自体が消費に合わせた形で広く薄く税をとるという趣旨のものですので、高くなるという意味はよくわかりませんが、税の趣旨としては、間接税というような形でとるものです。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"薄くというところで、やはり低所得者のところに負担割合が多くなるというところで、これは重い税制だと考えています。区内への影響はどういったものを考えていらっしゃるのか伺いたいと思います。","respondent":"品川財政課長","answer":"区内への影響ですが、当然、過去の消費増税を見れば、消費が落ちるというような傾向が出ていたということは事実かと思います。これに伴いまして、当然、区のほうでもプレミアム付区内共通商品券等対策を打ち経済対策をしっかりとやっていくという方向性で現在進めております。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり増税すると消費が落ち込む、そういった中、区内でも消費が落ち込み、廃業になってしまうという商店もあるかと思いますけれども、この間、８％に増税したときに、区内の商店、空き店舗になってしまったという数がわかれば教えてほしいと求めましたし、増加傾向にあるのか伺います。","respondent":"山崎商業・ものづくり課長","answer":"そこの部分につきましては、今回の国のほうの対応を伺いますと、そうした部分については、しっかり対応していくのだというようなところです。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"今、景気が下がってきているというふうに内閣府のほうでも見ているということだと思いますけれども、回復していないのではないでしょうか。伺います。","respondent":"山崎商業・ものづくり課長","answer":"平成２９年３月に、品川区産業支援施策調査分析最終報告書（商業編）、２０年間の消費の動向を考察しているところがあります。したがいまして、そうした全体の傾向と、今回の消費税が直接直ちに一致するものではないというふうに区としては受けとめているところです。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"消費税の増税で消費が冷え込んで区内の商店などにも大きな影響があると思いますので、やはりそういった面で商店街を守るためにも、消費税の１０％への増税はやめるべきだと国に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"品川財政課長","answer":"これは何遍も申し上げているとおり、国の所管事項ですので、区としてのコメントは差し控えします。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問","question":"２９７ページ、モンゴル高専について、それと３０１ページ、消費者センターについて。支援策も４項目書いてありますけれども、在留資格取得に向けた支援をするというのは、具体的に何をどういうふうに支援するのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"モンゴル高専の卒業生が区内中小企業に就職をする際には、在留資格、いわゆる就労ビザが必要になります。こうしたものの調整ですとか、そういったものに支援を行おうというようなことで、受け入れ側の企業に対して支援を行うというような中身です。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問","question":"日本の法律の中には、大学卒業の資格を持つ者ということが書いてあります。これは高度人材ということで認定をされて、そういう扱いで入ってくる、こういう理解でよろしいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"外務省などにも確認をしておりますが、初めての手続というようなことになりますので、ここは慎重にしっかり対応していこうというようなことで考えているところです。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"どこまで区が発給元、許可元である国に対して物を言うことができるのか、その辺の見解をお伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"外務省あるいはモンゴル大使館、こうしたところに公式に要請を出し、Ｑ＆Ａを繰り返しというようなことをさまざまやっております。今回、そうした一連の流れに沿う形で、今回の事例については大学と同等のというような内諾を得ているような状況になっております。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問・要望","question":"まだこの質問は終わりません。モンゴルの人材だけでは到底まかない切れないところもあると思うのですけれども、そこら辺の見通しはどのようにお考えか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"モンゴル高専は、１つ品川高専との関係もありまして、日本式の高専をモンゴル国につくるというようなことです。品川区としましては、今後そうしたところの推移を考えながら、本事業にしっかりと取組んでまいりたいと考えているところです。","id":"exchange-079"},{"speaker":"大沢委員","kind":"質問","question":"消費者センターに移りますけれども、消費者センターのそもそもの役割は何でしょうか。説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"いわゆる区民の方が消費活動を行うために必要な基本的な知識を身につけていただく、わかりやすい言葉で言いますと、しっかり皆様賢い消費者になりましょうと、こういうようなところで啓発事業などを行っているです。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"その賢い消費者が、今、特殊詐欺事件等々に非常に巻き込まれているわけでありまして、消費者センターはどこまで介入できて、どこまでの役割を担うことができるのか、それを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"こうすればいいのだなということで、要は、相談の大体７割がそういった形で相談した内容を自前で解決をしていただくようなことがあります。残りの３割につきましては、つなぐというようなところで対応させていただいているというようなところです。","id":"exchange-081"},{"speaker":"大沢委員","kind":"質問","question":"今、２つ言葉がありました。何らかの一定のポジティブリストのルールをつくってこれを運用していくということは、私は大事だと思うのですけれども、そこのところいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"確かに相談を受けて対応するという以外に、現状、連携をさせていただいているところもあります。消費者センターとしましても、そういったものを提示しながら適正に業務を行っていく必要があるだろうというふうに考えているところです。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"先ほど、警察との連携がしっかりできているのであれば、警察はポジティブリストのルールに基づいて動いているわけですから、それを応用、あるいは外に枝分けしたルールに基づいた強化を望みます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２９３ページ、雇用確保支援事業、自動化・ロボット化導入推進事業についてお尋ねします。そういった観点からＲＰＡを本格的に導入していただきたいと、平成３１年度は実証実験ということを伺ったのですが、そういったやりとりがありました。","respondent":"山崎商業・ものづくり課長","answer":"製造業をはじめ、各業種において、現在、人手不足が重要な経営課題になっております。企業の業務効率の向上、あるいは企業競争力の維持強化を図る、こうしたことを目的に実施をするものです。","id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"質問","question":"区内の中小企業、とりわけ小規模の事業者への導入推進は、具体的にどのように進めていかれるのでしょうか。その点についての支援も含めてお願いいたします。","respondent":"山崎商業・ものづくり課長","answer":"こういう意味では、いわゆる丁寧な伴走型の支援をすることによって導入に向けて動機づけを行っていくようなところが必要だと考えております。これまで区が持っているカタリストの情報などを総動員して、これは区として支援をしていこうというようなところで考えているところです。","id":"exchange-085"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、かなりお話がありましたけれども、何をどういうふうに進めたらいいかという、そこから始まる方が多いかと思うのです。それからマッチングについて、どういう形で小規模事業者の経営者とマッチングさせることをしていくことを支援していくのか、お願いしますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"今、区の内部と、それから本件事業はかなり専門的な知識を持った委託事業者と組む予定です。東京商工会議所品川支部などを通じてしっかり情報を流して、確率の高いマッチングを組んでいこうというようなところで考えているところです。","id":"exchange-086"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど、ほかの委員からもあった五反田バレーとの関係や、そういったところでやはりそういった企業を開拓していっていただけるということです。こういったマッチングにあたって業務委託される事業者がいらっしゃるということもお聞きしておりますけれども、計画がありましたら、お願いします。","respondent":"山崎商業・ものづくり課長","answer":"３０ほどの大学のそういった知見をこの事業者が持っておりまして、品川の小規模事業者に対する伴走型の丁寧な支援につなげていくというツールを持っておりますので、しっかりと支援ができる体制を整えて実施しているというようなところです。","id":"exchange-087"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ一方で、コーディネーターの電通大の関係の会社だと思いますが、そちらとの連絡調整もきちんと区として行っていってほしいと求めました。最後、その点だけお聞きします。","respondent":"山崎商業・ものづくり課長","answer":"いろいろ専門的な領域の支援は、なかなか区のほうも頑張っておりますが、やはりそうした知見をうまく組み合わせ利用し、効果的に中小企業支援にマッチングさせていただきたいというふうに思っております。","id":"exchange-088"},{"speaker":"いながわ委員","kind":"提案","question":"それと２９１ページ、２９７ページの商店街活性化事業費全般について、提案も含めてお伺いしてまいりたいと思います。あるお店はクレジットカードの手数料だけで年間１００万円を超えるという、そういった地元の飲食店もありますので、いかがか尋ねました。","respondent":"川島健康課長、山崎商業・ものづくり課長","answer":"こちらは考え方が５年に一遍ということではありますが、５年の健診の機会に歯科医院にかかっていただきまして。例えば受診券なしで、やはり委託料の持ち出し等大変多くなるということで… 区としましては、そうした小規模事業所に焦点を当てた支援、これをメインで考えていかなければいけないだろうというふうに思っているところです。","id":"exchange-089"},{"speaker":"いながわ委員","kind":"提案","question":"では、そのお耳に、ぜひ私も提案させていただきたいのですが、今、品川区は制度融資を行っていて、本当に助かっている企業が多くあると思います。悪いときを乗り切っているわけですから、そういったところに利子補給だけでもするべきだと思っているのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"区の制度融資でお借りして返済をしていただいている企業につきましては、利子補給をしっかりさせていただいてあります。借り換えなども条件がいろいろありますが、そうしたこともいろいろ見直しをしながら最適な融資制度を保っていく必要があるかと思っているところです。","id":"exchange-090"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"平成３１年度は４４４万９,０００円で、その理由を教えていただきたいのと、今後の進め方について教えてください。この辺の理解がされているのか、ごみの出し方がそういう方たちにちゃんと理解されているのかどうか、その辺についても説明を求めました。","respondent":"川島健康課長、仁平品川保健センター所長、工藤品川区清掃事務所長","answer":"区の対応としましては、健康課に担当ができる予定ですので、飲食店等の対応も健康課で行っていくことになろうかと思います。私どものほうにも配られるので… 私から、食から子育て支援事業の昨年度との予算の違いについてご説明します。ただ、見直しをさせていただきまして… ２つあろうかと思います。今、民泊事業者が増えてありますので、その事業者のほうにもそのような形で働きかけをしています。","id":"exchange-091"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"離乳食教室を役に立てていただきたいと、これは要望にしておきます。ほかでも民泊事業者によるそのようなことはないのかどうか、そういう指導はほかであったのかどうか確認させてください。","respondent":"川島健康課長、工藤品川区清掃事務所長","answer":"２０２０年４月から始まりますが、こちらの予算については別途、１年間かけて検討した上で要求させていただこうと考えています。それから、都条例に基づく上乗せの部分の事務につきましては… ２件につきましては、完全に問題は解決されておりますが、１件につきましては、まだ特定はされないというところで、引き続き調査をしているです。","id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから、ゴミ回収のほうは、いろいろこれからも頑張ってほしいと求めました。資源化センターについてちょっとお聞きしたいのですが、東品川船舶中継所、何か進捗があったら説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"ペットボトルの処理の処理能力をかなり超えているということで、来年度、少し人員等の増強を図るということで予算を増やしています。東品川船舶中継所の件につきましては、今、さまざまな方法、直接輸送するのか、また代替地かというところでさまざま検討をしています。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから２６７ページの健康塾、２９７ページ、お伺いしたいと思います。予約がなかなかできないとか、後回しにされてしまうとかという問題もあるというところで、このことについての状況を伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"そうすると、どこで受けられるのかというようなお問い合わせが区民の方から実際に保健所のほうにも寄せられたことはございました。どこに集中していたという個別の情報については把握してございません。","id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"そういうことが新宿区の場合はあるのかというところをお伺いしたいと思います。もしそういうことのあるなしとは別に、品川区内で価格の均一化みたいなことは、何か考え得ることがもしあるのであればお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"新宿区の１,７００円がどうしてということのお尋ねですが、申しわけありません。新宿区の１３歳未満の自己負担額についての詳細は把握してございません。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問","question":"では、このあたりのことについては、実情がどうなっているかということは今ご説明いただきましてわかりました。６５歳以上の高齢者のインフルエンザ予防接種についてですが、どういうふうに区として評価あるいは感想等をお持ちなのかお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"６５歳から６９歳のところが１９％とかなり低いのですが、例えば９５歳から９９歳ですと８０％とか、年代によって接種率が違うという現状があります。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問・要望","question":"７５歳以上というところで、年齢を区切って全額無料にしているという区もあります。考えていただいて、今後の接種率向上を図るための対策ということで、お考えを最後にお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"高齢者のインフルエンザについての自己負担部分について、プラスアルファで助成をしているという区が幾つかあるところは確認しています。現在、９,０８０万円ぐらい毎年かかっている部分もありますので、これも含めて今後の検討課題とさせていただきたいと思います。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。区内２３カ所で実施されていまして、２３カ所の会場によってのばらつき、低いところでどれぐらいの幅があるものなのかお伺いしたいと思います。","respondent":"川島健康課長","answer":"半年で１クールという形になっておりまして、今年は参加していただいた方が２,１８７人で、落選された方が２１７人です。そうはいいましても、やはり抽選に落ちる、連続で落選される方もいらっしゃいまして、その辺の話は私どもの耳にも入ってきているところです。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問・要望","question":"できるだけその辺の案内というのか、情報提供といいますか、せめてそこのところはしっかりとやってほしいと求めました。その辺の情報提供をしっかりしていただきたいというところで、どのような対応が考えられるのかをお伺いいたします。","respondent":"川島健康課長","answer":"こちらはお問い合わせをいただいた際に、より丁寧な対応に努めて、抽選漏れになった方の利便性にも配慮した形で、丁寧なご案内に努めていきたいと考えています。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"平成２９年３月に、品川区産業支援施策調査分析というすごい報告書が出ていまして、そこにも記されております。産業支援施策調査分析のところでいろいろ述べられている部分がありますけれども、現状、どのような形で進捗しているのかお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"これまでの行政の個店支援につきましては、これはマイスター店をはじめとしまして、さまざまな角度でＰＲ事業をやってまいりました。そうした１つの個店が面的な効果を生むような、今、いろいろ商連などと連携しながら取組みをさせていただいているような状況です。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問","question":"品川健康センターのジムを利用するある７０歳の方にお話を伺いました。こちらの利用料金の設定の根拠について伺います。","respondent":"川島健康課長","answer":"健康センターの利用料につきましては、条例に基づいて規定しています。","id":"exchange-101"},{"speaker":"安藤委員","kind":"質問","question":"ひどすぎないですか。、答えるよう求めました。","respondent":"川島健康課長","answer":"失礼いたしました。こちらはワンコインということで、荏原のほうは施設の規模が少し狭いということで１００円安くした、そういうふうな設定をしているものです。","id":"exchange-102"},{"speaker":"安藤委員","kind":"質問","question":"渋谷でも利用料金は４００円のうえ、中学生は１００円、６０歳以上と障害者は無料。健康センターのトレーニングジムの利用料は、高齢者や障害者は免除や値下げをすべきだと思いますけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"こちらは時間制限がないということで、１日利用できますので、現状でも十分なお安い価格だというふうに考えております。受付のときの確認事務が新たに発生するということで、その辺の経費も見込まなければならず、なかなか難しいのではないかと考えています。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、品川区内の年間の殺処分数と譲渡の数はどうなっていますでしょうか。区民から品川区保健所などに引き取ってほしいと申し出があった場合、どのような対応を行っているのか伺います。","respondent":"鈴木生活衛生課長","answer":"それから、猫は、都全体で２４７件の譲渡がされておりまして、区内で譲渡の実績はございません。対応、そちらをご相談者にご紹介をして、適切な対応をお願いしています。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいと思います。収容した動物はどうなっているのか、それぞれ伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"致死処分に至ったものが合計で４００件ちょっとですので、引き取りをされたもの以外は、最終的には処分をされているというのが現状となっております。都では、そういう民間の里親を探しているＮＰＯだとか団体との連携をしながら譲渡先を探しているというふうに聞いております。","id":"exchange-105"},{"speaker":"安藤委員","kind":"質問","question":"この点の周知について、品川区としては、現在、取組んでおられますでしょうか。伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"ペット等の飼えなくなったときの対応等についての啓発ですが、都のほうでホームページや広報、さまざまな機会を捉えて周知をしています。区のほうでは、区民の方向けの講習会や、いろいろな啓発の冊子、パッフレットの中でご紹介をしているというのが現状です。","id":"exchange-106"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が確認した限りでは、譲渡というところでは、まだまだ周知が弱いというふうに感じました。周知をもう少し強めていくことを求めたいと思いますけれども、ホームページの工夫なども含めて求めますけれども、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"確かに対応が必要な犬猫の譲渡というのは重要なことでありますが、その前に、飼い主が責任を持って最後までしっかりと飼うということが前提です。区としては、そちらに対する啓発等に力を入れて取組んでいるところです。","id":"exchange-107"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺います。こうした活動に取組んでいる区内の団体の連携を強めて、公的な支援を強めるべきだと考えますけれども、いかがか尋ねました。","respondent":"鈴木生活衛生課長","answer":"動物愛護相談センターのほうで、各団体との連携を行っておりますので、品川区が直接やりとりをすることは現在行っていないところです。","id":"exchange-108"},{"speaker":"本多委員","kind":"質問","question":"２７９ページ、保健衛生費の食品衛生についてと、２８９ページ、東京二十三区清掃一部事務組合分担金について質問します。それと、２３区の分担するべきことと、一部事務組合の自助努力や運用へのかかわりについて、その点について説明を求めました。","respondent":"鈴木生活衛生課長、工藤品川区清掃事務所長","answer":"平成３１年度につきましては、国のほうの法改正に伴いまして、食品関係の衛生管理の制度が新しく始まります。その対応のために専門非常勤の職員を現在の３名から５名に増員の必要がありまして… 分担金の考え方といたしましては、大きくは清掃工場の運営というところでございまして、清掃工場は今２１カ所あります。こちらを２３区の中で共同処理する、そういった考え方のもと、分担金を支出しているものです。","id":"exchange-109"},{"speaker":"本多委員","kind":"質問・要望","question":"食中毒に関連して質問していくのですけれども、都内で昨年、食中毒が１８５件起きました。最近１０年ではワースト１ということで伺っておりますけれども、区内の状況と、アニサキスによる食中毒の状況を教えていただきたい。","respondent":"鈴木生活衛生課長、工藤品川区清掃事務所長","answer":"平成３０年度につきましては１３件、そのうちアニサキスが４件と、やはりこれは都内全域と同じ傾向でアニサキスによる食中毒が増えているところです。その辺の症状が多いのですが、特別な重篤に至るケースはまれでございまして… 経営努力というところでは、清掃工場等の運営費で、民間のほうに施設の委託をしまして削減に努めているです。","id":"exchange-110"},{"speaker":"本多委員","kind":"質問・要望","question":"そういった場合の対応をどうすればいいのかお知らせいただきたいのと、清掃一部事務組合のほうは、わかりました。やはり２３区が負担しているのだなと思うのですけれども、発電した電気の取扱い方について、今後何か展開があるのかないのか説明を求めました。","respondent":"工藤品川区清掃事務所長、鈴木生活衛生課長","answer":"清掃一部事務組合は売電収入というものを収入源として、力を入れてあります。その量につきましては、年々増加しているですので、そういった収入を経営に資しているというのが清掃一部事務組合の考え方です。 食中毒による重症化の場合、基本的には医療機関の受診に基づく情報からですので、医療機関のほうで適切な対応をお願いしつつ、区のほうから調査の協力のお願いをしています。","id":"exchange-111"},{"speaker":"松永委員","kind":"質問","question":"私からは、２６７ページの禁煙外来治療費助成について、２８１ページのミスト発生装置設置助成について伺います。今までどのように区民への周知を行ってきたのか尋ねました。","respondent":"川島健康課長","answer":"今年度、医療機関に直接お知らせを配るようにさせていただいたところ、禁煙外来治療費助成の申請をする方が増えてきております。これを機運として１００人の方、ぜひ禁煙したいという方の支援をしたいということで、予算額を倍増したものです。","id":"exchange-112"},{"speaker":"松永委員","kind":"質問・要望","question":"私は、こうしたことをしない限り、区民への周知は難しいと考えます。禁煙されている方がターゲットであると考えますので、ぜひご検討をしていただきたいのですが、いかがか尋ねました。","respondent":"川島健康課長","answer":"工夫できる部分でやっていきたいと考えていますので、そのステッカーを貼るかどうかというのは別としましても、周知は強化していきたいと考えています。","id":"exchange-113"},{"speaker":"松永委員","kind":"質問・要望","question":"ホームページを確認しましたが、現在、定員５０人で、来年度は１００人とお聞きしましたが、定員数は、どのように決められたのでしょうか。本区内の喫煙者数は全国平均を約３％上回っており、定員数を増やすことも必要であると考えますが、本区の今後の方向性について改めて伺います。","respondent":"川島健康課長","answer":"他区も最初は５０人からスタートしているところが多かったということで、だんだん増やしていければというふうに思っているところです。","id":"exchange-114"},{"speaker":"松永委員","kind":"質問","question":"次に、２８１ページのミスト発生装置設置助成の１,００２万１,０００円について伺います。このミストの発生装置は、夏場のみの装置なのか尋ねました。","respondent":"小林環境課長","answer":"人の暑さを少しでもやわらげる対策として、細かいミストを発生させる装置を設置する場合に、設置費用の２分の１を助成するといったような仕組みです。","id":"exchange-115"},{"speaker":"松永委員","kind":"質問","question":"これは民間で設置する場合は２分の１補助が出ると伺いました。初めに、このメンテナンスや光熱費は、年間どのくらいかかるのか尋ねました。","respondent":"小林環境課長","answer":"こちらは特に東京都が先行してこういったような事業を進めているところでございまして、およそ年間１５万円から２０万円程度かかると言われており、これがかかるコストの捉え方かと伺っているところです。","id":"exchange-116"},{"speaker":"松永委員","kind":"質問・要望","question":"このミスト発生装置でありますが、例えば、商店街の方々が活用したいといった場合は可能なのでしょうか。これは民間扱いになるのかお知らせほしいと求めました。","respondent":"小林環境課長","answer":"このミスト発生装置の対象ですが、人が自由に出入りできる場所というところで、例えばショッピングセンターの出入口、広場、公開空地、そこの中には商店街も含まれると考えているところですので、商店街についてもこの助成の対象になると捉えているところです。","id":"exchange-117"},{"speaker":"松永委員","kind":"質問","question":"なぜかといいますと、先ほど質問させていただきましたが、東京２０２０大会後のことも考えますと不安です。これは室内の場合の効果でありますが、本区として、屋外のミストシャワーを設置することで、どのような効果が得られると思うか伺いたいと思います。","respondent":"小林環境課長","answer":"今回、微細ミストとして助成を行うものにつきましては、一般的には外に設置すると冷房効果があるというふうに言われているところです。今後設置する事業者とともに、夏場以外にも何か検討できれば、また情報収集していければというふうに考えてあります。","id":"exchange-118"},{"speaker":"松永委員","kind":"提案","question":"最後に提案ですけれども、知名度を上げる効果もあると思いますので、ぜひご検討のほどお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問","question":"それを前提として伺います。３点指摘させていただきましたが、それも含めて次年度の事業に向けて、どのように検討しているか、ご見解を伺います。","respondent":"川島健康課長","answer":"今ちょうど、事業を実施した後のアンケートを集約しています。９０％の参加者の方が、継続意欲も高いというような話になってございまして、こちらは見直しさせていただければというふうに考えているところです。","id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこで検討をされていくのでしょうか。テーマの決め方について伺います。","respondent":"小林環境課長","answer":"こちらを基本に、特に環境分野における喫緊の課題であります温暖化対策は重めに置いていきたいと考えております。こういった区民の関心とあわせて、その状況にあわせた展示、講座、情報発信などを行ってまいりたいと考えております。","id":"exchange-121"},{"speaker":"吉田委員","kind":"質問・要望","question":"ＮＰＯ法人有害化学物質削減ネットワークが行ったアンケートによれば、一般的な家庭でも７割が有害化学物質を保持しているのが今の現状です。ぜひ地球温暖化だけでなく、有害化学物質削減をテーマとして取り上げていただきたいのですが、ご見解を伺います。","respondent":"小林環境課長","answer":"施設のテーマにつきましては、これから会を重ねて中身はしっかり詰めてまいりたいと思ってありますので、これからの調整だと思ってあります。日常の業務でもさまざま行っておりますので、広く視野を広げながら情報収集には努めてまいりたいと考えています。","id":"exchange-122"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ関心が高いところをテーマに取り上げるのだと言われれば、では、私たちが頑張って啓発活動もしなければいけないのだなというふうに思いましたが、ぜひ区としても、いろいろな知見を集めてテーマを決めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"私は、２７５ページ、保健衛生費の各種がん検診に関連して、それから２９３ページ、雇用確保支援事業に関連して質問します。メールを送るほうが、郵送よりもはるかに安いわけであるから、そういうことを検討していったらどうかと思うのですが、いかがか尋ねました。","respondent":"川島健康課長","answer":"今、３月の女性の健康週間にあわせて、子宮がん検診のご案内等を発送したりとかという処理をしたこともあります。郵送料等かかりませんので、こういうアプリ等を活用した周知ができないか、いろいろと検討していきたいと考えています。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"意見","question":"それによって、結果的に品川区民のがん検診の受診率が上がるということは非常にプラスになるから、そういうことについてのお考えをお聞かせください。お願いいたしますとの意見を述べました。","respondent":"川島健康課長","answer":"ただ、今ご指摘いただいたようなアプリですとか、最新のスマホのアプリ等を使った啓発の工夫は当然考えられると思います。パパママ応援アプリでも、対象者が少し偏りがあるのかというところもありますので、がん検診の受診率が上がるように努めてまいりたいと考えています。","id":"exchange-125"},{"speaker":"伊藤委員","kind":"質問・要望","question":"企業の自主努力を後押しする制度と考えるのですけれども、そうではなくて、企業は人材を求めているわけであります。個々の企業に対する具体的な支援活動を展開していくことが大事だと思うのだけれども、品川区のお考えと方向性を説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"これに注力をいたしまして、例えば年収の何割が経常負担として負担しないと採用ができないというような、そのような構図もあります。来年度、直接的に支援をさせていただければということで予算化させていただいている内容です。","id":"exchange-126"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今お話があった人材派遣事業や、いろいろなところと十分連携をとって、さらに実りのある施策を進めていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"石田（ち）委員","kind":"質問","question":"２９５ページ、就業支援事業について伺いたいと思います。現在もその認識は変わっていないのか、まず伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"雇用情勢につきましては、品川区も含め、国全体あるいは東京都全体でも、いわゆる雇用環境指標としての有効求人倍率の数字の推移などから判断しますと、雇用情勢については良化しているというような状況で捉えているところです。","id":"exchange-128"},{"speaker":"石田（ち）委員","kind":"質問","question":"働き盛りの２５歳から６４歳も２８万人増えていますけれども、半分以上が非正規雇用です。雇用環境の改善といえる状況ではないと思うのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"雇用情勢につきましては、有効求人倍率、それから完全失業率の動き、こうした指標を分析しますと、行政は良化しているという分析のもと、区としましても、さまざまな区の施策を考えるベースにさせていただいているところです。","id":"exchange-129"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"若手にも来てほしいというところでは、ぜひとも続けていくべきだというふうに思いますけれども、いかがでしょうか。区としては、それが、先ほどから質問もいろいろ出ています雇用確保支援事業のことなのか確認をさせてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"品川区として、若者の就労支援の事業についてより効果的な、政策をシフトしたというようなことを前回もご説明をさせていただいたところです。","id":"exchange-130"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"就業意欲がありながら正規雇用の機会を失ってしまった、または得られていない、そうした若者に対しての支援だったわけです。若者たちがまだ正規雇用を求めている状況を見れば、そして研修もする、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そうした若者の就業支援は、もう実施しませんということではなくて、事業の実施方法を組み替えて。いろいろハローワークと連携した就業の雇用の支援をさせていただいているところがあります。","id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ブラックバイトを「学生であることを尊重しないアルバイトのこと」と定義してから、２０１３年あたりからそういった言葉が出てきたと思います。ですので、ここにブラックバイトという文言や、学生も参加できる状況に工夫をしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"労働法に係るセミナーを、年間で１２回から１５回、そうした問題をテーマとして扱っております。労働相談情報センターとも連携しながら、しっかり検討させていただいて実施してまいりたいというふうに考えているところです。","id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひそうした若者たち、そしてさらには中高年層もパート・アルバイトのブラックに苦しむという状況がありますので、そうした状況を改善させるためにも、区としてできる対策、そしてこうしたセミナーを引き続き積極的にやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"若林委員","kind":"質問","question":"２６６ページ、健康推進費について、受動喫煙防止対策について伺いたいと思います。品川区で受動喫煙防止に責任を持つ所管、進めていく所管はどこになるのか説明を求めました。","respondent":"川島健康課長","answer":"受動喫煙対策の責任所管は、４月以降、健康課が組織をつくりましてやっていく予定です。","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、品川区には所管が違いますけれども、指定喫煙所が３つの駅の周辺にあります。今、どのように把握されているか、実態を捉えているかお聞かせほしいと求めました。","respondent":"川島健康課長","answer":"今、委員がおっしゃったとおり、個々の施設についてもどうするかです。その辺も私どものほうで情報を集めまして、情報共有を進めながら適切な形で対処していきたいと考えています。","id":"exchange-135"},{"speaker":"若林委員","kind":"質問","question":"屋外についても改めて健康課が４月１日から責任の所管課というところで、特に２０歳未満など、効果的に推進に努めるべきであるというようなことです。品川区としての制度的な、また組織的な大きな困難な壁があると思うのですけれども、ここについての見解を伺いたいと思います。","respondent":"川島健康課長","answer":"やはり施設所管課それぞれ適切な維持管理に努める中で、一番実態を知っているところになるということです。それから施設の管理は、やはり責任を持ってそれぞれの所管がやっていくということになりますけれども、その辺の取りまとめは健康課が行うです。","id":"exchange-136"},{"speaker":"若林委員","kind":"意見","question":"この問題は、受動喫煙についての視点は、これは健康推進部がしっかりとコントロールをしていかなければいけないのではないか。もう１回、ご答弁くださいとの意見を述べました。","respondent":"川島健康課長","answer":"屋外も屋内も全面禁煙になるというのが好ましいというふうには私ども考えてございませんので、そういう方針にのっとって進めていくというところです。","id":"exchange-137"},{"speaker":"若林委員","kind":"質問・要望","question":"受動喫煙、屋外でもパーテーションの問題もあるではないですか。組織のあり方については、連絡会、会議等でしっかりと議論を尽くしていただきたいとお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２８４ページ、やっと返還を迎えるというのが目の前に来ているわけですから、基本設計ぐらいはやったほうがいいのではないかということを言いました。我々は会派としては基本設計ぐらいまで進めてほしいという話をしたわけだけれども、もうちょっとわかるように説明していただきたい。","respondent":"柏原企画調整課長","answer":"設計というところまで進めてほしいというお話でございましたけれども、もう少し突っ込んだ形で深く検討をしたいというところがあります。密な検討を平成３１年度に進める中で、できれば、平成３１年度の中である程度具体的な形を示しながら進めていきたいというところがあります。","id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つぐらいはやはり一部事務組合で持っていたほうがいいという見解だけれども、し尿処理場の部分を、全体の清掃の話が見えてくるではないですか。そういうところの考え方をもう一度教えていただきたい。","respondent":"工藤品川区清掃事務所長","answer":"清掃工場内のいろいろな関係ですけれども、粗大の中継所につきましては、今、検討を進めてあります。そういった部分を申し入れていくとともに、そういった部分の可能性につきましても、いろいろと考えてまいりたいと考えています。","id":"exchange-140"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１点聞きたかったのは、２７９ページのアレルギー等居住環境調査、やらなくてはいけないのかどうか。そういう情報とか、そういうものを相談を受けたときに出せる状態になっているのかということもあるではないか尋ねました。","respondent":"鈴木生活衛生課長","answer":"区民の方から住環境に関するご相談等をいただいた中で、必要な場合に実施をしているものです。ただ、丸きり需要がないというわけではありませんので、毎年数回の検査を行うための予算を計上しているものです。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"意見","question":"ベニヤ系も使えないし、畳も添加物が入っているから和紙にするとか、全部そういう決まったものがあるわけです。こういうものをどうぞと言えばいいだけなのだから、ぜひそこら辺は考えてほしいと、お願いだけしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"私は、２９９ページ、プレミアム付区内共通商品券の発行助成についてお伺いいたします。区と国の考え方にこれだけ大きな差があるのですが、これをどう見ればいいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"少しこのあたり、事業をいろいろ進めていく中では、区民の皆様にも誤解のないように対応していかなければいけないというふうに思っています。委員おっしゃったとおり、低所得の方でありますとか、子育て世代の消費に与える影響緩和ということが国の目的かなです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"意見","question":"今はそういう状況ではありません。ご見解を説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"今申し上げた２つのことには、ポイント還元なども含めて、著しい影響が出ないようなことで国も対応していくのだというふうに聞いてあります。商業、商店街自体で全てできるというようなことで、さらなる消費喚起をこのタイミングで行おうというような考えに基づいて行うものです。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"これはあまりにもとんちんかんではないですか。やはりもっと身近な自治体は、区民にもっと身近な自治体である品川区は、もっと区民の目線で考えなければいけないのではないか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"品川区は大型店と連携しながらいろいろ事業は行っておりますが、この事業については、商店街のみの使用というところで特徴立ててやってきております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう本当にこの先、大丈夫か、やっていけるのかという状況になっている方は大勢いると思います。私はもっと品川区は区民に寄り添った施策をやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-146"},{"speaker":"石田（し）委員","kind":"質問","question":"２９１ページ、２７７ページ、同じく２７７ページの犬の登録・予防注射についてお伺いします。時間があれば、２９７ページの五反田バレーについてお伺いします。","respondent":"川島健康課長、鷹箸保健予防課長、鈴木生活衛生課長","answer":"公衆浴場支援に関するご質問にお答えいたします。出会いの湯マップが浴場案内みたいものになっておりますので、お客さんに配っていただくとか… 骨髄ドナー支援事業についてのお尋ねです。上限１週間で３万円を支給するという事業ですが、現状ではこれ以外について、区独自で行っているものはありませ… 区長が特に認めるものという項目がありまして、それを適用して事業をされているというふうに考えております。","id":"exchange-147"},{"speaker":"石田（し）委員","kind":"提案","question":"その中でも幾つかあったので、今日は、４つ提案をします。国や東京都でまず先立ってやるべきだというふうに思うのですが、提案をした５つは、区でも可能な内容だと思いますとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"もう１つ、それを区民の見やすいところに置いておいて、それを手にとって書いていただくというような普及啓発の取組み方になってあります。","id":"exchange-148"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望だけになってしまうかもしれませんが、私は、これは民間が主導でやるべきだと思っています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それで伺いたいのですけれども、１件当たり、医療機関に支払う額は幾らぐらいになるのかということが１点です。４５歳と５５歳だけというので、なぜ４５歳と５５歳だけなのか、この理由についても伺いたいと思いますとの意見を述べました。","respondent":"川島健康課長","answer":"医療機関に支払う単価は７,２７６円の予定です。それから、予算の１,９００人ということですけれども、こちらは対象人口の１５％の受診率を見込んで１,９００人という形で予算措置をしたものです。","id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは私たちが要望を受けてきたときに、高齢者ほど有病率が高くなっていくわけですから、なぜ４５歳と５５歳の２つの年齢だけにするのかというのは。２３区としては、対象者をどうしているのかということについても説明を求めました。","respondent":"川島健康課長","answer":"それから、他区の状況ですが、１１区ほどが実施しているような状況です。やはり初年度、まずこの形で始めさせていただいて、着実に実績を残してからどのようにするか決めていきたいというふうに考えております。","id":"exchange-151"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこういう形で高齢者のところまで検診が受けられるという形で増やしていただきたいということを強く要望しておきたいと思います。要治療は２０歳代、この方が治療に結びついているのかどうなのかというところを教えていただきたいのですが、どれぐらいの方が結びついているのか。","respondent":"川島健康課長","answer":"脂質異常というのも結構多いところです。それから、医療機関へつながっているかどうかというところは、そちらまで私どもでは把握できてございません。","id":"exchange-152"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、なぜ高いかというのは、区としてもつかむ必要があるのではないかと思うのですけれども、その点についても伺います。そういう点でも、この２０歳からの健康診査を区としてもしっかりと分析をして課題を明らかにしていく、いかがか尋ねました。","respondent":"川島健康課長","answer":"こちらは要治療になる前の方が非常に多いというようなところですので、生活習慣病という部分です。生活習慣を改めていただくような促しを私どもはしていきたいと考えております。","id":"exchange-153"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これだけ高いというのは、私は異常な状況だと思うのです。要治療というふうな状況ですから、そういう視点と対策が必要だと思いますので、ぜひそういう点でも取組みを進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-154"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２７３ページ、成人歯科健診、同じく眼科検診をお伺いします。小学生で４.５％、中学生で８.５％という状況があるようですけれども、まず品川区の状況はどのような状況か尋ねました。","respondent":"篠田学務課長","answer":"中学校と義務教育学校（後期課程）が、歯列と咬合の異常が２０４名で、４.２％、それから顎関節の異常が３４名で０.７％となっています。こういった異常が見られますと、各ご家庭にご通知を申し上げまして、それぞれ受診の喚起をしているという状況です。","id":"exchange-155"},{"speaker":"こんの委員","kind":"質問","question":"こういうことに対しては区はどのように認識して、どのようにされようと、見解をお持ちでしょうか。お願いします。","respondent":"仁平品川保健センター所長","answer":"８歳から１０歳ぐらいのときには、永久歯が生えそろってまいりますので、その辺もうまく利用されるとよいのかというふうな認識です。保健センターとしましては、引き続き指導に努めてまいりたいと考えます。","id":"exchange-156"},{"speaker":"こんの委員","kind":"質問","question":"どういう治療体制にするのか、これは今、なかなかその指導まではいかれていないのかという現状があるのではないかと思われます。こうした状況もある中ですので、区としては何かの対策を考えていかなければいけないと考えますが、いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"矯正治療への支援となりますと、なかなか判断基準をつくっていくのは、区としては難しいかと捉えられるところです。成長の段階におきまして、我々としましては、現在は常に口腔の健康な維持を奨励するための指導を引き続き行ってまいりたいと考えるところです。","id":"exchange-157"},{"speaker":"こんの委員","kind":"提案","question":"この歯科矯正の治療に対する助成ということも考えておりまして、そうした治療の促進対策を提案したいと思いますが、いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"やはり矯正治療となりますと、状況によってなかなかそこに一定の判断基準を持つというのは、区としては難しいかと考えておりますので、今のところ、保険適用以外に助成金を出すというような施策は考えていません。","id":"exchange-158"},{"speaker":"こんの委員","kind":"質問・要望","question":"子どもの健康にかかわる大事な口腔ですので、指導していきたいという思いを実行に移していただきたい、このように要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"渡部委員","kind":"質問・要望","question":"私ども会派は要望させていただいていて、代表質問でいろいろお話もさせていただいたのですが、私たちはいいことだと考えています。どういう支援ができるのか、やはりこれは何かしてほしいと思いますので、２点お伺いします。","respondent":"山崎商業・ものづくり課長","answer":"例えば今、いろいろ電子決済のＰａｙＰａｙですとか、いろいろなものが出ております。そうしたスマホそのものの理解を進めるような出前講座なり、まずそこから考えて一歩を踏み出したいというふうに思っているところです。","id":"exchange-160"},{"speaker":"渡部委員","kind":"提案","question":"しかもそれをビジネスクラブ等と組んで、いわゆる品川パビリオンとしていくべきだと思うのですが、いかがでしょうか。今まで知らなかった方に、また品川のものづくりを知ってもらういい機会になるのでないかとも思うのですが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"しっかり区としてこの分野でＰＲしていこうというようなことでやらせていただく予定になっております。１つの産業の品川区を代表する動きではありますが、つなげ、イノベーション・シティ品川というものを確立してまいりたいと考えるところです。","id":"exchange-161"},{"speaker":"渡部委員","kind":"質問","question":"同じ２９５ページです、今年から社会貢献製品支援事業が始まって、１１社１３商品なのでしょうか、これに認定されております。新たな商品があれば、このように認定して進めていくのか説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"本格的な採用になっているというようなことで、１３製品のうち、ほぼ全ての事業でいろいろ成果を見せております。来年度についても、申請をいただいて認定をするというようなことと、今年認定したものをさらにプッシュしていくようなことで考えているところです。","id":"exchange-162"},{"speaker":"渡部委員","kind":"確認","question":"最後に１点だけ確認をします。品川区の制度融資は、制度融資内で限度額までは借り換えは大丈夫なのですよね。","respondent":"山崎商業・ものづくり課長、たけうち委員長","answer":"一定、借り換えも、条件はありますが、借り換えは基本的には可能です。以上をもちまして、本日予定の審査は全て終了いたしました。","id":"exchange-163"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/778040?Template=document&Id=1098#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":122598,"voices":379}},{"id":"r01-20190312-3","meetingId":"r01-c-budget","date":"2019年3月12日","dateIso":"2019-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"芹澤委員","kind":"確認","question":"３１５ページ、３０３ページの放置自転車の防止指導啓発について、伺います。特に初期対応で迅速に現場を確認する意味合いでは、１台でも２台でも意味はあると考えております。","respondent":"今井土木管理課長","answer":"ようやくＮＴＴ東日本関東病院のところに２カ所ポートを設置いたしまして、あとは今後、こういう施設にも置いていきたいと考えています。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"確認","question":"確認ですが、１９ポートを増設するというような具体的な数字が予算で組まれていると思いますが、この１９ポートの中で五反田が何ポートになるかというのはまだ決まっていないんか尋ねました。","respondent":"今井土木管理課長","answer":"できるだけ荏原地区、また五反田、大崎地区に進めていきたいと考えています。１９ポートの中で何施設、何ポートを、五反田、大崎地区に、というそこまでは決定していないところです。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"区民の運動習慣の一つとしても、より多くの方々に自転車を移動手段として使ってほしいと求めました。なかなか区独自でというのは難しいとは思いますが、これから自転車道の整備の予定について、説明を求めました。","respondent":"多並道路課長","answer":"具体的には今、大井ふ頭中央海浜公園の道路工事と、あとは大森駅周辺の整備等を進めております。今後の整備の考え方としまして、そういう視点で各課と連携しながら、進め方を考えていきたいと考えているところです。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"この水面の活用をできないかという視点で伺います。池でありますが、池の水面にプロジェクションマッピングを行い、５万人を超える観光客が来たと伺いました。","respondent":"持田河川下水道課長","answer":"そういった施設のほうを照らして、船から見た景色とか周辺を歩いた方の景色でより見やすいものと考えてございました。橋梁、護岸等をやりながら、また今後の展開という中で研究していきたいと考えています。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"最後、ちょっと時間があれですので、放置自転車について伺います。４分の１が取りにこないという状態かと思いますので、その自転車の対応というか、活用ができているのかを説明を求めました。","respondent":"古郡交通安全担当課長","answer":"１万台近くになっていて、その場に取りにこないものについては、業者に販売しているという状況です。売却については３０.２％の３,３４６台を売却しているような、リサイクルについては４２５台ということで、３.７％となっております。","id":"exchange-005"},{"speaker":"新妻委員","kind":"提案","question":"３０５ページ、デザインマンホール蓋設置等についてお伺いをいたします。津波・高潮対策ですが、私は一般質問で、高潮被害の起きる時間軸をもとにした被害状況を動画にして公開をしてほしいという提案をいたしましたとの意見を述べました。","respondent":"持田河川下水道課長","answer":"高潮というお話がございまして、かなり規模も大きいということで、津波よりも浸水の深さが深いような大きな水害となっているところです。例えば１ｍとか１.５ｍとして記載されてありますが、また今、啓発等の方法についても検討していきたいと考えているところです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"次に避難所運営マニュアルの公開について伺います。具体的にこの各避難所の運営マニュアルの公開を求めたところ、標準的な避難所運営マニュアルを公開するというところにとどまった答弁でありました。","respondent":"古巻防災課長","answer":"最終局面ということで、この公開の件につきましては、そちらとの協議の関係で公開するしないというあたりをきちんと詰めていく必要があるということ。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"この液体ミルクを正しく知ることを求めましたが、どのように周知がされたのか、または行われていくのか伺います。液体ミルクを災害備蓄品の中に入れることを改めて求めますが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"２点、それから消費者庁が主催しております調整液状乳に係る行政説明会が開催されまして、情報収集をしてまいりました。ただちにということは難しいかもしれませんが、なるべく災害時にきちんと活用ができるような方策を工夫して、考えていきたいという形です。","id":"exchange-008"},{"speaker":"新妻委員","kind":"提案","question":"そして、最後にデザインマンホールについて、伺います。５カ所全てシナモロールの新たなデザインで、全てを回ってもらえるような楽しさと意外性を持ったマンホールを提案いたしますが、いかがか尋ねました。","respondent":"多並道路課長","answer":"デザインマンホールにつきましては、しながわ観光大使のシナモロールをデザインとして、今年１カ所、整備させていただきました。文化観光課とよく連携をとりながら、周遊と観光も含めて、工夫してまいりたいと思っているところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"中止を求める請願が第１回定例会に出され、住民の一番近くにいる区政として住民の願いをしっかり受けとめていただきたいと思い、質問をいたします。３点目が都に公開説明会の開催を求めてください。","respondent":"鈴木都市計画課長","answer":"放射２号線に関するお尋ねですが、まず道路予定地に係る建物棟数ですけれども、約２００棟です。これは代替地の考え方ですが、対象者がみずから地区内で探したかどうかも含めて、区のほうでは把握していないという状況です。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"代替地は当然、求めに応じて用意すべき。都と区の責任で公開説明会を開いていただきたいのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"放射２号線を含む特定整備路線につきましては、東京都のほうでこれまで事業の説明会あるいは用地測量の説明会、回を重ねて説明会を実施しています。区としましては、今後も都と連携をして、さらには東京都にも引き続き地権者の方への丁寧な説明を求めていきたいです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"誰がなぜ道路をつくってくださいと東京都に頼んだのでしょうか。この発言が事実なのかどうか、説明を求めました。","respondent":"鈴木都市計画課長","answer":"そうしたことからも公開説明会を区としてとり行う考えはございません。燃え広がらないまちをつくっていくというところで、東京都が地域の方にご説明をしながら事業認可を取得し、進めているものです。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"提案","question":"説明会を開いて、そして都に中止を求めるよう、強くお願いをしたいと思います。そして、もう１つの質問としては、地権者みずからがまちづくりを提案と書かれていますが、提案する方々の構成と人数を説明を求めました。","respondent":"稲田都市開発課長","answer":"今週末、地権者への説明、またその後に周辺の皆様方への説明会をやるというふうに今、考えているところです。商店街の方々もこの案について、発案しているというところでございまして、約１００名程度ではないかと考えています。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はこの地域もアンケートを３回ほど行っているんですが、武蔵小山の庶民的なところが大好き、高層化に反対をする人が５２.５％いらっしゃいます。ぜひ、地元の声を聞き、尊重するまちづくりを進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"歩行者用の信号を設置すると、以前伺いましたが、その進捗がどうなっているのかをお知らせいただきたいと。なぜかというと、それについて、どうお考えなんか尋ねました。","respondent":"古郡交通安全担当課長、今井土木管理課長、多並道路課長、高梨木密整備推進課長、長尾建築課長","answer":"どういったものが必要なのかを検討しまして、道路課の所管を含むものについては連携を図って、道路改良なり対策をしています。… 今後、来年度に向けまして、７０ポート、７００台の予定で全区展開をしていく予定です。駅からちょい乗りするという形でも考えておりましたので… これについては優先度を見ながら修繕を進めているところです。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"こうした未接道、いわゆるコアな住宅に対してもしっかりと建て替えに関する何らかの支援や救済措置が政策上必要と考えますが、いかがでしょうか。やはり一つのところにしっかりと支援ができる何かを今後政策として考えていかなければいけないと考えていますけれども、いかがか尋ねました。","respondent":"長尾建築課長","answer":"原則は接道は２ｍ必要となっておりますが、２ｍの接道幅はとれないけれども、許可をいたしまして建て替えもできるようにはなっております。そういったところも勘案しながら、未接道宅地での建て替えを望まれている方の後押しをやっていきたいと考えております。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"４,０００棟前後あると言われている未接道宅地なんですけれども、今、じゃあこの４,０００棟のうちの何棟がそれに該当するのか。そういうところに積極的に問題意識を持って支援ができる、救済措置ができるといった政策をぜひつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"３１５ページの排水施設建設事業なんですけれども、西大井五丁目、四丁目の工事はどうなっているんでしょうか。お伺いします。","respondent":"持田河川下水道課長","answer":"ようやく平成２９年の４月ごろ、これは大田区の公園を使ってやっておりますが、工事をしていると聞いてあります。進捗としては下水道管はおおむね３００ｍぐらい設置するうちの今、６０ｍが終わったところということで、おおむね６０ｍぐらいまでやっと進んだです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう本当に何年かかったでしょうか。もし東京都に４月から帰ることがあっても、最後まで見ていただきたいと思っているんですけれども、その辺についてはいかがか尋ねました。","respondent":"持田河川下水道課長","answer":"事業をやっている事務所としても時間はかかってありますが、毎年しっかり予算をつけて事業を進めていると聞いてあります。都のほうで進めている事業は非常に注目されているんだというところについてはしっかりと、引き継ぐような形をとっていきたいと思ってあります。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"地域の方からも伺いました。ぜひ６時台に１本でも２本でもぜひぜひとまってほしいというお話が来ているんですけれども、どう考えるか、説明を求めました。","respondent":"鈴木都市計画課長","answer":"８時台、４本と本数も少ないというところで、中央部分では乗れないときもあって次の電車を待つ方もいらっしゃると伺ってあります。今、いただいた要望も含めて、こうした状況を確認しながらＪＲとは協議をしていきたいです。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"次が３０３ページの交通事故防止対策になると思うんですが、信号機のない横断歩道のことです。やっぱり道路交通法上だと思うんですけれども、この辺について私は対策していっていただきたいと思うんですが、いかがか尋ねました。","respondent":"古郡交通安全担当課長、多並道路課長","answer":"ただ、ないところには警察署と連携をしまして、横断歩道に人がいたらとまりなさいよという啓発看板等の設置をして対策をしています。安全教育等さまざまな機会を捉えて、周知徹底、広報、啓発を図っていきたいと考えております。 都市計画道路の１６３号線というところになっていますので、事業化に向けて検討しているところということで、ご不安のところについては解消していく方向と考えているところです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"だからせっかく警視庁から来てくださっているんですからお願いします。いかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"取り締まりに関しては、警察の所管となっておりますので、警察のほうには要請という形で伝えてまいりたいと考えております。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"最後に、３４１ページ、借上型区民住宅ですけれども、特優賃です。どういう状況になっているか、説明を求めました。","respondent":"森住宅課長","answer":"借上型につきましては、今年度の８月に１棟、返還をいたしまして、残り１棟、１６戸が残っている状況です。残りは平成３２年の末に返還という予定になってあります。","id":"exchange-023"},{"speaker":"藤原委員","kind":"確認","question":"今まで特優賃の質問をよくしてきましたけれども、これで最後ということが確認できましたので、安心しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"３３１ページ、４目公園管理費、子どもたちのアイデアを活かした公園づくり基本構想策定についてです。この菜園ができた経緯をお知らせくださいとの意見を述べました。","respondent":"今井土木管理課長","answer":"福栄会の知的障害者の授産の作業用地としまして、障害者福祉課を通して平成１９年に活用の申し出があったところです。倉庫などの検討がまだ進んでいなかったところですので、目的外の使用許可という形で、行政財産の使用許可をしたところです。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"地域からはフェンスによる圧迫感ではなく、公園の整備を求める声も聞こえています。区は都と地域住民の調整役となり、地域住民の求める公園や花壇や菜園の設置などにつなげられないものか伺います。","respondent":"高梨木密整備推進課長","answer":"放射２号線沿道で、まず地域の声を受けて、東京都と協議をしてまいりたいと考えております。あると思いますが、まずはそういった声を我々のほうへ上げていただいて、区としては東京都と積極的に協議してまいりたいと思っています。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"彼らから声を聞き取るのは難しいかもしれませんが、一緒に公園に行ってみると、小さな子どもの求める整備というものがわかります。保育士体験をした職員や保育者からの声を聞きながら、小さな子どもたちの声も公園設備へつなげてほしいと思いますが、いかがか尋ねました。","respondent":"高梨木密整備推進課長、溝口公園課長","answer":"菜園ができるかどうかについては、区としても約束できるものではないかなとは思いますが、そういった声があるということは東京都に正確に伝えて協議してまいりたいと思います。どういう形で子どもたちのアイデアを聞いていくのかといった検討を今現在して、４月よりスタートしたいと考えているところです。","id":"exchange-027"},{"speaker":"田中委員","kind":"提案","question":"公園便所を快適で清潔に利用できるよう環境整備を行う中で、トイレ設計時に、防犯の観点も重視してほしいという思いから質問します。防犯面に不安がある現状の公衆トイレでは早急な防犯対策が必要だと考えますが、どのような対策がされるのか、伺いますとの意見を述べました。","respondent":"溝口公園課長","answer":"そういったところで、委員のご指摘のように、死角をなるべくなくすといったところが一つ大きな視点かと考えているところです。出入り口を公園のほうに向けるとか、安全でまた利用しやすいトイレといったものの整備を心がけていきたいと考えているところです。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"現在、防犯面に不安がある現状のトイレについての防犯対策についても、後でお伺いできればと思います。発災時の集団住宅で、トイレが使用できるかどうかの下水管チェックができると、２０１８年の決算特別委員会で伺っています。","respondent":"溝口公園課長、古巻防災課長","answer":"そういった中で、まずはやっぱり清掃してきれいに使ってもらえる。清掃回数を増やすといったところで安全対策を図っていきたいと考えているところです。１つは安全運営マニュアルの中で、これは避難所のチェックではありますが、こういった形でトイレのチェックの徹底とチェックの仕方を掲載する。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"１点目に防災訓練経費について、お伺いいたします。目黒駅や大崎駅など、行政同士は他区とのかかわりを持っているかと思いますが、区民同士の状況はいかがか尋ねました。","respondent":"古巻防災課長","answer":"今、委員からもご紹介がありました、そういった中での情報交換とかのところからの顔の見える関係づくりといったものを進めているところです。","id":"exchange-030"},{"speaker":"横山委員","kind":"提案","question":"東急線沿線は住宅が多いため、目黒区と品川区の両方の防災に関する情報を知ることもできるような取り組みを実施いただくことを提案いたします。住宅街における他区との防災情報の区民同士の共有を早急に進めていただきたいのですが、区のお考えを説明を求めました。","respondent":"古巻防災課長","answer":"町会の中でそういった形での働きかけをするとか、示唆をするとかいった形で、情報交換が進むこと。そういったことでなるべく区の取り組みがわかりやすく伝わるようにといったことも含めて考えてまいりたいと思います。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"は港区の方々と実際に自助・共助で連携していく必要性も出てくるかと思いますので、このあたり研究を進めていただけたらと考えています。町会・自治会とともに検討を進めていただきますよう、こちらは要望させてほしいと求めましたけれども、最後に一言お願いいたします。","respondent":"古巻防災課長","answer":"近隣区との連携といった部分でいいますと、特別区で防災担当課長会という課長が集まる会合が月に１回程度開催されております。そういった中で、そういった中で情報交換をしていくといったところから必要性を集めて考えてまいりたいと思います。","id":"exchange-032","title":"町会・自治会支援"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に歴史的・魅力的建築物調査活用委託について、お伺いいたします。表紙と２ページ目、そして３ページ目をご覧ほしいと求めました。","respondent":"長尾建築課長","answer":"こちら、オープンしなけん２０１９というイベントで、３月９日の土曜日に実施いたしました。実施したところですけれども、こちらのご参加も合わせますと、１,３００名ほどの方が当日楽しんでいただけたような状況になっております。","id":"exchange-033"},{"speaker":"横山委員","kind":"確認","question":"区外の方が６割ということで、自由見学も含めて１,３００名ほどご覧になられたということ、参加いただいたということを確認させていただきました。品川の「品」にアーキテクチャーの「Ａ」を融合したロゴなのだという話をお伺いしましたが、周知方法、ご説明をお願いいたします。","respondent":"長尾建築課長","answer":"イベントの実施に当たりまして、イベントの実績のある所管部署、デジタル媒体と紙媒体をできる限り使うというところを工夫いたしました。２月１日から周知を開始いたしまして、締め切りの２月２２日まで広報しながわ、配布させていただきました。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"日本の団地というのは外国人にとって魅力的なものであるというお話がありましたが、品川区には八潮団地があります。別の魅力についても調査、活用をいただきたいと要望いたしますが、区のお考えを説明を求めました。","respondent":"長尾建築課長","answer":"今、区の魅力を発見したり再認識したりする一つの視点として、可能性はあると考えます。さらに区の魅力を感じていただける視点も大切かと思いますので、今後の研究課題として捉えてまいりたいと考えております。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ今後の研究課題として、次回以降に活かしてほしいと求めました。この事業で文化財として価値の高い建築物を発掘する中で、教育委員会による文化財保護との連携について説明を求めました。","respondent":"長尾建築課長","answer":"今回、公開した中には国や都、区の文化財指定を受けている建物はございませんでしたが、建物の所有者のご意向も踏まえながら、そういった文化財の指定をすることで、さらに区の魅力の向上や形成につながるように今回の事業を活用していけるように検討してまいりたいと考えます。","id":"exchange-036"},{"speaker":"つる委員","kind":"質問","question":"３３９ページ、３４３ページ、伺っていきます。公園管理費、それから小山台東公園改修工事について伺いますが、まず民生費の質疑の中で、この間、品川区が進めてきた待機児童対策。","respondent":"溝口公園課長","answer":"そうした中、やはり遊具としては３歳から、複数の幼児から児童まで使えるような遊具の設置を進めてきているところです。公園の利用状態といったところも勘案しながら、遊具の設置といったものは今後も引き続き行っていきたいと考えているところです。","id":"exchange-037"},{"speaker":"つる委員","kind":"質問・要望","question":"これが２０１９年度以降、検討されたものがどう具体的に改修工事等の中で活かされていくのかといった部分。そうした観点も含めた先ほどの子どもたちの部分もありますけれども、それをどう活かしていくのか、そのあたりも説明を求めました。","respondent":"溝口公園課長","answer":"今年度、ユニバーサルデザインをどういう形で公園に取り込んでいくかというところで検討を進めてきたところです。今年度検討したものにつきましては、子どもたちのアイデア、子どもたちのアイデアの公園づくりを進めていきたいと考えているところです。","id":"exchange-038"},{"speaker":"つる委員","kind":"提案","question":"年１回の専門家によるさまざまな確認等をしていただいているかと思いますが、日常の危険箇所、２０１０年に公園課長が写メール等を活用して。実際に区民の方から危険箇所などを教えていただいて、これについてはあえて答弁は求めませんが、要望でとどめますけれどもとの意見を述べました。","respondent":"森住宅課長","answer":"自治会の方々が週１回掃き掃除だとかもやっていただいていると聞いてあります。清掃を一つのコミュニケーションとした取り組みも考えておりますので、そういった部分を指定管理者とともに検討していければと考えております。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった部分に対しても手当をしていただきたいという声も皆さんから伺うところでありますので、今回、展開をしていく。多少なりとも限定条件を加えたとしても、全面展開できるような工夫ができないかどうか、そのあたりの考えを説明を求めました。","respondent":"古巻防災課長","answer":"平成３１年度予算の中では高齢者、それから新たにアースつきのコンセントを設置するタイプの簡易型の追加という形での助成の拡大をしています。","id":"exchange-040","title":"町会・自治会支援"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に３０４ページの道路橋梁費に関連して、カーブミラー等の支柱倒壊対策という観点で伺いたいと思いますが、提示します。そして今年度そうした支柱等の点検を強化されているとは伺っておりますが、点検をした上で、お聞かせほしいと求めました。","respondent":"多並道路課長","answer":"この中で、かなり今のような老朽度の激しいものについては１８基あったということで、これについては対処させていただいたところです。それ以外にも軽微なものが５７２件ほどありましたので、構造的な安全対策は今後もしっかり行っていきたいと思っているところです。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ積極的に対策を進めていただきたいのと、やはり動物のさまざまなマーキングの部分もあるかと思いますので、そういったものも含めてあわせて対策を強化してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"今度の計画でも水上アクティビティという強化をぜひお願いしたいと思うんですけれども、いかがお考えなのでしょうかということと、飲食。水辺近くの商業、飲食スポットの推進を伺っていきたいんですけれども、その点についていかがお考えか尋ねました。","respondent":"持田河川下水道課長、鈴木都市計画課長","answer":"そういった非動力で人が遊べるものと、またいわゆる大きな船など、なかなか安全面ですとかといった部分のすみ分けが非常に難しい状況があるです。具体的なところにつきましても、また非動力のものの桟橋も含めて… これまで水辺も魅力ある取り組みを継続して行ってきておりますが、これを来年度１年かけて策定していきたいと考えています。そういった視点を加えながら、この整備計画の策定を進めていきたいです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"区民体感型の取り組みがこれから必要だと考えておりますので、２点、ぜひともお願いしたいところです。今、私が話した周知の方法について、今後どうお考えになっているのかをお知らせください。","respondent":"持田河川下水道課長","answer":"所管としては整備など進めながら、なかなか具体的な桟橋等もまだない中で、周知のほうも少しまだ努力をしなければいけないと考えているところです。事業を進める中で、そういったイベント等の中で、水辺のほうもＰＲを連携しながらしっかりとやっていきたいと考えています。","id":"exchange-044"},{"speaker":"筒井委員","kind":"質問","question":"オリンピック・パラリンピックの成功という意味には、このオリンピック・パラリンピック時災害対策計画の内容はどのようなものになるんでしょうか。東八潮にあるんですけれども、これはなかなか災害時避難対策は難しいかなと思っているんですけれども、その辺いかがお考えになっているんか尋ねました。","respondent":"古巻防災課長","answer":"１つは具体的には震災を主に考えておりまして、江東区とも連携しながら、東京都を含めた連携体制の中での安全対策を考えているところです。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして無事故で過ごせるよう、本当にいい大会だったなと思われるような万全の体制で行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"３２１ページ、不燃化１０年プロジェクトに関連し、住みなれた街並みを活かした低層の防災のまちづくりを求めて質問いたします。まちづくりを地域の皆さんとともに検討していきたいとは、具体的にどういうことか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"今、委員のご説明のとおり、２月末から３月にかけてアンケートを実施しています。どのようなところをよいところと思っているのかといったところを聞き取るためにもこのたびのアンケートを実施したものです。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"問７で住まいの権利状況や建物の用途や構造を聞いておりますけれども、その理由は何か伺いたいと思います。これはなぜなのか、伺います。","respondent":"高梨木密整備推進課長","answer":"問６のこれからのまちづくりの進め方についての選択肢ですが、あと、そういったところも選択肢としては入れました。皆様方の合意をもって進めたいという選択肢につきましては、こちらを選んでいただければそういった趣旨で合うのかなといった形で考えております。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"資料には緊急車両の進入路とありますが、これはどういう目的なのか、なぜこの位置の整備なのかを伺います。もう１つの目的として住民の迅速な避難路を確保とも書いていますけれども、どんな場合のどんな避難のことを指しているのかを伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"さらに両側１ｍずつのセットバックが必要といった形になりますが、合意が得られたところから順次、整備を進めていきたいと考えているところです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"共同建て替え等を支援するとあり、この共同建て替えというのはいわゆる第１種市街地再開発事業も含まれるのか伺いたいと思います。これでも皆さんの意向に応じたということになるのか、あわせて伺います。","respondent":"高梨木密整備推進課長","answer":"西品川三丁目地区で定めました整備計画の中での建て替え促進地域についての考えは、まず、第１種市街地再開発事業を前提としたものではございません。既にそういった事業が予定されているといったものではなくて、事業手法等についても検討していくことになろうと考えています。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいと思います。数軒での小規模な共同建て替えを基本にして、区は小規模で低層の共同建て替えを支援することを求めますけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"そして飲み水等、そういう防災の倉庫等も設置しているというところで、防災的には非常に安全性が高いものだと考えております。居住者を入れて、まちを活性化するとかという面もありまして、そのような形で進めているものでマンション等もつくっていくというところであります。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"最後、すみません。避難先の避難所自体、火に囲まれてしまうのではという不安が住民の中にありますが、その不安について区はどのように考えていますか尋ねました。","respondent":"高梨木密整備推進課長","answer":"延焼が進んだ際には広域避難場所に逃げてもらうように周知啓発を図っていくという形をとっています。","id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"３１３ページ、水辺利活用事業で五反田のことを中心に伺います。本当に川の拠点だったり、水辺、海もそうですが、やはり道の駅というものがあるように、川の駅などはどうか尋ねました。","respondent":"持田河川下水道課長","answer":"工事も進めながら、工事はまた地域の方にいろいろご説明しながら進めているところもありますので、本格的な運用が迫ってまいりましたら。","id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"ツタというんですか、ここ１年で集中的に重点エリアを決めて、何か手を入れられないものか。今、コンクリート一辺倒みたいなところがどうしても多いので、この辺の景観について、説明を求めました。","respondent":"持田河川下水道課長","answer":"にぎわいの要素というところでやはり緑とか花というのは重要だと考えていますので、整備の中でできる範囲やっていきたいと。そういった緑ですとか花の要素というのもにぎわいに重要だと思いますので、そういったところも取り出しながら進めていきたいと考えています。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問","question":"ここ１、２年、やはり春の桜のシーズンに運行マナーがすこぶるよくなっている。ごみ等も含めて、その辺、いかが考えているのか説明を求めました。","respondent":"持田河川下水道課長","answer":"区のほうでもプロモーション的な観点ですとか、庁内で連携して、そういった何かプロモーション的な部分についても検討していきたいと考えています。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間があれば３２５ページ、連続立体交差化事業についてお伺いします。１番目に、決算特別委員会で自民党の芹澤委員とともに求めておりました行政書士会品川支部との防災協定について、どのようになったのか。","respondent":"古巻防災課長","answer":"去る１月の下旬に協定の締結に至りまして、援助、ご支援をいただいたりといった形の内容での協定を結ばせていただいております。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"幾つか具体的な確認をさせてほしいと求めました。立て続けに伺いますけれども、ＴＳマーク等を含めほかの自転車保険がありますけれども、比較してのメリットについて伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"この保険のメリットですが、ほかの保険に比べて安価で入れるということ。内容についてもある程度保障はされるということで、それがメリットだと思います。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"在勤、在学の方も申し込めるというところの、何かもし理由があれば教えていただきたいということと、プレス発表では品川区が保険者となると。もう少しわかりやすく教えていただきたいのと、またその民間の保険会社がどこなのか、お知らせください。","respondent":"古郡交通安全担当課長","answer":"損保ジャパン日本興亜株式会社が提供する区民交通傷害保険制度に品川区が窓口となって、区民等に申し込みを募集するものです。申し込みと保険料は区がとりまとめて、保険会社に提出するということになっております。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私なんかも入っていますけれども、そういうところとの違いをわかりやすくちょっとご説明をほしいと求めました。お子様までカバーができるのか、それともお子様も入っていなければいけないのか、それについて説明を求めました。","respondent":"古郡交通安全担当課長","answer":"は自転車で転倒をして、けがをした場合になります。母親も入っていただいて、子どもも入っていただいてという形で、母親が入っているから子どもが保障されるものではございません。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"意見","question":"区広報媒体を活用し、区民の加入促進を図る」とありますが、区広報媒体というのは何を指しているのかというところ。ケーブルテレビ等も入っているのか、お知らせくださいとの意見を述べました。","respondent":"古郡交通安全担当課長","answer":"周知の方法につきましては、チラシの配布を行うということで、区内の小中学校や、区内の警察署の交通課などそういったところに。は地域センターだとか、区内の自転車駐車場等、そこで配布をする形になります。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問","question":"最後に伺いたいのは、一応プレスだと、５月７日に申し込みが始まって６月２１日までと。前回、前のときには５００円、品川区としてはこの保険の推進を強く図っていくのかどうかのお考えを伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"これについては、ほかの区で実施している状況を見ると、大体１％程度ということですので、そういった見込みでおります。推進につきましては、自転車の事故が非常に増えていますので、推進を図っていくです。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問・要望","question":"総括で、若干後ほどまた確認をさせてほしいと求めました。今回１億円以上、計上されていますが、それはその分も入っているのか説明を求めました。","respondent":"古巻防災課長","answer":"昭和５０年代から変更されることがなく、約４０年ほどか、もう少し経過をしているような状況です。安全性とか性能の点で、品川区の職員とわかりやすいデザイン、それから蛍光剤を用いることといった形でリニューアルの内容を検討しています。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問","question":"その理由の１つに、貸していただける、貸与していただけるのは大変ありがたいのですが、区の職員と間違われてしまうと。これから先は本当に議会での話で、これはこちらで揉まなければいけない話なんですが、デザインの変更等というのは間に合うのかどうか伺いたいです。","respondent":"古巻防災課長","answer":"デザインの変更につきましては、今年度予算でデザインの変更をさせていただいて、大きくは難しいかなと思います。ただ、そのあたりできるところで、何か判別ができるような形をとれるようには工夫をさせていただければと考えます。","id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこについてつくっていただきたいという要望をいただいてきたんですが、この辺について、今までの話し合いの中で出てきたのかどうか。つくっていただきたいと思うんですが、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"地域のほうからも高架下の活用、それから駅前広場の利用に当たりましては、駐輪場をつくってほしいという要望を今現在もいただいているところです。来年度詳細計画を検討していくことになってありますので、こちらの計画、今後も検討してまいりたいと思います。","id":"exchange-064"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３４０ページ、現在区内には５０カ所の民間井戸を確認しているというご答弁があったんですけれども、５０カ所どころではない。荏原のほうに行っても井戸は確認できますし、世田谷なんかでは千数百あるということで、その後何か進展がありましたら教えてほしいと求めました。","respondent":"古巻防災課長","answer":"井戸の現状ですけれども、ご答弁の中で５０カ所ということで、区として今現在、把握している箇所は５０カ所です。そのほかにあるのかどうかといったことにつきましては、今、調査等する中で把握していくことになろうかと思います。","id":"exchange-065"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今後の課題として研究をしていくということで、研究というお話になっているんですけれども、協定の締結というお話もありました。世田谷の例も聞かせていただいて、これは今すぐにではなくていいんですけれども、これは継続をして調査研究は進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"松永委員","kind":"質問","question":"初めに３３１ページの公衆便所費、４億３,１０８万３,０００円について、伺います。あわせて、立会川駅の近くにある天祖・諏訪神社に隣接する公衆便所については、いつごろ工事にとりかかるのか尋ねました。","respondent":"溝口公園課長","answer":"東京２０２０大会の開催までに全てのトイレの改修、または洋便器化といったものを図っていきたいということで、現在進んでいるところです。立会川駅の弁天橋の工事につきましては、来年度に設計と工事をやっていくということで予定をしています。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"そして関連して新たに公衆便所を設置することについて伺います。できるように検討を行うべきではないかと考えますが、区の見解をお伺いします。","respondent":"溝口公園課長","answer":"公衆便所だけでなく、公衆便所、公園トイレを含めて新たに設置していくという考えは今のところないのが現状です。今あるトイレ、まずはその洋式化をしっかりと進め、そういったものにまずしっかりと取り組んでいきたいと考えているところです。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問","question":"以前は公衆便所が汚かったということもあり、そうしたことは今までなかったそうです。このだれでもトイレとはどういうトイレであるのか、また公衆便所についてもどういうときに利用していいのか、ルールについて改めて伺います。","respondent":"溝口公園課長","answer":"基本的に公衆便所につきましては、誰でも、区民の方、また区に訪れる方といった方たちには誰でも使えるような形を目指してきているものです。障害のある方、また身だしなみを整えてもらったりとか、そういったものに使っていただけるということを目的に設置してきているものです。","id":"exchange-069"},{"speaker":"松永委員","kind":"質問・要望","question":"防犯に関してなんですが、公衆便所の入り口に防犯カメラの設置を要望いたします。公衆便所に壁画などを取り入れたり、照明をもう少し明るくするなども効果的だと考えますが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"全ての公園に防犯カメラを設置するという形で今、進めてきているところですので、そういったところで対応ができると考えているところです。取り組めるところからしっかり取り組んでいき、なるべく誰もが使いやすいトイレといったものに取り組んでいきたいと考えております。","id":"exchange-070"},{"speaker":"松永委員","kind":"質問・要望","question":"災害が起きた場合に確保できるよう対策をとっていただきたいと要望いたしますが、いかがでしょうか。国もペットの同行避難が行えるよう求められておりますが、本区ではいつまでにペットの同行避難ができるような環境になると考えているのか尋ねました。","respondent":"古巻防災課長","answer":"どういった形で活用ができるかはこれからの検討になりますけれども、そういったところは十分に考えてまいりたいと考えています。一定の区の考え方を示しておりますので、周知が進み、なるべく早い段階で同じような考え方で区民の中でペットの対策が進むように考えております。","id":"exchange-071"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に要望いたします。やはり将来的には備蓄倉庫の拡大も必要だと考えますので、今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"３１９ページの特定整備路線沿道まちづくり推進費にかかわって、２９号線の東京都の買収地について伺います。区民が行きにくい、また行きたいと感じているところを把握できるアンケートなどにしてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"来年度より開始しますコミュニティバスの導入検討ですが、区のほうで公共交通として実施していくというのがまず基本的な考えです。これはやはり地域の声をしっかりお聞きしながら、検討を進めていきたいです。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問・要望","question":"一応、声を聞きながらということですので、しっかりと地域の声を聞き取れる、把握できるアンケートなどにしていってほしいと求めました。これまでも予算要望など、求めてきておりますけれども、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ルートの検討につきましては、先ほどご説明しましたが、まず既存のバスの走行ルートの検証をしっかり行わなければいけないです。まずはバスルートを、その上で、そうした視点で委員のご提案の視点も踏まえながら検討していかなければいけないと考えています。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"２６号線はまだ開通していませんが、桐ケ谷通りを通るルート、また各鉄道駅の間をつなぐといったルートを求める声も寄せられています。こういったこともぜひ検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ルートの検討に当たっては、特に補助２６号線の整備の見通しについては、検討していかなければいけないです。それからその後段のほうで、繰り返しになりますが、そうしたところとの競合がないような形でその辺はしっかり検討していかなければいけないです。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういったところも検討していただきたいと思うんですけれども、やはりそういった１ルートだけでなく、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今、大田区境の１ルートというお話もございましたが、まだこれから検討ということですので、どこのルートを重点的にということはこれからです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"私はこれまで求めてきたとおり、もちろん２９号線は撤回すべきだと思いますけれども、商店街の姿としてもよくないと思います。仮店舗やお休みどころ、駐輪場やイベント時に広場として貸し出すなどもできるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"こちらは東京都の事業になりますので、まず東京都がどういうお考えかが重要になってくるかと思います。短期間ではありますけれども、イベント時の広場的といいますか、休憩所みたいな形での活用をされているということは聞いたことがあります。","id":"exchange-077"},{"speaker":"のだて委員","kind":"提案","question":"これも仮設のトイレをそこに置くということになるか、お年寄りの方はなかなか使いづらいのかなということもありますので、どういった形がいいのか。ちょっと具体的な提案はわかりませんけれども、そういったトイレの設置などの活用についても伺いたいと思いますとの意見を述べました。","respondent":"東野まちづくり立体化担当課長","answer":"先ほどもお話しさせていただきました道路の目的外使用ということになりますので、その辺は東京都との十分な調整が必要だと考えます。一時的に区が窓口になることはやぶさかではございませんので、お声を寄せていただければと思います。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"目的外使用なのでできないというお話もありましたけれども、イベント時のお休みどころ、休憩場所みたいな形では使っているということでした。どういった形の場合に使えて、何が使えないのかを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"例えばですけれども、営利目的であるとかそういう場合には使えないということは聞いているところです。都有地の活用ということで、公有財産の貸し付けとかというような場合が生ずるということで、いろいろな制約があると聞いてあります。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"もう１つお話を伺いました。行政の事業によって、会員が減らされているということへの支援をしてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"２９号線の整備でいろいろな商店街の用地の交渉が進む中で、いろいろな事案があるというのも商店街の方からもお聞きしています。地域の声をしっかりお聞きして、できるところ、やるべきところはしっかり今後も地域の声をお聞きしながら対応していきたいです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"できることは対応していくということでしたけれども、今言いました商店会員がいなくなって、商店街の運営も大変だというお話なので、そういったことへの支援は何かできるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そういうところで何か商店街のイベント等に活用できないかという声をいただいております。できるところは東京都の対応、あるいは区がすべきところは、あるいは区ができるところは区が行うというところはしっかりしていきたいと思います。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"つまり商店会員の方への支援はできるんでしょうか。商店街の商店会員がいなくなってしまうという、この商店街の方たちへの支援はやっていかれることは。","respondent":"鈴木都市計画課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ声を受けとめて活用してほしいと求めましたし、私は２９号線撤回に向けて頑張っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"最初に、名前は出しませんけれども、建築会社のところで、界壁でしょうか。現状、これはこちらのほうの情報でありまして、区民の方からこの件についての何か意見あるいは情報が寄せられている部分はあるんか尋ねました。","respondent":"長尾建築課長","answer":"共同住宅・長屋等の界壁の仕様の不適合にかかわるというもののお問い合わせについてですけれども、現時点では建築課のほうに直接お問い合わせをいただいているというところはございません。","id":"exchange-084"},{"speaker":"大沢委員","kind":"質問・要望","question":"これで質問を終わっちゃうと、私も時間がちょっと余ってしまうので、先に進ませていただきたいんですけれども。平成１１年の５月１日から建築確認の認可に関する規制緩和ということになったわけですけれども、教えてほしいと求めました。","respondent":"長尾建築課長","answer":"先ほどご案内いただきました平成１１年当時の建築基準法改正に伴いまして、民間の建築確認検査機関へ手続が一部開放されております。","id":"exchange-085"},{"speaker":"大沢委員","kind":"確認","question":"その時期というか、時期的に建築の確認の作業が多いから一部開放したんでしょうけれども、かなり行政にとっては、それは負担になるほど多いというか、事務作業は多かったんか尋ねました。","respondent":"長尾建築課長","answer":"現在、区内では年間に大体、１,０００棟から１,２００棟の建物の確認申請が出ております。平成１１年当時もおおむねそのぐらいの件数があったと思われます。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問","question":"１,２００件という案件があるということで、いろいろなことをやっている会社なんですが、そういったことが起こらないようにしなければいけない。民間に委託したところに対して、行政はどのように普通の段階において指導・監督しているのか説明を求めました。","respondent":"長尾建築課長","answer":"民間の建築確認検査機関への指導等につきましては、例えば日常的にも法令の解釈などにつきましては、建築課のほうに問い合わせは来ております。きちんと法令にのっとった審査をしているかどうかというところも確認を行いまして、一定のチェック機能を働かせているところです。","id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"中間検査や完了検査について区がかなりの部分で関わっていかないと、こういう事故というのは減らないような感じはするのです。ちょっとそれは、私はこの部分の分野は余り、うといもので、そのような質問になってしまいますけれど、そこについてはどういうふうにお考えか尋ねました。","respondent":"長尾建築課長","answer":"今、それをきちっと計画どおりにつくらなければ安全とは言えませんので、検査というのは一定程度重要な過程であると考えております。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問","question":"私の経験則の中では、７月の頭にある行事を駅前でやったときは、それ以外は意外とずっと放置されているままの状態が続いているのです。あそこの所の放置自転車というかお客様の自転車でしょうけれども、どのように対策を講じていただければ解消できるか説明を求めました。","respondent":"稲田都市開発課長","answer":"まちづくりの中におきましては、その駐輪対策、何とかしてくれというところで東急のほうには申し入れをしています。東急のほうはなかなか難しいということで、現在のところ、回答はいただいております。","id":"exchange-089"},{"speaker":"大沢委員","kind":"質問・要望","question":"なので、日常の業務においても、東急にお任せするべきところが多いのですけれども、申し入れだけは常日ごろより行っていただきたいと思うのです。そのために駅前のビルによって周辺の駐輪対策、きれいになるようなまちづくりをしているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"それぞれの方々についての公園に対する要望というのはいろいろあるという中で、どういう公園であるかというつくりのバランスとか。足りているか足らないのか、ちょっと少なくなってきて足りなくなっているかなというふうな認識か、その辺のところなどをお伺いいたします。","respondent":"溝口公園課長","answer":"どうしても公園の中、やはり単体だけではなくて複合遊具を設置していくというのが、今現状において公園に必要と感じているところです。","id":"exchange-091"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった中で多くの方々が最大の満足を得られるという難しい注文になりますけれども、今後ともご検討いただきたいと思うのです。そういう中で、あの一角の遊具なのですけれども、移設あるいは別の所に同じようなものといった考えはあるのかどうかをお尋ねいたします。","respondent":"溝口公園課長","answer":"今回できる環境未来館の中でも、ある程度連携することによって、子どもたちの遊べるスペースといったものもつくっていきたいです。しっかりと連携を図りながら、改修に合わせての機能改善、そういったものを図っていきたいというふうに計画しています。","id":"exchange-092","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問","question":"そういった環境にある種特化した地域ということにもなってくるので、ここの水の汚れというのも何か手当をしていくべきかなと思います。そういった考えもあるというようなことも伺っておりますけれども、この辺の具体的な対策等あればお考えをお聞きいたします。","respondent":"溝口公園課長","answer":"水質が悪化してきたりというのは私どもも認識していますので、１回水を抜いて、今さまざま検討しているところではあります。環境未来館もできるところでありますので、そういったこともにらみながら、環境整備に努めていきたいというふうに考えております。","id":"exchange-093","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問","question":"今、そのヘドロ、常時きれいにしていくようなシステムというのはなかなかやはり大変なのでしょうか。もう一度お伺いしたいと思います。","respondent":"溝口公園課長","answer":"もともと、今改めて公園の中に浄化施設を入れるというのはなかなか難しい状況だというふうに考えているところです。そういったもの、またさまざまな池の浄化の手法がありますので、そういったものを含めて検討していきたいというふうに考えております。","id":"exchange-094"},{"speaker":"塚本委員","kind":"確認","question":"それを区のほうに連絡したりすると１週間から２週間、ということで、その後一定程度経過したら撤去というふうにしているかと思います。撤去されたあとの流れについて、最初に確認をさせてください。","respondent":"古郡交通安全担当課長","answer":"撤去したものにつきましては、所有者照会ということで警察のほうにお願いをして所有者照会をすると。集積所はここですよ、という形でお知らせをして、とりに来ていただくという形でやっております。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問","question":"その２週間とかという一定程度の間様子を見ているという間に、防犯登録等がされていれば、所有者への連絡というのは可能なのだと思うのですけれども。あるいはできないのであれば、なぜなのかというところをお伺いしたいと思います。","respondent":"古郡交通安全担当課長","answer":"所有者の照会につきましては、警察署への照会をして、おおむね１カ月程度かかります。何かできるかというとできないという形で、うちのほうで１週間程度見て、それで撤去をするという形になります。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"そこを待たずに、盗まれたんです」「じゃあとりに来たらどう」という話になぜすぐならないのかというのが、地域の方々からの素朴な疑問。私も話を聞いて、なるほどなと思ったところなので、今そうしていない理由というのがもしあるのであれば、お伺いしたいと思います。","respondent":"古郡交通安全担当課長","answer":"区の所有にならないと照会ができない。要は撤去をして、区の管理下に置いて、管理をして、それから照会という形になりますので、条例上もできないということです。","id":"exchange-097"},{"speaker":"塚本委員","kind":"確認","question":"よその自治体などでは、インクルーシブというような言い方で、インクルーシブな防災訓練というのを実施しているというような話も聞いております。どの程度今、されているのかというところだけ、最後に確認をさせてください。","respondent":"古巻防災課長","answer":"要支援者の支援体制構築の中で具体的にその個別計画をつくり、それを踏まえた形で避難援助ワークショップを行っているという形ではあります。今後、どういった形で進めるかはあれですけれども、障害者福祉課とも連携して考えてみたいと思います。","id":"exchange-098"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"しかし、食材がないということで、その食材は献立も含め自治体が準備をするということになっていると伺いました。品川区の防災の計画では、こういった自衛隊の炊き出しに関して、食材の調達や献立といったことの準備はどのようにされているのか尋ねました。","respondent":"鈴木都市計画課長、持田河川下水道課長、溝口公園課長、古巻防災課長","answer":"これも平成２９年度から検討を進めまして、地域全体の方へのアンケートの実施等を行いながら、まちづくりビジョンとして取りまとめてあります。… 立会川下流の１００ｍぐらいのエリアのところ、いわゆる青い鉄製のパネルを設置しまして、溢水防止という形でやっているところです。… 課題としてはあるところですが、公園の改修、また大きな道路の改修などでも品川区役所の前で１６３号線の整備も進められているところです。","id":"exchange-099"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つだけ、立会川・勝島の勝島運河の桟橋についてはどのような状況か尋ねました。","respondent":"鈴木都市計画課長","answer":"まちづくりビジョンの中においても、勝島地区と立会川地区の歩行者ネットワークの形成というところをしっかりうたわせていただいてあります。それをどう具体化していくかにつきまして、来年度、都・国といろいろ協議、調整をしながら、検討を進めてまいりたいと思います。","id":"exchange-100"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先日、幼稚園のお母さんから要望がありました。そういう声があったので、区も対応している部分はあると思うのですけれど、その辺どうお考えになっているか説明を求めました。","respondent":"長尾建築課長、溝口公園課長","answer":"その２０５棟のうち、耐震診断がまだ終わっていない建物や、耐震性がないことが確認されているものとしましては、合わせまして１２３棟ある状況です。率でいいますと約６割となっております。物が一切置けないような状況になっておりますので、どうしても木が少なくなったり木陰が少なくなったりというところがあります。","id":"exchange-101"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺はどういうふうに考えていくのか、お答えをほしいと求めました。パラソルなどどういうように置くかわからないのですけれど、そういった日陰の設置について、もう少し教えて下さい。","respondent":"長尾建築課長、溝口公園課長","answer":"その後耐震化を図っていくというところは、非常に労力もかかると思いますし、時間もかかるものだと感じております。そういった条例改正の内容も踏まえまして… 委員ご提案のミストというお話も言われております。この当公園の暑さ対策の中でどんなものができるのかというのは、利用者の声も聞きながら検討していきます。","id":"exchange-102","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の、緊急道路は都の条例改正によって変わってくるというお話だったのですけれど、現在の賃貸借にもそれは及ぶのですか。話が出たかどうか記憶にないのですけれど、借りて子どもさんのために活用することができないかと思いますが、いかがか尋ねました。","respondent":"長尾建築課長、溝口公園課長","answer":"先ほどご説明いたしました、そういった対応しか位置づけがなかったのですけれども、占有者の方に対しての対応についても位置づけることで。 子供の森公園での児童相談所の建設の件ですが、実際平成３２年度ぐらいから工事に入っていく予定でおります。現状、現状としてはそういう利用もされているところもありますので、引き続き検討してまいりたいというふうに思っております。","id":"exchange-103"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは品川区がやって、国道と都道とどういう連携していくのかということ。それから、歩道が結構ひどい所があるので、そこら辺はどういうふうに考えているか。","respondent":"長尾建築課長、多並道路課長","answer":"区としましては、こちらのほうに注力してまいりましたが、平成２８年度で耐震診断のほうを９５％程度完了しているということがあります。今後は一般緊急輸送道路のほうも耐震化について進めていくという意思のあらわれというところで… いろいろ情報共有しながら新たな取り組み、進め方ということで、一緒に進めているところです。","id":"exchange-104"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから、できればその委託をする中に地元の方も、いろいろな要望も今出ていると思います。その辺の声をどのように結びつけていただけるか、その辺だけお答えをほしいと求めました。","respondent":"稲田都市開発課長","answer":"引き続きＪＲとの共同検討、それに伴う区の単独検討というのを行っていくというところと、新しく事業化検討業務というのがあります。整理をしておかないといけないのかというところで、境界の測量や道路の立体的な所の検討などをやっていくというところです。","id":"exchange-105"},{"speaker":"南委員","kind":"質問・要望","question":"それと、３１９ページの八潮地区の将来像検討経費についても伺います。そういう中で、前回と今回の違いは何なのかについて一つ伺いたいと思います。","respondent":"古巻防災課長、鈴木都市計画課長、溝口公園課長","answer":"避難所のご質問に対してのお答えになりますが、これまでもさまざまな形で、環境の改善をしていくような取り組みは進めていって動いているところです。… 八潮地区の将来像検討経費の今の状況ですが、先ほどご説明しましたとおり、あるいは勉強会をしています。団地に入居が始まったときの５社協定の今のあり方… もう平成１９年ぐらいからさまざまな計画、検討を進めながら今日に来ておりまして、平成２２年に説明会をしたという経緯があります。","id":"exchange-106"},{"speaker":"南委員","kind":"質問・要望","question":"その２通の意味というのはどういうことなのかなというのがちょっと気になったので、それを伺いたいのと、アンケートについて伺いたいと思います。も回収状況も含めて、どんな内容になっているのか、概括でいいですから教えてほしいと求めました。","respondent":"古巻防災課長、鈴木都市計画課長、溝口公園課長","answer":"避難所の環境に関してですけれども、災害関連死ということにつきましては、国も大変重要な課題であると認識をしているというふうには考えております。… これは１通お送りしますと、そのお子様等にもお答えいただきたいというところで、世帯の中で複数お答えいただくということで２通お送りしています。それか… 南側ゾーンも含めて計画段階から説明会等を開催し、また地域の方、そういった方々のご意見を聞きながら進めてきております。","id":"exchange-107"},{"speaker":"南委員","kind":"質問・要望","question":"受け止めて参加できるようにしていただきたいと思うのですけれど、どういうふうな形に呼びかけをされるのか、その辺について最後に１点伺います。ぜひこの点について、お伝えをしながら区がリードしてつくっていけるようにしていただきたいと考えていますが、いかがか尋ねました。","respondent":"鈴木都市計画課長、古巻防災課長","answer":"地域で活動されている団体の方の参加のあり方については、自治会の方々と相談しながら今後検討していきたいと思います。 先ほどの答弁でお答えしましたとおり、こちらも大事だというふうに考えておりますので、バランスよく進めていきたいと思います。","id":"exchange-108"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、本区内での夜間に起きる事件や事故はどのような所に起きているでしょうか。そして、１年を通して事件や事故が一番多く発生する時期や時間帯というのはあるのか尋ねました。","respondent":"多並道路課長","answer":"３ルクスを確保しなければいけないとか、防犯面を気をつけながら、ハード面という形で進めているところです。そういうソフト部門の連携も図りながら、より効果の高い場所というのを研究しながら設置していかなければいけないと思っているところです。","id":"exchange-109"},{"speaker":"木村委員","kind":"意見","question":"昼も夜も気を付けなければいけないということですね。希望等何かあれば、この道路にぜひ街路灯をお願いしたい」というふうなことでも構いませんので、あれば説明を求めました。","respondent":"多並道路課長","answer":"区の我々のほうに区民の方からお問い合わせのあった件としましては、やはり暗いということで、新しく設置するご要望等があります。適切な、先ほどの基準もございましたけれども、そういう一定の基準に則った一定の明るさを確保するような整備を進めているところです。","id":"exchange-110"},{"speaker":"木村委員","kind":"質問・要望","question":"今現在ある街路灯で事は足りているのかどうか。何かあればお聞かせをほしいと求めました。","respondent":"多並道路課長","answer":"いろいろな所管で防犯カメラなどいろいろな対策等もありますので、そういうさまざまな対策を組み合わせながら進めることが重要だと思います。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問・要望","question":"安全で安心なまちなのかどうか、理想のまちに近づいているのかどうか、この街路灯を通じてお聞かせを願いたいと思います。","respondent":"多並道路課長","answer":"区としましてはそういう観点をすぐに処理させていただいて、一日も早く安全にご利用いただけるようにということで、そういう面は日々心がけながら維持管理に努めているところです。","id":"exchange-112"},{"speaker":"木村委員","kind":"質問・要望","question":"ＬＥＤ型のものが今回は１,６６８基が約２億６,０００万、１本当たりで計算しますと１５、６万というところでしょうか。これが３基で３６３万３,０００円ですから、ざっと計算しますと、この差というものに対してわかりやすく教えてほしいと求めました。","respondent":"多並道路課長","answer":"街路灯につきましては、あとは電柱にくっついて頭だけついている物がありますので、そういう点では全体ですと安くなるというのがまず１点あります。","id":"exchange-113"},{"speaker":"木村委員","kind":"質問・要望","question":"そういうところに、公園等に何基か置いていくというような計画で、今進めているのか。それで、今現在、今回とっているのは３基でありますけれど、これからどのような計画になっているのか教えてほしいと求めました。","respondent":"多並道路課長","answer":"学校避難所に１カ所です。来年度の予算につきましては、安心安全のまちづくりに努めていくという観点で進めているところです。","id":"exchange-114"},{"speaker":"本多委員","kind":"質問","question":"交通安全の取り組みとしましては、これまでも品川区としていろいろな地図などをつくって対策をしてこられましたけれども、最近の状況をお伺いします。その皆さんは本当に毎日、ここは危ないと感じていますけれども、そうした声を活用できているのか説明を求めました。","respondent":"古郡交通安全担当課長","answer":"自治会、高齢者クラブのほうにも配布をして、安全啓発を図っております。区内の事故の状況ですが、平成３０年度では７８６件発生しているような状況で、前年度より２５件ふえているような状況です。","id":"exchange-115"},{"speaker":"本多委員","kind":"質問・要望","question":"平成２０年９月から平成２３年にかけて、今は補助制度がないのですけれども、自主返納、いろいろ取り組みをされてきました。ただ受付は警察のほうでされますけれども、区の役割としては自主返納を促すことだと思うのですが、その昨今の状況をお知らせください。","respondent":"古郡交通安全担当課長","answer":"当初は１２１企業だったのですけれども、サポート協議会加盟企業という形で、現在については２４９企業ということになっております。平成２８年度が４万２,０００件、平成２９年度は４万４,０００件という形になっており、非常にまた上がってきている状況です。","id":"exchange-116"},{"speaker":"本多委員","kind":"質問・要望","question":"最後のもう一押しが足りないとか、事故が起きてからもう少し遅かったとか思う前に、何か対策をしていただきたいと思うのです。は部をまたいで、例えば福祉部と一緒にこの課題について連携したり、そんな状況についてはいかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"現状に関しては警察と連携をしまして、状況を把握して、研究していくという形でやらせていただきたいと考えています。","id":"exchange-117"},{"speaker":"本多委員","kind":"質問","question":"あれからもう２４年がたちまして、改修の必要があるということなのです。その計画について説明を求めました。","respondent":"持田河川下水道課長","answer":"Ｋ字橋からちょうど新しくつくる桟橋ですとか、大崎橋広場などをちょうど見渡せる視点場としてよろしいというふうに考えてあります。それと、橋梁のライトアップなども、このふれあいＫ字橋の改修の一環としてやっていきたいというふうに考えてあります。","id":"exchange-118"},{"speaker":"本多委員","kind":"質問","question":"２９のうち７は鉄道事業者の橋桁ですから、２２の橋があります。この２２の橋につきまして、水辺を活用するということですから、その視点というのはどういうふうに捉えているのか。","respondent":"持田河川下水道課長","answer":"ただ、船の視点から見ると、満潮のときなどは背の高い船ですと通過できないようなことになってしまいます。ただ、なかなか橋のかけかえ自体というのは相当難しい部分もあるというのは認識しているところではありますが、橋梁の高さが決まっているです。","id":"exchange-119"},{"speaker":"本多委員","kind":"質問・要望","question":"そのふれあいＫ字橋は舗装等もやりますけれども、ほかの２２橋も景観よくやってほしいと求めました。山手線でも２カ所あって、本当に色があせているなと思うので、ぜひその辺も鉄道会社に働きかけをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"どういうニーズを想定して、取りつけ道路をつくって乗降場所をつくるのか伺います。品川区が当初目指したものと少し違ってきているように見える駅前広場計画をつける必要はないのではないかというふうに思うのですが、見解を伺います。","respondent":"東野まちづくり立体化担当課長","answer":"それからお年寄りの方を対象といたしまして、安全な乗降場を設けていきたいという考えから、計画をしているものです。それから、こういう連続立体交差化事業を契機として駅前広場を考えなさいよということを、計画しているものです。","id":"exchange-121"},{"speaker":"吉田委員","kind":"質問","question":"歳入のところでちょっと伺いましたが、予算額が８１５万３,０００円です。区として取り組むときには、福祉の担当課との連携が欠かせないと考えますが、その辺の連携についてはいかがお考えか尋ねました。","respondent":"東野まちづくり立体化担当課長、森住宅課長","answer":"高架下の活用につきましては、委員がおっしゃるように、地元の声も受けた形で一緒に検討してまいりたいと思ってあります。これについては、駅周辺にも結構な影響があるということを受けて… 課長レベルでの協議を今年度８月に実施をしておりまして、福祉部それから子ども未来部とお話をしています。","id":"exchange-122"},{"speaker":"吉田委員","kind":"提案","question":"立体交差化のほう、まだこれから、検討していないことも合わせて、もう一体としてやったほうがいいのではないかなというのが私の提案です。だからやはりその辺の必要性も、周辺のニーズ等もきちんと聞き取りながら福祉政策とあわせてぜひ有効なものにしていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"３３７ページ、がけ・擁壁安全化支援事業について伺います。平成２８年度から、２年がたちましたが、その中で工事に至らない理由というのも確認をさせてほしいと求めました。","respondent":"長尾建築課長","answer":"所有者の方自身が、そういった擁壁に関して余り維持管理をするという認識がそもそもないといったところもございました。その改修に向けての合意形成といいますかお話し合いを重ねていくというところで、時間も労力もかかるというような側面もあるかと考えます。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"ちょっとまだ影が見当たらないというところで、これは私どもも、また品川区としても求めていただきたいというふうに思います。ここの６８カ所について、また対象にどうしてもならない箇所、箇所数をお願いしたいと思います。","respondent":"長尾建築課長","answer":"特に安全性を図る必要のある６８カ所に関しての、所有者等を個別に調べているわけではございませんので、どういった方がお持ちなのかというところは区では今は把握しておりません。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"とにかくまずは安全化支援のために実績を上げるということが今、建築課に求められる仕事、使命だと思います。ご相談、何とか品川の地域の安全化支援をしていただきたいなという思いで要望しますけれども、ご答弁をお願いいたします。","respondent":"長尾建築課長","answer":"がけ・擁壁の改修工事の対象の扱い含め、現在実績として出ていない状況もあります。現在の支援制度の対象に関してだけではなくて、支援のあり方、後押しになるような形というものをもう少し検討しながら。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ、３年目に入る事業の実績をとにかく上げていただきたいというふうに強く要望します。このスケジュールを何とか遅らせないために、品川区はどのようなことに着目をして、配慮をしながらやっていくのか、この確認だけさせてください。","respondent":"鈴木都市計画課長","answer":"スケジュールどおり進めるに当たっては、この辺もしっかり進めないと、しっかりしていかないといけない。事業認可主体の運輸局ですとか、あるいは交通管理者、道路管理者、こういったところとの協議もしっかり進めていかなければいけないです。","id":"exchange-127"},{"speaker":"伊藤委員","kind":"質問","question":"私から、３２１ページ都市計画費の立会川・勝島地区まちづくり検討経費に関連して、それから、３０４ページの土木費の道路橋梁費に関して質問します。お願いいたします。","respondent":"鈴木都市計画課長","answer":"それから、どういった具体的な事業を行っていくかというところをより掘り下げて検討していくわけですが、ブラッシュアップをさせていただきました。具体的な事業の検討に当たっても、引き続き継続して地域の方と意見交換を重ねながら、検討を進めていきたいです。","id":"exchange-128"},{"speaker":"伊藤委員","kind":"確認","question":"今、指名競争入札で事業者を決定していくということをお聞きしましたけれど、プロポーザルがむしろいいのではないでしょうか。そのことの確認。","respondent":"鈴木都市計画課長","answer":"特に都市再生整備計画を策定していく中で、国費を受けながら具体的な事業を進めていくかという検討ですので、どちらかというと実務的な内容が主です。そうした選定を使って、しっかり来年度検討していきたいです。","id":"exchange-129"},{"speaker":"伊藤委員","kind":"質問","question":"その理由は、今まで池上通りまで出る道が３カ所あったのが、一方通行になって１カ所になったのが大きな原因であるというわけであります。お願いいたします。","respondent":"多並道路課長","answer":"大井町駅周辺バリアフリー計画の中で、より安全に通行できる空間の確保という観点で、計画に上げさせていただいておりました。説明会も開きながら、平成２９年度に工事を実施して、進めたところです。","id":"exchange-130"},{"speaker":"伊藤委員","kind":"意見","question":"正しかったのかどうか非常に疑問になるわけで、あわせて聞きたいのが、今後の渋滞対策をまずはどう考えていくかということが１点。お願いいたしますとの意見を述べました。","respondent":"多並道路課長","answer":"そういう将来的な面も踏まえて、または都市計画道路の整備の状況を踏まえながら、いろいろ意見交換をしながら進めてきたところです。交通状況を見ながら柔軟に、よりよい形ということはそれはもちろん、今後も検討していかなければいけないと思っているところです。","id":"exchange-131"},{"speaker":"伊藤委員","kind":"意見","question":"なぜこんなことが気になるかといいますと、大井町という名前ではないのです。お願いいたしますとの意見を述べました。","respondent":"多並道路課長","answer":"今、委員のご指摘のとおり、大井町のまちづくりという観点で利用者の目線でご利用に不便がないような形でまちづくり、今、いろいろな部署と連携しながら進めていきたいと思っているところです。","id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３３１ページの公衆便所整備費から伺っていきたいと思います。この改築や改修が行われるのですが、洋便器化ということは、いわゆるだれでもトイレではないということなのか尋ねました。","respondent":"溝口公園課長","answer":"私どもが進めているのはもう、洋便器化ということで、今現在、和式の便器がついているものを洋式に変えていきます。それをしっかりやっていきたいというところで考えているです。","id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"確認","question":"では、今申し上げた中で、もともとだれでもトイレの洋式になっているところもあると思うのです。今おっしゃったとおりに、和式が洋式便器化されるだけということで、新たにだれでもトイレになるところはないということで確認をお願いします。","respondent":"溝口公園課長","answer":"大井町駅前の公衆便所については、新たにだれでもトイレも設置をします。そのほかについては、今現状のものを基本的には和式から洋式にかえていくといったところで考えているものです。","id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、今年度改修・改築される公衆便所の中で、今現在、だれでもトイレにしてほしいという要望が上がっているところはあるのかどうか。そうした声を把握されているのかどうか伺います。","respondent":"溝口公園課長","answer":"西大井については身障者対応のだれでもトイレになりますが、その３カ所についてはだれでもトイレの整備をしていくような形になっております。そういった中でも、まずは洋式化をしっかりやっていきたいということでご理解をいただきながら、現在事業を進めているところです。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ベビーカー、介助者がここに入れるような、障害者も使えるようなだれでもトイレにしていくべきではないでしょうか。そして、洋式化をしっかり進めたいということですけれども、どうしてこの方針が決まっていったのかを伺いたいと思います。","respondent":"溝口公園課長","answer":"方針の決定ですが、あくまでもオリンピック・パラリンピックに向けてトイレの洋式化、これまでさまざま声をいただいてきたところです。まずは公衆便所の洋式化、それをしっかり取り組んでいきたいということで事業を立ち上げているものです。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが地方自治体が進めるべきことではないでしょうか。伺います。","respondent":"溝口公園課長","answer":"鉄道利用者ということであれば、やはり鉄道の事業者がしっかりバリアフリー化の対応をしていくべきというふうに考えております。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問","question":"それを鉄道事業者がやってくれないからこそ、区が、区管轄のトイレだからこそやるべきではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"この居住者の大半が避難できる、収容できる場所というのは、この品川区は用意しているのでしょうか。説明を求めました。","respondent":"古巻防災課長","answer":"東京都の被害想定であります避難所生活者数１２万人ということが言われておりますけれども、それに基づいた計画で、指定をしているです。ですから、多少そのバランスが悪くなるということはあるかもしれませんけれども、区全体として収容できるような体制を考えているところです。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"だから、平均的に場所がありますから、確保されていますよ、という返事なのですか。ところが、避難しようとしたら、遠方に行かなければできない、というような状況ということなのか尋ねました。","respondent":"古巻防災課長","answer":"遠方にということではなくて、地域の中でバランスを考えて避難をしていただくというケースは出てくるのかと思います。それに取り組んでいただくためのマンションの防災対策ということも進めておりますので、そういったことも含めて、これを進めているところです。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"移動もしにくい、さらに救援しようとしても、では３０階まで誰が上がっていくのですか。少なくとも通信やエレベーターを使える自家発電設備などのライフライン、復旧できる設備をどれぐらいのマンションが持っているのか尋ねました。","respondent":"古巻防災課長、稲田都市開発課長","answer":"ここから高層マンションが危険だということではなく、マンションのそういった危険に応じた対策をとっていく。対策について、区としても支援をしていく部分があれば支援をしていくことが重要だというふうに考えております。７２時間の発電ができるということで、それによってエレベーターやその他電気等で必要なものを動かしていくです。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"ではそれはいざとなったらどうするのですか。どれぐらいの高層マンションが、こういう自家発電装置等を持っているのか尋ねました。","respondent":"長尾建築課長","answer":"非常時の消防活動用に使われるような非常用エレベーターの設置であるとか、排煙設備、非常用照明の設置などが義務づけられております。先ほど都市開発課長が申しました、基準法によって義務づけられているもの以上のものとして自主的に設置されているものです。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"下におりるのも大変で、一度下がってしまったら上になかなか上がってこられない。区としても対策を考えて、民間と何とか連携してやってほしいと求めましたが、一言だけ答弁をお願いします。","respondent":"古巻防災課長","answer":"マンションの防災対策は区としましては、１つ大きな課題だということで、対策に力を入れているところです。","id":"exchange-143"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"洋式化はいいのだけれど、こういうところをどこかでわかりやすく説明してほしいというのが１つ。だからこの辺のところも、水族館をどう考えていらっしゃるかというのも答弁いただきたい。","respondent":"溝口公園課長","answer":"改めて、これまでも平成２２年に出たご意見を踏まえた中で、説明をしながら設計・工事を進めていきたいというふうに考えているものです。","id":"exchange-144"},{"speaker":"石田（秀）委員","kind":"提案","question":"そのときに、建物の魅力、活用をいろいろご案内したり、それはいいのだけれども、１つだけこういう提案をします。そういうことをぜひ言ってほしいと思うのだけれど、その辺の提案をお願いしますとの意見を述べました。","respondent":"長尾建築課長","answer":"毎年１軒、２軒という形でなっておりますので、ご提案いただいた内容につきましてはちょっと研究をさせていただきたいと考えております。","id":"exchange-145"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３２１ページ、３０３ページ、交通安全についてお伺いします。このＷｉ－Ｆｉは、震災が起きたときにいわゆる０００００ＪＡＰＡＮのような全開放型のＷｉ－Ｆｉになっているのか説明を求めました。","respondent":"鈴木都市計画課長、古郡交通安全担当課長、古巻防災課長、山本情報推進課長","answer":"その作成に当たっては、現在設置しております地域交通検討会を活用しながら行っていくです。それから２０２０年度は、さらに検討を進めながら… ２０代から５０代の働く世代への啓発なのですけれども、あらゆるところで警察署と連携してパンフレットを配っていく。は今後… 区民避難所、合わせて１２万７,０００人分の避難所のスペースを確保しているというふうに、計画上考えているところです。","id":"exchange-146"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"交通安全はぜひ、駐輪場ということはそこにいる人は自転車に乗っている人なのですから、一番対象者ではないですか。では、この五反田リバーステーションを利用して、具体的に何を発信していくのかというのを説明を求めました。","respondent":"持田河川下水道課長","answer":"五反田水辺が結ぶプロジェクトですが、方針としては川と人を結ぶとか、住む人と働く人を結ぶ、地域と来街者を結ぶというような考え方です。この五反田のにぎわい方、区内の水辺のにぎわいにもつながることではないかというところで進めているところです。","id":"exchange-147"},{"speaker":"石田（し）委員","kind":"意見","question":"東品川との行ったり来たりで誰が、新しいお客さんが五反田に来てくれるのかというのが、そこが疑問なのです。だったら、そういう所からお客さんを五反田に運んで、ぜひそういった大きい視点で考えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それから３３１ページの公衆便所費、３３９ページの空き家等対策事業、そして３２６ページからの公園管理費について伺いたいと思います。先ほども質問があったのですけれども、洋式の便器にかえるだけなのか、そのことについて伺います。","respondent":"溝口公園課長","answer":"今回計画していますと、荏原町の公衆便所については洋式化のみで考えております。だれでもトイレの設置も相当検討はしてきたのですけれど、そこについては洋式化のみという形で今、建設しています。","id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この問題、私も議会の中でも何回か取り上げまして、２０１４年のときの決算特別委員会でも取り上げました。あれば、車椅子が使えるような形でのトイレが何とかできないかというふうに検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"古郡交通安全担当課長、溝口公園課長","answer":"荏原町駅の駐輪場の改修については、駐輪場のところが雨漏り等していますので、そういった雨漏り対策だとか外装の塗装をかえるだとか、そういったところで改修をするものです。 今回は荏原町駅の駐輪場の改修については、新たに建てるわけではありませんので、今のものを使うような形になっております。そういった中でいいますと、あくまでも私どもは、洋式化に向けた改修をやっていくということで計画しています。","id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて、車椅子の方も使えるようなトイレへの改修を強く要望しておきますので、ご検討よろしくお願いいたします。一日も早く対策をとってほしいというさまざまな要望が、区のほうにも届いていると思いますし、私も言ってきたところです。","respondent":"森住宅課長","answer":"先ほど委員のほうからご紹介いただきました立ち入り調査については、１２月１７日に建築課と一緒に実施をしたところです。今後命令に移っていく中で、一定期間必要だと思うのですが、その後行政代執行という形で法律にのっとって進めていきたいと考えております。","id":"exchange-151"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ地域から、また町会から対応を求めるような声が上がったときは、ぜひ対応を進めていただくようにお願いしたいと思います。土地探しなども含めて、区のほうで積極的な対応をぜひお願いしたいと思うのですが、具体的なところでぜひお聞かせほしいと求めました。","respondent":"森住宅課長、溝口公園課長","answer":"西中延の空き家につきましては、命令それから行政代執行と進めて、夏ぐらいまでには実施していきたいというふうに考えております。 区内の約２００ぐらいの町会・自治会の中、公園・児童遊園を有さない町会というのが３０あります。そういった中、今すぐに適宜、公園にできる適地を探しながら、整備を引き続き考えていきたいというふうに思っているところです。","id":"exchange-152"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで実際に実現をしてほしいと。このことを強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"こんの委員","kind":"提案","question":"ベビーカーや自転車の車輪がはまってしまうということもあって、舗装がはげてしまってほとんどマナーが守られていないという状況が確認されています。踏切の安全対策と歩道橋の利用促進のためにエレベーターの設置などを提案させていただいてきましたとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"朝の踏切の状況についてはかねてから認識しておりまして、そうした声があるということも以前からこうした場でご質問いただく中で把握しています。なかなかその用地の確保というところが難しいところとして、区として認識している状況です。","id":"exchange-154"},{"speaker":"こんの委員","kind":"提案","question":"自転車ですよ、歩行者ですよ、とわかる看板が見える位置に設置をし直したほうがいいというふうに思うのです。このような提案ですけれども、いかがか尋ねました。","respondent":"多並道路課長","answer":"設計を平成２８年度にする際に、できるところということで、今のような形でやっているところです。住民の皆様の声を伝えながら、改善を図るようにということで、今後も続けていきたいと思っているところであります。","id":"exchange-155"},{"speaker":"こんの委員","kind":"提案","question":"大森駅歩道橋についてはさまざまな角度から提案してきたところです。直近ではエスカレーターの運転時間の延長を求めて、ここを利用する区民の方からさらなる利便性向上の要望などがありますので、取り上げしますとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"北口のほうは、そうしたところで駅構内のエレベーターの設置と一体的に進める必要があるというところが一つあります。こういったところを進めるに当たっては、やはり大田区と協議を進めながらしっかり進めていかなければいけないというところが１点あります。","id":"exchange-156"},{"speaker":"こんの委員","kind":"質問・要望","question":"なのでそこの要望はやはり品川区が上げていかないと、要望していただきたい、このように思います。この二葉一丁目の住宅について、その日陰の制限というのはどういうことをいうのか説明を求めました。","respondent":"鈴木都市計画課長、森住宅課長","answer":"北口の品川区側のエレベーターの整備については、より効果的な一体的な整備が行えるように、ＪＲ、大田区とともにあらゆる機会を捉えてやりとりをしていきたいです。二葉一丁目区営住宅のエレベーターの設置に関してですが、エレベーターの設置を検討した中では北側の公園側、あるいは図書館。","id":"exchange-157"},{"speaker":"こんの委員","kind":"質問・要望","question":"最後に要望だけします。ぜひ防災課のほうで音頭をとって、きちんとそこが整備されるようにしていただきたい、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"渡部委員","kind":"質問・要望","question":"であれば、今現状考えている段階でわかれば教えていただきたいのは、どういうメンバー構成になるのか。名前は変わるにしても立場的にはそのような方でというところで結構なのですが、その辺、どういう会議体になっていくのか説明を求めました。","respondent":"鈴木都市計画課長","answer":"お尋ねのコミュニティバスの検討の際ですが、平成２６年に設置をしました地域交通検討会の中で具体的な内容を検討していきたいです。その中で、あと交通管理者、道路管理者も含む形で検討を進めていきたいというものです。","id":"exchange-159"},{"speaker":"渡部委員","kind":"確認","question":"その次の年には実施計画を出して、またその次の年には運行にこぎつけてというような流れで確認はさせていただいているのです。ばんばん実務的に進めていくのか、その辺の進め方と、会議体の回数とをそれぞれ教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"ここにつきましては、いろいろな視点から検討を進めたいですが、使われ方をしているかということはしっかり整理をしていきたいというところです。これを先ほどの地域交通検討会、今のところ２度ほどの開催を考えてありますが、お諮りしながら整理をしていきたいというところです。","id":"exchange-160"},{"speaker":"渡部委員","kind":"質問","question":"幾つかお伺いできればと思うのですけれど、今このタイミングで２年後でしょうか、そういうのは何かあったりするのでしょうか。走らせたら、この期間は補助金がつくというような、わかれば説明を求めました。","respondent":"鈴木都市計画課長","answer":"今、詳細に細部にわたって把握し切れていないところがありますが、今回の来年度の委託導入については、国の補助を受けて検討委託を進めるのですが、実際の運用についてはちょっと詳細には把握し切れていないところです。","id":"exchange-161"},{"speaker":"渡部委員","kind":"質問","question":"去年でしょうか、結局その収支率を５０％以上に保つことというような中で、では今後どうしようかという検討が始まっているみたいです。ゼロベースでスタートなのか、ある程度ビジョンがあってスタートしようという感じなのか、その辺教えてほしい。","respondent":"鈴木都市計画課長","answer":"来年度以降しっかり検討していくのですが、やはり品川区内の鉄道あるいはバスを含めた公共交通網は、他区と比較しても非常に高い充実度があります。","id":"exchange-162"},{"speaker":"渡部委員","kind":"質問・要望","question":"３３１ページの子どもたちのアイデアを活かした公園づくり基本構想策定のところで確認ですけれど、これも１０年前に、幾つか公園ができたわけです。その辺の考え方、みたいなものがあるのであれば、あわせて教えていただけますか尋ねました。","respondent":"溝口公園課長","answer":"今後検討していく中で、広く愛される公園づくりというのは検討していきたいというふうに思っております。同じような形でやっていきたいと思いますし、できることなら少しでも広く意見を聞けるような形をとっていきたいというふうに考えているところです。","id":"exchange-163"},{"speaker":"渡部委員","kind":"質問・要望","question":"１０年に１回でなくても、ずっとそういうのは続けていただければいいのかなと思ったりするのですが、大変でしょうから、そこは結構です。その昔の遊具といったらおかしいのだけれど、子どもがチャレンジできるような遊具を置いてもらいたいのですが、物理的に無理なのか尋ねました。","respondent":"溝口公園課長","answer":"やはり子どもというのは遊びを通じていろいろ体験することによって成長していくというところがあります。で、そういったところをしっかり見極めながら、公園の整備に当たっていくです。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/778040?Template=document&Id=1100#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":128337,"voices":393}},{"id":"r01-20190313-3","meetingId":"r01-c-budget","date":"2019年3月13日","dateIso":"2019-03-13","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を135件整理しています。","topics":[{"id":"topic-01","title":"平成３１年度品川区一般会計予算","agenda":"平成３１年度品川区一般会計予算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"私からは、３６７ページ、タブレット端末運用について、３５９ページ、オリンピック・パラリンピック教育推進事業について伺います。タブレット端末の運用について伺います。","respondent":"篠田学務課長、熊谷指導課長","answer":"委員からは２,０００台ということでお話がございましたけれど、その後、およそ２,３００台程度を使っていただいているような状況です。増やす予定はございませんが、あわせて各学校のＬＡＮ工事を進めてありますので… ＩＣＴ推進校と、推進校では子どもたちが自分の意見や考え方を説明する場面で活用するなど、タブレットＰＣを使った授業スタイルが定着しています。授業改善に非常に役立つということで、校長や教員からは評価されているところです。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"タブレットの中のデータを使って個々人のデータの把握というのができているのかも伺わせてください。続けて伺います。","respondent":"篠田学務課長","answer":"ですので、そういった意味では、使い過ぎることはあまりないのかと考えているところです。教育委員会では全体の各学校ごとの比較等、それぞれデータを慎重に扱いながら、整理しています。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"続いて、オリンピック・パラリンピック教育推進事業について伺います。オリンピック・パラリンピック教育について、机の上での学習ではなくて、それ以外の部分で、これまでどんなことが行われたのか、説明を求めました。","respondent":"熊谷指導課長","answer":"今お話がありましたように３競技体験教室、そしてブラインドサッカーの体験教室を、全ての学校で実施しています。３月２２日に天王洲公園で行われるブラインドサッカーワールドグランプリ２０１９で、それから協会ブースの手伝い等のボランティアを行う予定です。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"提案","question":"この壁をどうにか壊せないかという意味合いでの提案をします。非常に難しいと理解はしていますが、学校を背負わせて、東京五輪ではなくて品川五輪みたいなものを子どもたちでできないのかというのもご提案しますとの意見を述べました。","respondent":"熊谷指導課長","answer":"運動会でのミニオリンピックの実施についてですけれども、保護者、地域の機運の醸成につながると考えます。陸上競技大会はこれまでも行ってきていますので、そういう中で実施していくことは可能だと思います。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"では、最後にレガシーについて伺います。区として、オリンピック・パラリンピック終了後の教育の中でのレガシーを残す取り組みについて、最後にご説明ください。","respondent":"熊谷指導課長","answer":"それは、１つは障害者理解、ボランティアマインド、そして豊かな国際感覚。それを考える１年にしていきたいと考えています。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"事務事業概要では、デジタル教科書のバージョンアップ委託として約３００万円が予算づけされておりますので、ここで関連してお伺いします。デジタル教科書がどのように活用されているかお伺いいたします。","respondent":"篠田学務課長","answer":"あるときから学校単位でのライセンスに変更されまして、最新の状況でどれだけの数のお子さんが使われているかというのは把握し切れていない状態です。そちらのほうの意向もございまして、こちらは今、２校で使われているような状況があります。","id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"約３０人の方がアクセス・リーディングを活用していると伺ったことがありますが、またデジタル教科書についてお伺いいたします。この文字がどこかで活用されているのかということを１つ確認しますが、ぜひこの字の活用を提案いたしますが、ご見解を伺いますとの意見を述べました。","respondent":"篠田学務課長","answer":"特別支援のｉＰａｄに関しましては、ＵＤフォント自体がインストールされていない。当然、さまざまな環境を整えた上で、必要に応じて使えるような形で整備をしていくというようなことを考えているところです。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご相談があったという場合でありますけれども、全ての考え方の中で、標準服としてスカートやスラックスが選べることが求められていると思います。このことをぜひ品川区でも推進してほしいと求めましたが、ご見解を伺います。","respondent":"大関教育総合支援センター長","answer":"現在、区立学校における、標準服につきましては、各学校ごとに、同窓会あるいはＰＴＡ等の意見も聞きながら決めてきている経緯があります。各校単位で、教育委員会といたしましては、各校の自主性を尊重したいと考えております。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も、標準服、制服について伺いたいと思っています。私もいいことだと思っているのですけれども、区内では、今まで、また現在、こうした声は出ていないのかどうか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"ＰＴＡのご意見なども聞きながら、比較的、標準的なものというものを１つの目安としてお示しするという形で決まっております。ＬＧＢＴへの配慮などにつきましても、それは、これまでも実際に申し出があった場合には、個別のケースとして対応させていただいているところです。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"スラックス、２０１５年４月に文部科学省から、性同一性障害の児童や生徒に対するきめ細かな対応を求める通知が出されています。そしてそれを認め合う社会が求められているということですので、女はスカートと決まっていること自体が、区の見解はいかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"学校が一律にこうあるべきだということばかりではなくて、時代の流れとともに検討する部分はこれから生じてくる場合もあろうかとは思います。そこにつきましては、今後とも情報をよく収集してまいりたいと思います。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"女子用のスラックスの採用に肯定的な意見・回答が半数以上を占めたということもあって、こうした選択ができるということを取り入れたということです。さまざまな意見があるということですので、意見を聞くためのアンケートなども保護者や生徒にしてはどうかと思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"昨今、国や都あるいは区からの多くのアンケート調査が来る中で、非常に学校は疲弊しているという現実もあります。収集しており、校区教育協働委員会などの場で意見を交わす場面もありますので、そういった部分を尊重してまいりたいと思います。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"性の多様性が求められており、それを認め合う社会が求められているというところですので、媒体として使っていくべきではないかと思います。風潮というのですか、こうしたところには必要ではないかと思いますけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"今年度も私は見てまいりましたが、どこかの学校ではこういう取り組みが、自分たちはこう取り組んでいるというのを参考にしていった。そのような取り組みを大切にしています。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、各学校で設置されている目安箱についてですが、生徒から意見や要望などはありましたでしょうか。あわせて伺います。","respondent":"大関教育総合支援センター長","answer":"目安箱の件数および内容、対応につきましてご質問いただきました。その子どもの気持ちを酌み取りながら、必要な対応については学校とも共有し、本人の悩みの改善・解消に向けて努力していく。","id":"exchange-013"},{"speaker":"松永委員","kind":"質問","question":"次に、いじめのアンケートについて伺います。そこで質問いたしますが、現在、本区では、生徒に対してアンケート調査というものは行っているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"両方うまく組み合わせながら子どもたちの様子を知る取り組みは、月に１回程度、何らかの形で子どもたちの声を拾う努力はしております。アンケート、そしてアンケートだけでは拾い切れない部分は目安箱で、活用していきたいと考えています。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"先ほどの質問に戻るのですが、４８件の目安箱の中に、虐待に関する意見はあったのでしょうか。お伺いします。","respondent":"大関教育総合支援センター長","answer":"先ほどの４８件の内訳の中に、まず書いてあった内容としてのところには、直接、虐待を受けていますという書き方はございません。そういったことが把握できるという状況がありますので、そういった場合にはすぐに関係機関と情報を共有して、確実に対応しています。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"より子どもたちが申告しやすいように、アンケートをぜひ加えていただければと要望し、次の質問に移ります。ホッケーやビーチバレーボール、子どもたちはボランティアとしてオリンピック・パラリンピックに参加することはできるのか、あわせて伺います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ボランティアの件について私からご説明させていただきたいと思います。ただし、まとめて何か手伝っていただくとかボランティアに参加していただくというのは、今後検討していきたいと思っているところです。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問・要望","question":"サッカーでよく見かけるシーンですが、入場するときに選手と手をつないで入場するということは可能なのでしょうか。その辺について伺います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"先般、決定したところで、区に挨拶ということでいらっしゃっています。今後の検討事項といいますか、大会組織委員会の方たちと相談しながら、区の子どもたちにいい思い出が残るような形に持っていきたいと思っています。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"学校にはない環境がそろっていることを考え、ぜひ学校とスポル品川大井町で連携してみてはと思うのですが、いかがでしょうか。施設が開設されてから今日まで、教育の一環として利用されたことはあるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"いろいろな競技といいますか、アスリートたちのお話を聞いたり、実際に体験するということがございました。各ご家庭で、親子でスポーツ体験を楽しんだとか、そういうお話は聞いているところです。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"次に、３６９ページの学校環境整備事業について伺います。その理由についてあわせて伺います。","respondent":"有馬庶務課長","answer":"今回、補正をとりまして検討しておりますけれども、基本的にはガス式ということを中心に、今、考えております。今、そこを中心に検討を進めているです。","id":"exchange-019"},{"speaker":"松永委員","kind":"確認","question":"２０４４年まで人口が増え続けると聞いておりますが、プールの敷地分、校舎を増やすという考えはあるのでしょうか。今後について最後に伺いたいと思います。","respondent":"有馬庶務課長","answer":"プールの解体は改築のためにいたしますけれども、その後、またプールは校舎と一体型というようなことで屋上に設置していく予定です。その間、使えない期間について、近隣の学校を使用するような対応を考えているものです。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"次に、品川区内の公立小・中学校の生徒・児童に対しては、現状はいかがですか。これも説明を求めました。","respondent":"大関教育総合支援センター長","answer":"本区におきましても同様に不登校件数は増加している傾向です。そういったものを早目に発見して、関係機関としっかりと情報共有して、複数の愛で、こぼれることのないように支援しようと努力している最中です。","id":"exchange-021"},{"speaker":"須貝委員","kind":"確認","question":"それは、担任の先生がやはり忙しいということにも起因しているのでしょうか。そういうこともあるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"これはもう、さまざまな経験のある、いろいろなタイプの教員がいますので、一概に年齢が浅いだけで厳しいとは考えておりません。どの教員も考えておりますので、忙しかったので自分の担任するクラスの子どもの様子がわからなかったという学校はないと捉えております。","id":"exchange-022"},{"speaker":"須貝委員","kind":"意見","question":"でも私は、ないということは隠れているのではないかと教育委員会には見てほしいのです。それで、やはり信じてあげるということが第一だと私は思うのですが、その辺についてご見解を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"そのほか、特別な支援の配慮の観点から、専門のカウンセラーが２週に一遍、やはり担当校を回っております。本区の取り組みについては常に、定期的に専門の方のご意見などもいただきながら、見直しを進めているところです。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"２週間に１回、カウンセラーの方が来られても、それは何か結局、お子さんにとってはお客さんではないのですか。相談できそうだ」というのを感じるのが子どもたちだと思うのですが、その辺について、時間などあるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"中学生においては、１行、何かしら、今度は子ども自身が書いたことに対して、担任が少しだけアドバイスを入れたりというのを工夫したりもしています。日ごろから、学年保護者会あるいは全校保護者会などで、校長より各家庭にもお願いしています。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、どうなのですか。皆さんも子どもたちをしっかり見て１対１で向き合ってくださいというお願いを出すべきではないかと私は思うのですが、その辺についてどうか尋ねました。","respondent":"大関教育総合支援センター長","answer":"やはり支援ブックを各家庭に配布させていただいたり、さまざまな形で家庭支援も、子どもたちへの指導と同時に進めているところです。学校での対応は、二重、三重で取り組んでいくことが大切だと考えております。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"蹴とばしたり殴ったりして、もし万が一、大きなけがでもしてしまったら、それこそその面倒を見るのは親ですから。ですから、今後、教育委員会でもしっかり、やはり家庭にもっとお願いして、もう、文書でも配るなりしてやってくださいと。","respondent":"大関教育総合支援センター長","answer":"さまざまな課題はあろうかと思います。今後、都の条例がどのように定まっていくのかも注視してまいりたいと考えています。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"時間があれば３６３ページ、４目図書館費、図書館運営費について伺います。区の測定は、食の安全を確認するためにもこれからも継続し、より検査を向上させるためにも単品検査への転換を求めますが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"単品検査ですけれども、現在、これまでやってきた放射能検査におきましても、基本的には放射能の検出がほとんどない。単品検査に転換するといった考えは、今、持ち合わせていないものです。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"教育委員会として、この価格に対してどのようにお考えなのか伺います。必ず指定のものを購入しなければならないのかということもあわせて伺います。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"豊葉の杜学園の９学年、ファイルは置いていっていいですよ」というふうに全て示したものを、子どもの家庭にも示しています。そのようにして工夫を各学校、学年ごとにしています。そういったものも含まれた価格であるということであれば、一定程度、現状の価格も合理性があるのかと考えるところです。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"２０１８年の第四回定例会で、学習指導要領を超えた性教育の実施を求めましたが、学習指導要領を遵守した形で教育を進めていくとのことでした。区は、都とどのように連携を図っていくのか伺います。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"標準服のリサイクルの関係で１点ございました。ただ、あくまでＰＴＡが自主的に行われているものですので、それぞれの判断を尊重してまいりたいと感じるところです。 東京都が現在、性教育の指導の手引を見直しているという情報は得ております。得次第、都と連携を図りながら、有効な授業の内容につきましては検討してまいりたいと思います。","id":"exchange-029"},{"speaker":"田中委員","kind":"確認","question":"予算に子ども読書活動推進会議が計上されていますが、新たな計画の策定は進んでいるのでしょうか。伺います。","respondent":"横山品川図書館長","answer":"子ども読書活動推進計画のお尋ねです。委員ご指摘のとおり、来年度１年間、検討期間を設けまして、翌々年度に新しい計画を実行するつもりです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"他自治体では、預金通帳型の読書の記録システムを導入しています。読んだ本からこれだけの知識の貯金ができたと確認できるおもしろいシステムなので、ぜひ区でも参考にしていただければと要望いたします。","respondent":"横山品川図書館長","answer":"読書貯金通帳についても、全国に普及している状況を見まして、検討を進めてまいりたいと思います。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"先日、消費者センターなどとの連携を効果的に実施していただきたいのですが、教育委員会のご見解をお伺いいたします。悩みやトラブルに直面する前に、性・性教育を教育現場で伝えていただくことを要望いたしますが、区のご見解をお伺いいたします。","respondent":"熊谷指導課長、大関教育総合支援センター長、高山子ども育成課長","answer":"それが規範意識を育てるということで、一緒に清掃をするというようなことも行いました。次年度もさまざまな大使館との交流、アメリカ合衆国、スイス… そして事後学習１時間、合わせて１５時間が１つのユニットとなっておりまして、例えば収支バランスといったことを考えるような場面があります。… 児童センターで実施しております赤ちゃんとのふれあい事業の件について若干補足します。今年度で発足から１１年を迎えまして… 追加させてください。","id":"exchange-032"},{"speaker":"横山委員","kind":"提案","question":"品川区においてグローバル時代にはどのような教育が望ましいとお考えでしょうか。世界の成り立ちを理解するプログラムについて、区のご見解をお伺いいたしますとの意見を述べました。","respondent":"熊谷指導課長","answer":"相手の意図や考え方をしっかり理解して、世界の国々の方々と、臆せずに積極的にコミュニケーションを図ろうとする態度が重要だと考えています。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"世界でリーダーシップを発揮できる大人になるためには、新しい知識を次から次へと学んでいくことがこれから求められると思います。子どもたちが大きな器を持てるようにサポートすることで、それが可能になると私は信じておりますが、最後に一言お願いいたします。","respondent":"熊谷指導課長","answer":"そして、その中で、世界にはいろいろな考え方があるのだといったことを授業の中で学んでいくということが重要だと思います。そうした視点を大事にしながら、世界ともだちプロジェクトも含め、進めてまいりたいと考えます。","id":"exchange-034"},{"speaker":"つる委員","kind":"質問・要望","question":"３月１３日、公明党の柏原ヤス参議院議員が無償化の全面実施をするべきだということで強く求めて、当時の質疑を確認しますと。もし区独自で実施した場合の経費になるというような答弁を確認していますけれども、その財源をどこに求めるかは別にして、無償化になった際に。","respondent":"篠田学務課長","answer":"入学される際に銀行口座を登録していただいて、そこから自動的に引き落としをするというような形です。現状は、仮に無償化がされまして負担がなくなったといったとき、その辺の負担がなくなるといったことが考えられるところです。","id":"exchange-035"},{"speaker":"つる委員","kind":"質問・要望","question":"まさに憲法が求める理想に近づく施策の展開の仕方ではないのかと思いますので、公明党としては学校給食無償化を求めていきたいと考えていますが。給食施設整備費に関連してですが、事項別明細書を確認させていただいたところ、小山台小学校が給食室全面改修工事ということで載っておりました。","respondent":"篠田学務課長","answer":"小山台小学校につきましては、給食室を全面的に改修工事を行うということで、時期的には一定の期間がとれるということで、夏休みの時期を予定しているものです。","id":"exchange-036"},{"speaker":"つる委員","kind":"質問","question":"夏休みの時期で、２学期までまたぐか、またがないか説明を求めました。","respondent":"篠田学務課長","answer":"工程につきましてはこれから検討してまいりますけれども、場合によっては最長では２カ月という事例もあったのですけれども、要は２学期に入って工事が行われるという事例もございました。","id":"exchange-037"},{"speaker":"つる委員","kind":"提案","question":"すまいるスクールの部分で配食サービスを提案しておりますが、既にほかの２３区で見ても、３区で実施しているというところもあります。その注文の仕方も、別の款で提案させていただきましたけれども、非常にやりやすいとの意見を述べました。","respondent":"篠田学務課長","answer":"現状は、委員ご指摘のとおり、保護者の方にお弁当を用意していただいてお持ちいただくという形で対応しています。アレルギー対応をどこまでできるのかといったところが、私どもとしては、なかなか踏み切れないようなところがあります。","id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"５歳以上、さらにトイレの確保、それから十分な暑さ対策に対する支援策も求めているところではあります。どういう考え方かというところと、別段で求めている保育園・認定子ども園も含めた子どもたちが全員行けるということも求めたいと思いますけれども。","respondent":"熊谷指導課長","answer":"園から目的地までの移動時間を１時間までとしているということから、もしくは、駅から会場までが歩ける範囲ということで依頼しています。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問・要望","question":"細かい部分だけれども配慮してとっていくべき課題なのだろうと思いますので、教育委員会としても、強く東京都に対して求めてほしいと求めました。図書館経費については、機会があれば求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"おくの委員","kind":"質問","question":"そこでお伺いいたします。お伺いいたします。","respondent":"熊谷指導課長","answer":"次年度、得点を上げるための指導を行ったとしても、実際にはそれは何の役にも立ちません。なぜならば、本区の調査、それから都の調査、国の調査も、同様の問題が出るわけではないからです。","id":"exchange-041"},{"speaker":"おくの委員","kind":"質問","question":"やはり、それに即してお伺いいたします。お伺いいたします。","respondent":"熊谷指導課長","answer":"テストがある教科に上乗せしたというところがあるようなのですけれども、本区におきましては教育課程をしっかり指導主事が管理しております。","id":"exchange-042"},{"speaker":"おくの委員","kind":"質問","question":"それを聞いて一応、安心しました。今は解決していると思いますけれども、品川区では、４月に行われたものを独自に採点・分析しているという実態は過去にあったのか尋ねました。","respondent":"熊谷指導課長","answer":"区は６月に返却しておりますし、９月ということは、これは都のほうではあるかと思いますけれども、やりやすい状況になっております。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"３５７ページ、３６７ページ、学校ＩＣＴ活用経費についてお伺いいたします。何か品川区独自の特色、工夫というのはやられているのかを、まずお聞きいたします。","respondent":"大関教育総合支援センター長","answer":"理数教育につきましては、観察・実験などによって科学的に探究する学習活動がとても重要だと、新たな学習指導要領でも示されております。理科実験の支援員を学校に配置するなどのほか、発達段階、本人の習熟度に応じた確実な学習の定着というものを工夫しています。","id":"exchange-044"},{"speaker":"筒井委員","kind":"意見","question":"小学校はそうした実験や活動を重視しているのに対し、中学校は知識重視ということで、小・中の校種間で比較すると少し違ってくると。算数・数学が好きだという肯定的回答を増やしていく手段というのは、今後、品川区としてはどう対応していくのかを説明を求めました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"入ってすぐのときに、本人の学びたい課題に応じて、教員たちが指導・対応する時間なども確保しているところがあります。こちらの教育会につきましても、教育委員会がずっと講師派遣料等の支援を行っているところです。 教科等検討部会で、どこが子どもたちが苦手なのか、一貫教育の中で子どもたちが苦手とするところを補完する教材を作成しています。来年度、完成する予定です。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問・要望","question":"次に、地域の歴史・文化学習についてお伺いいたします。今現在、品川区ではどういった取り組みをされているのか、また課題がありましたら説明を求めました。","respondent":"大関教育総合支援センター長、有馬庶務課長、篠田学務課長","answer":"まだ歴史と文化がありますので、地域の歴史・文化について、子どもたちが自分自身で調べたり発表したりなどという学習も行っております。… まず区立学校全校が掲載されている学校史、まず自分の学校の歴史を知ろうというもので、「品川の教育」という冊子も発行しています。平成２４年度からは… こちらを選定した理由は、特に小規模校が多いのですけれども、１つ、学校の特色として打ち出すためにしたものです。","id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"このような性感染症の蔓延の中で、学校教育の現場では、現在、性感染症に対してはどのような受けとめがなされているのでしょうか。前回もお聞きしましたが、その後、何か進展があったかどうかお聞きしたいと思います。","respondent":"大関教育総合支援センター長","answer":"避妊具を活用することも性感染症の予防には役立つというところまでが示されてありますので、そこまで９年生で扱うという状況になってあります。","id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"個々の生徒に配慮して行うことを東京都教育委員会は求めているが、５１校が集団指導のみ行っていると回答したということを発表しました。これに対して品川区としては、どのような受けとめと対応をお考えか尋ねました。","respondent":"大関教育総合支援センター長","answer":"この３つをしっかりと守った上で、対象をきちんと区別した状態で、保護者の理解も得た上で行うべきだというような内容。モデル授業の実際の取り組みの例なども、今度の新たな手引においては示されるという、そこまでの情報を得ているです。","id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"その上で、性感染症の予防、避妊に対する具体的な教育がなされるべきだと考えます。この点に関して品川区はどのようにお考えなのか、ご見解をお伺いします。","respondent":"大関教育総合支援センター長","answer":"委員よりご指摘があったように、そして他者のことも大切にするという、そこは市民科でしっかりと学ぶべきことがまずは土台だと考えております。","id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問","question":"医療の専門家が担当して、子どもにしっかりと具体的な内容と、それの理屈づけを教えるべきだと思います。このような団体をも利用して、いろいろとウイングを広げていくべきだと思いますが、区のご見解はいかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"区内にも保健予防課と関係機関もありますので、そちらよりしっかりと情報収集をして研究してまいりたいと思います。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"９万６,０００円が新規計上ということで、各会派からも要望が出ているところですが、計上されたことは非常によかったのではないのかと思います。それで、９万６,０００円という金額の積算の根拠、そして何をもって専門的講師というのかについて教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"例えば公認会計士ですとか、いわゆる士業という資格をお持ちの方の場合には、１時間当たり８,０００円という報酬規定を定めてあります。２時間行ってもらう学校が６校あったとした場合に、まずは６校程度やっていきたいと、学校の応援をして状況を見ていきたいと考えております。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に、給食運営費で２つほど伺いたいと思います。どういう内容を請願の内容について送られたのかというところを教えてほしいと求めました。","respondent":"篠田学務課長","answer":"請願の内容は、プラスチックストローを使わないようにということを、東京都や学校給食会、乳業者に声を上げてほしいという内容のものでございました。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問","question":"何か反応はありましたでしょうか。いろいろ東京都の動きがあったので、総括で行いたいと思いますけれども、まず品川区に対して何か反応があったのか伺いたいと思います。","respondent":"篠田学務課長","answer":"直接的には、お送りした後に、こちらに対するリアクションというのはなかったのですけれども、担当者の方の話しとして、例えば乳業者の方々ですと、ほかの地域からもそういった声が少しずつ上がってきていますというような声はいただいているところです。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"お子さんのことを伺うと、それは学校側の許可を得てやっているということもあったのですが、このような話は教育委員会として把握はされていらっしゃいますか。","respondent":"篠田学務課長","answer":"一部の学校で、そういった形で保護者の方からお申し出があったという形では伺っております。それで、各学校とも可能な範囲で対応していくと聞いております。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"約２万人の区立小学校・中学校の生徒がいるのですけれども、何人に対してどのような対応を行っているのか、わかれば教えてほしいと求めました。そこについても伺いたいと思います。","respondent":"篠田学務課長","answer":"そのほか、基本的にアレルギーの物質・食材を除去した形で対応していただいている方が４６６名ほど。１食しかつくらないというのは、昼食の取り違え等があると非常に危ないということがありまして、そういう対応をとっているものです。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今まで教育委員会もしくは学校に対して、こういう宗教上の理由で学校給食への配慮を求められたという例があったのか、ないのか。これについて伺いたいと思います。","respondent":"篠田学務課長","answer":"今年度に関して申し上げますと、現在、宗教上の対応をしているお子さんが全部で１９人ほどいらっしゃいます。ただ、必要な対応をさせていただいてありますけれども、こういった信条等にかかわるものに関しては学校では対応ができないということで。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、ギフテッド教育のことについて伺いたいと思います。そういう才能あるお子さんというのは、それとあわせてやっているようなのですけれども、この辺についての情報があれば教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"そのときに本人に苦手さがある部分については、どのように克服していくかという部分は、通級指導学級等で、自立活動として支援を行っている段階です。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３５１ページの就学援助費、３７１ページの給食運営費について、給食費無償化を求めて質問します。生活保護に連動して引き下げないように求めますが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"生活保護基準の変更に伴う就学援助費の取り扱いです。したがいまして、私どもは基本的には現行の水準を引き続き維持する方向で考えているところです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"アベノミクスによって格差と貧困が広がっているということもありますので、就学援助の役割というのはますます高まっているのではないかと思います。さらに基準を上げて、対象を広げていくということが求められているのではないかと思いますが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"現在、就学援助に関しましては、おおむね、ここ数年、２割前後の認定率の水準を保っているところです。現状では著しく悪化しているという話も聞いていないところですので、今のところ、この水準を変更するような考えは持っていないです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、就学援助のいわゆる入学準備金について伺います。ぜひ、国の変更に合わせて、区でも増額してほしいと求めましたが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"就学援助の新入学の学用品費につきましては、これまで長い、かなりの期間にわたりまして、２万円程度で変更なしで来たところです。平成３２年度の前倒し分からは、改めて引き上げを予定している予算を、平成３１年度予算案として組んでいるところです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"確認","question":"来年度からにはなっています。これは準要保護世帯についても増額されるということでいいのかという確認と、額の設定の理由、根拠を伺いたいと思います。","respondent":"篠田学務課長","answer":"考え方としましては、そういったことも踏まえながら、区として判断してまいりたいと考えているものです。準要保護世帯につきましても、この基準で支給しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、就学援助の標準服の支給について伺いたいと思います。この標準服の支給金額を、ぜひ実態に合わせて実費支給にすべきだと思いますけれども、いかがか尋ねました。","respondent":"篠田学務課長","answer":"就学援助の場合は、標準服に限らず基準額を設けた形で、必ずしも満額を支給しているものではございません。標準服があるということでの補助をしているですので、一定額の補助という考え方を、今のところ変える考えはございません。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"ぜひ実費支給をしていくべきだと思いますけれども、標準服の平均額というものがわかりましたら、教えてほしいと求めました。実費支給をしていくことで、教育の機会均等という面からも適しているのではないかと思いますが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"男子の場合がブレザーと半ズボンで２万１,６９０円、女子がブレザーとつりスカートで２万４,２００円となっています。そことの均衡を図るといったところでいきますと、なかなか実費支給、全ての金額をお支払いするといったところの考えまではいかないものです。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"私はしていくべきだと思いますけれども、いかがでしょうか。入学前からの標準服の資金の支給も求めたいと思いますけれども、いかがか尋ねました。","respondent":"篠田学務課長","answer":"こちらは学校によって対応がさまざま異なるところがあって、購入したものに関して領収証等を見せていただいたりといった事務的な作業があります。その関係で、事前の支給が今のところはされていないということがあります。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ機会均等の面からもやってほしいと求めましたし、今、これとあわせて実施していくということはできないのでしょうか。無償化を求めると、なぜそれで足りていると言えるのか、伺いたいと思います。","respondent":"篠田学務課長","answer":"前倒し支給ですけれども、１つは前倒しのタイミングなのですけれども、要は学校の就学指定の関係で確定していないということがあります。学校教育法に基づきまして、食材費だけをご負担いただいているということがあり、これ以上の無償化に係る対応は考えていないものです。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際にやはり給食費は保護者の方が負担しているということになりますので、そこを無償化していくということが必要なのだと私は思います。憲法にも、第２６条に義務教育は無償とするとありますので、給食費の無償化はぜひ品川区から踏み出していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"渡辺委員","kind":"確認","question":"３６１ページ、学校地域連携推進経費で、コミュニティ・スクールのことを伺ってまいります。この基本情報を確認のために説明を求めました。","respondent":"熊谷指導課長","answer":"これに加えてアシスタントコーディネーターを、必要に応じて、特に３年目を迎えた学校には配置しています。報酬につきましては、それからアシスタントコーディネーターは平成３０年度については１,０００円となっているところです。","id":"exchange-067"},{"speaker":"渡辺委員","kind":"質問","question":"この辺についてのお考えを教えてください。そこまでお願いします。","respondent":"熊谷指導課長","answer":"ですので、今後また柔軟性というところについては検討してまいりたいと考えています。すみ分けをどうするかということを十分に検討した上で実施しているところもありますので、それについても今後の課題と思っています。","id":"exchange-068"},{"speaker":"渡辺委員","kind":"質問","question":"どうこうという思いもないのですが、これはまだ本当に初期段階ですから、ぜひともお願いします。理想的な、あるいは望ましい体制は、どのようなものか説明を求めました。","respondent":"熊谷指導課長","answer":"週に４回ぐらいやっている学校もあります。コーディネーターが大学に赴いて、学生課に行って、ご案内していただいた上でご紹介いただいているといったようなことがあります。","id":"exchange-069"},{"speaker":"渡辺委員","kind":"質問","question":"２点伺います。そんな仕組みがどうかというのも踏まえて伺って終わります。","respondent":"熊谷指導課長","answer":"今度はもしかすると、一斉にというのではなくて、地域ごとにということも考えられるのではないかと思います。ケーブルテレビ品川等も情報提供することで、より一層、区民の方にコミュニティ・スクールについて知っていただく機会としていきたいと考えています。","id":"exchange-070"},{"speaker":"大倉委員","kind":"質問・要望","question":"３５５ページ、３６６ページの学校教育費で、その辺について伺えればと考えています。子どもたちの対応をするところで、時間帯が早いから連絡ができないということも解消されるのかと思っているのですが、いかがか尋ねました。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"今それは所有者と、売る、売らないの検討をこれからしていくという形になってくると思います。ただし、今までの経過もありますので、先方と十分協議していきたいと考えています。 欠席連絡の対応ですが、保護者の方より、毎日のことではないので、やはり状況については直接お聞きしたいというのが担任の立場です。担任が直接対応できなくても、やはり直接やりとりをするのは重要だと、現段階では考えます。","id":"exchange-071"},{"speaker":"大倉委員","kind":"質問・要望","question":"通学安全確認業務等委託費で、変更がなければいいのですが、そういったことがあるのかどうか教えてください。随分前から都にも、そういったスクールゾーンを土曜日も設置ができるようにということで求めていっていただいていると思いますが、お願いいたします。","respondent":"大関教育総合支援センター長、有馬庶務課長","answer":"私からは、まずいじめ対応についてです。登校のときに、誰が入れたのかわからない状況で集めるとか、さまざまな工夫があろうかと思います。もし変更が必要な場合につきましては、学校はもとより、新たなところは設定するということを考えていきたいと思います。","id":"exchange-072"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかりと取り組んでいっていただきたいのと、関係機関と連携して取り組んでいってほしいと求めましたので、よろしくお願いいたします。スマートフォンというのが、なかなかないのかとは思っているのですが、小・中学校の現在の対応についてお知らせください。","respondent":"大関教育総合支援センター長","answer":"スマートフォンの対応ですが、現段階においては従来どおり学校には持ち込まないということです。持つことによる登下校中のデメリットの部分のところを、バランスも見ながら検討していく必要があると、現段階では考えているところです。","id":"exchange-073"},{"speaker":"大倉委員","kind":"質問","question":"まもるっちのようなものがあれば、別に買わなくてもいいのではないかという、中学生の保護者の意見も聞いております。その辺の対応について、これは所管が違うから答えられないのかもしれないですけれど、考え方を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"学校の立場からの答えということになりますが、中学生の段階になって、キッズ携帯をまず持ちたがるかという現実の課題が１点あります。学校には持ち込まないというルールをどうしていくかというお話と、また区別して検討してまいりたいと思います。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問","question":"いまだ保護者からは、防災頭巾はどうなのでしょうかというところでの疑問を投げかける方が結構いらっしゃるです。品川区として、ヘルメットか防災頭巾かみたいな話も含めてですけれども、どのように考えているのか、最初にお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"３年間だけではなく６年生までは使いたいという部分と、単価は２,５００円から３,０００円と、小学校の状況です。例えば体育館に行くときに持っていってお尻の下に敷いたり、そういった活用も実はとても小学生は重宝しているのが防災頭巾の実態だと思います。","id":"exchange-075"},{"speaker":"塚本委員","kind":"質問","question":"学校側から何かしら、保護者に対して防災頭巾を用意するに当たっての情報提供というようなことは、どのような状況になっているのかお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"１００％、「防火のアルミのような生地が表面に塗られているものが、非常に耐火機能も高いのでいいです」という形でご案内はしております。多くの方は示めされたものを、最初の入学前の段階、学用品をそろえる際にそろえられている状況にあるのだと思います。","id":"exchange-076"},{"speaker":"塚本委員","kind":"質問","question":"防災頭巾が適している場合や、貸与というような形で考えていってほしいというような思いもあるのですけれども、どのように考えられますでしょうか。最後に伺います。","respondent":"篠田学務課長","answer":"１つは置き場の問題で、防災頭巾を使っている子、やはりその辺の整理の関係等も出てくるものと思います。経費的にも、通常のヘルメットよりもかなり高いと聞いておりますので、その辺も研究していかなければいけないといったところです。","id":"exchange-077"},{"speaker":"塚本委員","kind":"質問","question":"これについて、まず区としてどのように対応を考えていらっしゃるのでしょうか。教員の意識改革、文化の改革という点についてお伺いします。","respondent":"熊谷指導課長","answer":"ですので、どんなに環境を整えても、教員自身が自分自身の働き方に対する価値観や意識を見直さない限り、何も変わらないと考えております。ですので、チャンスは今と考えているところです。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問","question":"１つは、確かに今日はもう時間だから早く帰った。単に労働時間だけで見ていってはいけないのだというような思いが私としてはありますけれども、そこについてのご見解をお伺いしたいと思います。","respondent":"熊谷指導課長","answer":"まず一昨年の９月から、働き方改革を進める上で、学校としての在校時間も含めて情報提供しています。保護者の理解、広報しながわの教育特集号で、教員の働き方改革についてもお示ししてご理解をいただくという努力を毎年行ってきているところです。","id":"exchange-079"},{"speaker":"塚本委員","kind":"質問・要望","question":"とはいっても働き方改革ということは大事なことの１つだと思うので、今後とも取り組みをというところでお願いしたいと思います。より一層、強く生徒に伝えていただきたいと思うのですけれども、最後に一言だけご答弁をお願いします。","respondent":"篠田学務課長","answer":"各学校におきましては、今年度から全部の学校で歯磨き指導を進めているところです。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"３５９ページの英語の学習について伺いたいと思うのですけれども、２３区、英語の先生の人材についてどういうふうにお考えになるか。その辺の考え方を説明を求めました。","respondent":"熊谷指導課長","answer":"本区におきましては、ＪＴＥと呼ばれる英語専科指導員で学習指導を行っております。ＪＴＥのような仕組みをとって英語の授業を行うということは今のところ聞いておりませんので、特に不足するということにはならないかと考えています。","id":"exchange-081"},{"speaker":"大沢委員","kind":"質問","question":"でも、見たとおりですから、表現のとおりということです。その中で伺いたいのは、１年生から６年生まで、将来的に子どもたちにどのような影響を及ぼしていくのか。","respondent":"熊谷指導課長","answer":"ただし、そこでなのですけれども、やはり国語というのは全ての知的活動の基盤であると考えています。ですので、やはり国際化社会の中で育っていくためには、伝統文化と国際理解の両方を重視することが重要ではないかと考えております。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"子どもたちはどうもそちらへ流れていくような気がしてならないのですけれども、その辺と日本語の兼ね合いというのでしょうか、授業の兼ね合い。どういうふうに行おうと考えていらっしゃいますか。","respondent":"熊谷指導課長","answer":"そういったものについても、心を育てるという意味で、さまざまな教科の中でも取り入れております。心も育てつつ、そしてまた新たな未知の世界への憧れといったものも持たせていくことが、本区ではできるのではないかと感じております。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"グローバル人材はどういうことかという定義は、もう皆さんご存じですから、どのように先生方は教えていらっしゃるのか。それはどのように、世界から見た日本の国土の位置はどのように教育されているのか説明を求めました。","respondent":"大関教育総合支援センター長","answer":"輸入している、輸出しているというものは社会科で学んだり、さまざまな教科の場面で指導は行っております。その場合に、まずは日本を中心に置いてある地図から導入しております。","id":"exchange-084"},{"speaker":"大沢委員","kind":"意見","question":"日本海は湖のように見えたりするわけですが、その辺の逆転の発想によって、子どもたちに対する日本の位置関係。逆さ地図については、先生方の裁量によるとは思うのですけれども、そのあたりは資料として使われておりますかとの意見を述べました。","respondent":"熊谷指導課長","answer":"ほかの国から日本がどのように見えるのかといったことを知ることも、グローバル化の中、世界の中で生きる日本人として必要なのではないかと思います。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここからが質問なのですが、品川区で行われています性教育の内容を、ざっくりと教えていただきたいのが１点。２点目は、足立区立中学校の授業の後、都教育委員会から何らかの指導がありましたか尋ねました。","respondent":"大関教育総合支援センター長","answer":"７年生になりますと、もう少し具体的に生殖機能の成熟について、性とどう向き合うかなども出てまいります。ここの部分を確実に守っていく必要があろうかと思います。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"都教育委員会のモデル授業について、区教育委員会はどのように受けとめていらっしゃるでしょうか。ぜひ品川区でも、このようなモデル授業を実施していただきたいのですが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"都教育委員会がモデル実施した内容を含めまして、保護者の理解をどのような形でとって、どういうふうにモデル実施してこのような成果があった。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学習指導要領の範囲を超えた発展的な内容を盛り込む予定だと書かれておりますので、ぜひ品川区でもモデル授業のような中身でやってほしい。ぜひモデル授業を参考にして、医師や専門家、そして保護者の力を集めて、創意工夫して授業を行ってほしいと思いますが、改めて伺います。","respondent":"大関教育総合支援センター長","answer":"教職員全体の共通理解があること、そして保護者の承諾があるということをしっかりと踏まえた上で、プラスアルファの内容がどれだけ実現できるか。する場合には、今度の手引の中で１つの例として示されるというふうに、区としても内容を待っているところです。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういった中身としまして、ぜひ、新しい学校選択制のどこが子どもたちのためになっているのか伺います。こういった中身の学校選択制はやめるべきと考えていますが、いかがか尋ねました。","respondent":"若生学校制度担当課長","answer":"そういったことがやはり今回の大きな制度改正については必要だという認識のもと、こういった丁寧な経過措置をとったものです。若干、複雑化している部分については、今後丁寧に区民の皆様にご説明していくつもりですので、今後ともそういったことで取り組んでまいります。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問・要望","question":"災害時や交通事故の対策などの改善も全くなされていない中で、学校選択制はやめるべきであると思います。強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこで、５校の中で学んだ生徒に少しお話を伺う機会が何校かありました。安全性を担保しながらということで、地域の利用の方々の要望がありましたが、その点はいかがか尋ねました。","respondent":"大関教育総合支援センター長、熊谷指導課長、有馬庶務課長","answer":"私からは、就学前の特別支援教育の重要性についてです。お子さんの周りにどのような支援者の方がいて、とても大切な情報であると認識しており… 全校で実施となりましても、グローバル人材育成塾のコースは５０コースと変わらないため、実際のところの予算は増額にはなっていないところです。… 学校改築もしくは校庭の改修に伴う利用者への影響ですけれども、基本的には影響をなるべく少なくしていこうというのは児童にとっても同じことです。","id":"exchange-091"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校ファンドについてさまざまなポイント、ご要望や、どうしたらいいのだろうというアドバイスを求めてくる機会があると思います。もちろん中心になってということではないですけれども、側面からいろいろ相談にのる機会もあると思いますが、その点についてお伺いします。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"特別な配慮が必要なお子さんへの対応の内容ですが、今後とも療育支援ネットワークなどを通じて、情報をなるべく共有していきたいと思います。具体的に知能発達について、受けたケースにつきましては… そうすると、区の歳入という形になります。予算で配分できない理由、なぜ予算を使わないのかといった、しっかりとした理由が必要になってくるのではないかと思います。","id":"exchange-092"},{"speaker":"高橋（し）委員","kind":"意見","question":"特別支援のほうは、療育支援ネットワークと、保幼小の連携をぜひお願いします。学校ファンディングについては、新しい時代の新しい手法ですので、学校としてアドバイスをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"伊藤委員","kind":"確認","question":"タブレット端末の推進校が１０校、それから２,３００台が今、導入されていることを聞きました。１点確認したいのは、タブレット端末の種類は何なのかを説明を求めました。","respondent":"篠田学務課長","answer":"推進校に配付していますタブレットについてはWindowsタブレットを配付しているものです。","id":"exchange-094"},{"speaker":"伊藤委員","kind":"意見","question":"ということは、パワーポイントを活用してプレゼンテーションする。それができているのかということが１点と、当然やっていると思うのだけれども、その点に関してどうかということもお願いいたしますとの意見を述べました。","respondent":"篠田学務課長","answer":"なかなか子どもたちがどこまで使いこなせるかというのはあるのですけれども、活用することができるような環境は整えております。今、プロジェクター等を設置していますので、そちらにデータを流した上で映し出すといったことは可能です。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"提案","question":"パワーポイントなり何らかの形で使って、自分の意見を提案していくとか、それから、今の議会でもそうだけれども、資料提出ということをやるわけです。お願いいたしますとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"あるいはカウンセラーが直接学校に出向いていって、お子さん自身への対応あるいは監督支援の対応について学校にアドバイスもします。要するに、担任が１人だけで抱え込んで時間だけが過ぎてしまう、これまで充実させてまいりました。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"確認","question":"あえて確認したのは、調布市の例もそうだけれど、大概、マスコミ報道で言われていることには、いろいろな共通する問題があるわけです。この問題は解決しないと思うのだけれども、幾つか質問しましたけれども、改めてご答弁をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"具体的に命の大切さを感じるさまざまな取り組みは、動物飼育などのモデルを実施したり、生きているというものを実感していく。そういった、学校と家庭で連携して子どもを育てていくことが重要だと考えております。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、確かなことは、義務教育の中で品川区の子どもたちにしっかりとその命の教育を展開していくこと。これは、児童・生徒一人ひとりの心に響く指導をどういうふうに具体化していくかということを、ここで説明を求めました。","respondent":"大関教育総合支援センター長","answer":"毎月第１・第３の土曜日が基本となりますが、人ごとではなくて、自分たちにもいつ起きるかわからない。「やめようよ」と言えるような、いじめ撲滅・根絶に向けた子ども自体が考えていける取り組みを、これからも大切にしていきたいと思います。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"提案","question":"それから、教育指導費に関連してなのですけれども、私ども自民党の提案によって、教師の家庭訪問が復活しました。それから、大切なところは、全ての児童・生徒の家庭を訪問しているのかどうかということについてもあわせて説明を求めました。","respondent":"大関教育総合支援センター長","answer":"ご提案いただいた以降も、家庭訪問は区立学校では継続して行っております。さまざまな背景というものがやはり見えますので、今後も教員負担がゼロとは言いませんが、家庭訪問は大切な把握の機会と捉えています。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"意見","question":"今、相当、マスコミの注目を集めている虐待の発生はほとんど家庭です。それから家庭での状況と学校の様子をしっかり見た上で、子どもたちを健全に指導していっていただきますように、お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"若林委員","kind":"質問","question":"２２.６％増といっても、品川区教育の大きな課題に立ち向かう、非常に大事な事業なのだというようなメッセージもあると思います。冒頭、その辺、メッセージといいますか、前年度比、大幅に増額された教育費全体について、教育委員会のメッセージをお聞きしたいと思います。","respondent":"有馬庶務課長","answer":"細かいですけれども、サービス向上のための継続経費ですとか、いろいろなところで見直しをした結果です。今まである事業をしっかり平成３１年度は行って、次の承継に向けてしっかり行っていくという予算を編成したと考えております。","id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"特に、私が聞きたいのは、兄弟姉妹枠について、４月の確定状況を教えてほしいと求めました。それから、兄弟姉妹枠の中で、やむなく当該学区域に引っ越しをした人、世帯というのですか、その数がわかれば説明を求めました。","respondent":"有馬庶務課長、大関教育総合支援センター長、篠田学務課長","answer":"大槌町には義務教育学校が１つあるということで、その学校の様子なども視察してまいりました。心の傷を負った子どもたちに対してどういうふうに寄り添って… ２３０件分を予算計上していますが、昨今、特別支援教育の必要なお子さんの数が非常に増えているという実態があります。特別支援教室の対象者は… 抽選で漏れて、さらに指定校変更等の申請をされた上で無理だったといった方につきまして、正確な数字はまだ集計していないのですけれども。","id":"exchange-102"},{"speaker":"若林委員","kind":"質問・要望","question":"望ましくない点をお聞きしましたけれども、やはりどう考えても、望ましくない点が大き過ぎる。こういうタイミングで、ぜひしっかり知恵をまた出し合って、兄弟姉妹枠の問題をしっかり検討していただきたいと強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"３５５ページ、教職員支援経費、教員の超多忙化解消について伺います。勤務を命じられていない土日祝日に学校に来た際にも打刻できるようにし、教員の真の勤務実態を把握するよう求めますが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"それで、本区に視察に来た中で、こういうものがあるといいのだけれども、なかなかつくるのは難しいので、押印は押印の出勤簿。副校長の負担を倍増することになってしまうということがありますので、本区としては、現在考えていないです。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問","question":"それで、今は何か副校長の話をしていますけれども、そのためにＩＣＴがあるのではないですか。それを軽減するために、システムをきちんと変えればいいと私は思うのですけれども、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"４時間以上は現在、特殊勤務手当が４,０００円出ていますので、また施設管理人日誌等にも記録している。把握する手段としては、そういった部分、また実際に教員から管理職に報告するよう指導しています。","id":"exchange-105"},{"speaker":"安藤委員","kind":"質問","question":"私は昨年第１回定例会の一般質問で、「１時間の授業に１時間の準備ができるように、教職員定数を決めている」。伺いますが、区は、教員の持ち時間数が多過ぎるということが、教員の長時間労働の大きな要因の一つだと考えているのかどうか伺いたいと思います。","respondent":"熊谷指導課長","answer":"全都では過労死ライン８０％なのですけれども本区では１８.６％ということで、人的支援が整ってきた成果ではないかと思っています。ただ、それにしてもやはり副校長の在校時間が最も長いということについては看過できないとは考えております。","id":"exchange-106"},{"speaker":"安藤委員","kind":"質問","question":"改善はされているということでしたけれども、では品川区教育委員会としては、教員は十分に時間内に授業の準備ができているという認識なのですか。私が伺ったのは、教員の持ち時間数が多過ぎることが教員の長時間労働の大きな要因の一つではないのですかと伺ったので、もう一度、答えるよう求めました。","respondent":"熊谷指導課長","answer":"先ほどお伝えしましたように、超過勤務、いわゆる在校時間がほかの区市町村と比べて非常に少ない状況であります。やはりさまざまな支援ということで、こうした支援で、それで授業準備ができると考えています。","id":"exchange-107"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際に現に教員の負担がどうなっているかというのは、よく教員の実態を伺って、対策を打ってほしいと私は思います。すぐにできるのは、現場の教員の方の意見を聞いて業務を削減していただきたいのですけれども、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"そういったことも含めて考えていく必要はありますけれども、少なくとも本区においては、負担をできるだけ減らすようにしています。本区の取り組み、リーフレットが全校に配られたということもありますので、引き続き続けていきたいと考えています。","id":"exchange-108"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、３５２ページ、教育指導費、それから３６９ページ、学校体育施設整備費から伺います。それで、やはり改めて教育委員会として、こういう実態があるということを認識していただきたいのですが、その辺についてご見解を伺います。","respondent":"篠田学務課長","answer":"こちらに関しましては、具体的には教育委員会には、そういった形でご相談等は上がってきていない状況です。特に取り扱いについて変更する予定はございませんけれども、例えば今後、それはその時点で改めて検討させていただければと思います。","id":"exchange-109"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで対応を求めたいと思いますが、後でご答弁を伺います。それから、避難所の機能強化ということなのですけれども、どの程度の機能強化を考えていらっしゃるのか見解を伺います。","respondent":"篠田学務課長、有馬庶務課長","answer":"そういった場でも、確認しているところではあるのですけれども、今のところ学校からはそういうご意見はいただいていないという現状があります。今後、実際には学校によってかなり柔軟に対応しているところもありますので… 今回入れる機器につきましては、要するに電源・電気がない場合には使用できないということになります。体育館で長期・短期にかかわらず生活するということになったときに、そこにきちんとした空調機能を持った設備を導入していこうです。","id":"exchange-110"},{"speaker":"吉田委員","kind":"質問・要望","question":"国民生活センターにはもう相談が倍増しているという実態がありますので、その辺はぜひ感度を高く持ってほしいと求めました。そういうときに、きちんと区民に伝わるように配慮してほしいと求めましたが、見解を伺います。","respondent":"有馬庶務課長","answer":"基本的には、電気がなくても使えるのかと思われている方がどの程度、いるかというのはわかりませんけれども、それをやるとすると、相当大きな機械が必要になってしまうので、それはできませんということは、防災課とも協議しながら、その周知には努めたいと思います。","id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"質問","question":"そのときのお昼はどうしているのですかというのを、まずお聞きしたいと思います。こういうところを、今、現状どう捉えていて、これをどうしていこうとお考えなのか、その辺をお聞きしたい。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"基本的には、その日、宿泊している宿でお昼のお弁当をつくってもらう。出発するときに、各お父さん、お母さんたちに渡していくという状況です。野球部が今あるところをどういうふうに支援していくということで、別の学校から野球部に参加するという形が可能なように取り組んできたところです。","id":"exchange-112"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは、品川区はそれが当たり前でやっているのだとしたら、ほかのところはどうしているのですか。だけど、その学校には部活がないなどということがあったりすると、ではどうしようとなるじゃないか尋ねました。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"校外施設の利用の際の昼食です。食中毒が起きないような形で、朝渡すときには、少なくとも食中毒が起きたりしないような配慮はしてまいりたいと考えております。 各学校ごと、地域の少年野球のチーム等もあろうかと思います。そういった中で、区外等の校長も含めて情報共有をして、子どもにとってよりよい方法という部分を模索してまいりたいと思います。","id":"exchange-113"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこはぜひ理解していただいて、外部という話もあるけれど、うまくいくような形をぜひとってほしいと思います。こういうことがあってもいいのではないのかと私は思うのだけれど、その辺の考えをお教え願いたいと思います。","respondent":"大関教育総合支援センター長","answer":"さまざまな研究をなされていて、投稿されたものをまとめてくださったものを提供してくださったことがありました。学校の教育の中でも非常にありがたい機会だと考えておりますので、またそういった、活用について検討します。","id":"exchange-114"},{"speaker":"石田（し）委員","kind":"確認","question":"３５３ページ、３６９ページ、３７１ページの通学安全確認業務等委託についてお伺いします。通学安全確認業務ですが、これはどういったところに委託して、どのような確認をするのか。","respondent":"篠田学務課長、大関教育総合支援センター長、菅生活安全担当課長、熊谷指導課長、有馬庶務課長","answer":"ＩＣＴの友好都市との連携についてのお尋ねです。今後、意見交換ができるのであれば、それは１つの今後の品川区のＩＣＴの発展に役立つものになるの… この間、さまざまなソーシャルネットワークの中で、さまざまな国民の意見が書き込まれています。もうしばらく情報収集しながら… まもるっちの有料オプションの加入率につきましては、全体の約７割と聞いております。それを見据えて、来年度から８年生で、英会話のオンラインレッスンを全校展開していく予定です。２５分のものを年間１０回考えております。","id":"exchange-115"},{"speaker":"石田（し）委員","kind":"確認","question":"通学路のどういったところが危険だと思うかという地図を、そういったことというのは今でも続けられているのかどうか、そこだけ確認させてください。生徒指導ですが、教育委員会として今年の１月に起こった都立高校での教師の暴行動画について、まず皆さんがご覧になられたのかどうかお聞きします。","respondent":"大関教育総合支援センター長","answer":"ああいった状況の背景全部を動画だけでは見られませんけれども、やはり、ただ１つ言えるのは、暴力はあってはならない。そうなる前の段階で、どんな取り組みができるかという部分は、学校に突き付けられる、そして家庭にも突き付けられている課題だと考えております。","id":"exchange-116"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはりそこは保護者も含めて、どういう学校での指導をするべきなのかというのは、本当に真剣に考えなければいけないのではないかと私は思います。これは要望で終わりますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"３６７ページの学校図書館についてお伺いしたいと思います。そのあたりから少し教えてほしいと求めました。","respondent":"横山品川図書館長","answer":"学校図書室の名称についてですが、今は図書室という普通名称を学校の中では使っていると思います。用語の中で、図書館法ほかで学校図書館という言い方をしているので、通常の中では図書室という形で利用していると思います。","id":"exchange-118"},{"speaker":"南委員","kind":"質問","question":"改めて学校図書館の役割は何なのかを伺いたいと思います。品川区は、学校図書館につきまして、業務委託を今されていますけれども、いつからこういう形態になったのか、その理由は何なのかもあわせて伺います。","respondent":"横山品川図書館長","answer":"学校図書館への支援スタッフの派遣は、公共図書館から学校図書館への支援として行っているものです。その一環としまして学校図書館へ公共図書館から支援スタッフを送って、児童・生徒に読書習慣をつける強化をするということが目的です。","id":"exchange-119"},{"speaker":"南委員","kind":"質問","question":"その後、どういうふうに発展して子どもたちに提供されているのか、それを伺いたいと思います。それから図書館の役割について答弁がありませんでしたのでお願いします。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"学校図書館の役割につきましては、子どもに読書の習慣をつけていただくということを、環境として学校で整備するような形になっております。昭和２８年に学校図書館法制定によりまして、学校図書館というのが正式な名称になったところで… とても親切に教員の相談にも乗ってくれて、今度子どもたちを、授業で調べ学習に連れていきます。そのときにこんな協力も少ししてくださいなどという相談もできており、とてもありがたいのが品川区の学校図書館の実情だと思います。","id":"exchange-120"},{"speaker":"南委員","kind":"質問・要望","question":"１２学級以上ある学校には配置していると聞いてきたわけですけれども、それはそれとして、その点についての考え方を伺っておきたいと思います。その辺について教えてほしいと求めました。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"学校図書館に指導するスタッフにつきましては、週に１５時間派遣しておりますので、それを学校で適宜振り分けて使っていただくようになります。支援スタッフがいない時間につきましても… 図書担当の教員がおりますので、子どもたちにはしっかりと学校図書館の利用方法について、担当教員が指導もしております。","id":"exchange-121"},{"speaker":"南委員","kind":"質問","question":"運営支援員、いわゆる業務委託をして採用されている方々の処遇についても少し伺いたかったのですが、勤務時間はわかりました。その辺について伺いたいと思います。","respondent":"横山品川図書館長","answer":"月に１回、また蔵書点検や夏の課題活動について、さまざまな行事での協力の仕方について計画するところです。報酬につきましては、一括の委託契約なので、個々の方へのお支払いについてはこちらではわかりかねます。","id":"exchange-122"},{"speaker":"南委員","kind":"質問","question":"そういう位置づけの学校図書館ですから、そういう点での偽装請負ということの心配は全くないのか、あるいは気がつかないでいるのか。そんなことはないと思うので、その辺についてどういうふうに見ているのか、体制があるのか、説明を求めました。","respondent":"横山品川図書館長","answer":"学校図書館へ配置しておりますスタッフには、必ず委託事業者から責任者がついております。何校かを担当しておりまして、計画の進行について把握している形になりますので、スタッフに一方的に指示が出るというようなことはございません。","id":"exchange-123"},{"speaker":"南委員","kind":"質問","question":"そしてまた、支援スタッフの方々の資格保有率というのはどうなのか。そこだけ説明を求めました。","respondent":"横山品川図書館長","answer":"支援スタッフの資格ですが、５９名、全体の５０名が司書資格または司書教諭の資格を持っている形で勤めています。子どもが本をというよりは、先生が授業で使うものについて手配して、公共図書館の協力・支援で配送して運ぶような形をとらせていただいております。","id":"exchange-124"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、３５５ページ、いじめ防止対策費、３７１ページ、普通教室増設工事、３７３ページ、学校改築推進経費の３点をお伺いしたいと思います。大人に求められることは、そもそもいじめが起きにくいよう、子ども同士のコミュニケーションを適切に介助できているかを見直すことが大事とあります。","respondent":"大関教育総合支援センター長","answer":"学級の中で浮いている子はいないのか、７年生の担任、そして管理職が一緒にコンサルタントを受けるという取り組みを継続しています。教員の指導力の向上は、今後も教育総合支援センターの業務として、教員研修の充実に努めてまいります。","id":"exchange-125"},{"speaker":"こんの委員","kind":"質問・要望","question":"いじめが起きにくい教室にするために、いじめが起きにくい教室をつくることが求められる先生への指導、そして子どもたちに振る舞う先生への何か支援。講じていないのであれば、今後、こういうことは考えていらっしゃいますか尋ねました。","respondent":"熊谷指導課長","answer":"それを防ぐために、また年次に応じた研修等も行っていくのですけれども、そうした資質を持っている教員も中にはいる可能性はあります。それが服務事故にもつながるということを、具体的な事例を踏まえて、校長連絡会等でこれまでも伝えてきたところです。","id":"exchange-126"},{"speaker":"こんの委員","kind":"質問","question":"校長はどういうふうに対応されているのか、何かありましたらご紹介ください。ありませんでしたら、今後どのように考えているか説明を求めました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"５分見れば、普段この先生がどんな授業をしているのか見えます。すぐに担当指導主事が学校に参りまして、管理職と情報共有しながら、必要に応じて学校だけでなく指導主事が授業観察を行うなどしております。そして心身ともに健康で、専門性を十分に発揮できる職場づくりということを管理職がつくっていく必要があると思います。","id":"exchange-127"},{"speaker":"こんの委員","kind":"意見","question":"そしてお互いを気遣うように、自分がかけてほしい言葉をかけてもらって、かけてあげて。」そういったコミュニケーションを職員室の中でもとっていける学校づくりが、より教室をいい環境にすると私は思うのですが、この点はいかがでしょうとの意見を述べました。","respondent":"熊谷指導課長","answer":"そういったことをしっかり把握していく。そういった学校づくりが重要ではないかと考えております。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問・要望","question":"最後、少し時間がなくなってしまいましたけれども、確認だけさせてください。６２３世帯入るタワーマンションができますけれども、山中小学校の対応は今後、大丈夫か尋ねました。","respondent":"篠田学務課長","answer":"人口推計については私どもも注意深く見守っているところです。山中小学校につきましては、現状の校舎の中でさまざまな工夫で、受け入れについては対応可能であると思っているところです。","id":"exchange-129"},{"speaker":"こんの委員","kind":"質問・要望","question":"対応が可能ということですけれども、１つ、いきいき広場、高齢者の方も使っていらっしゃるところでもあるので、空き教室がないと少し懸念しましたのでお伺いしましたけれども、大丈夫だということなので、そのまま進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"渡部委員","kind":"質問","question":"３５１ページ、３５３ページの生徒指導対策費になるのでしょうか、私たちも考え方を述べたいと思います。所管が違うから予算立てがどうこうというのは別なのだけれども、子どもの安全を第一に考えるのだったら、その辺の考え方をお聞きします。","respondent":"大関教育総合支援センター長","answer":"さまざまな考えがある中で、何がどうあるべきなのか。そのような状況の中で、どうあるべきかという部分は、さまざまなご意見を頂戴しながら考えていきたいと思います。","id":"exchange-131"},{"speaker":"渡部委員","kind":"質問・要望","question":"今ここで聞いても答えは出ないと思うのですけれども、そういう要望があったときには検討していただきたいということで、要望して終わります。全員残念ながら入れないかというふうに私はしてほしいと思うのですけれども、その辺について考え方が何かあれば説明を求めました。","respondent":"若生学校制度担当課長","answer":"近年、非常に、特に臨海部を中心に増えてあります。やはりキャパシティも考えると難しいものですので、そこは今後、制度を拡充していく中で考えてまいりたいと思っています。","id":"exchange-132"},{"speaker":"渡部委員","kind":"確認","question":"この質問に入る前に１つ確認したかったのですけれど、例えばＡという学校で兄弟姉妹枠で５人希望がありましたという５人に、つけませんか。そこを先に確認させてください。","respondent":"若生学校制度担当課長","answer":"兄弟姉妹枠の中で抽選になった場合の順位づけのことですけれども、これは特に兄弟姉妹の中で順位というのはつけていないものです。","id":"exchange-133"},{"speaker":"渡部委員","kind":"提案","question":"間に合わないと思うけれど提案させていただけるのであれば、くじ引きで番号を決めるのではなくて、例えば年子でいたら優先順位１番で。そういう優先順位をつけた上で兄弟姉妹枠を扱ってほしいと思うのですけれど、可能性があるかどうか、検討していただけるかどうかとの意見を述べました。","respondent":"若生学校制度担当課長","answer":"それはおっしゃるとおり、くじ引きというか、そういった形で抽選番号を決めているような形です。学校選択制、考え方として入れるのは難しいものですけれども、今後については課題と認識しまして研究してまいりたいと考えております。","id":"exchange-134"},{"speaker":"渡部委員","kind":"質問","question":"ただ、兄弟姉妹だけれども、１つの学校に入れる子がいる一方、入れない子が出てしまっているのも、品川区の学校で事実なわけじゃないですか。私が１つお伺いしたいのは、特色ある教育活動の展開の中の２番目に、「困難に負けず生き抜く力をもつ」。","respondent":"中島教育長","answer":"品川教育ルネサンスで進めている３本の柱によって、これからの学校教育、さまざまな施策を考えてきたつもりであります。時代の中で、最終的にはローカルに戻っていけるような、品川区を愛してくれる子どもたちを全力で育てていきたいと考えます。","id":"exchange-135"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/778040?Template=document&Id=1102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":125857,"voices":325}},{"id":"r01-20190318-3","meetingId":"r01-c-budget","date":"2019年3月18日","dateIso":"2019-03-18","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を125件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"行政のやることですから、家と家の間を仕切るブロック塀というイメージがありますけれども、例えば大きい駐車場の場合もあります。行政の線引きは道路境界線というのは十分理解できるのですが、命を守る視点というところではいかがか尋ねました。","respondent":"中村都市環境部長","answer":"まず生垣助成の考え方と実績ですけれども、潤いのある町並みを形成する、そういった目的のために実施してまいりました。コンクリートブロック塀等安全化支援における隣地境界線という考え方ですけれども、支援の対象や方法について、さまざまな検討を行ってまいりました。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"行政が取組むことですから、安全面、命を守る視点でも考えていってほしいと求めました。その点について説明を求めました。","respondent":"曽田災害対策担当部長","answer":"行政書士会による生活再建支援、あるいはドローンによる情報収集支援など、現在まで提携している協定は１６０になります。さらに株式会社明電舎とは災害時の電源供給に関する協力について、現在、協議を進めているところであります。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"災害時にドローンを活用するということで、そのいざというときに万全を期すために、日ごろより別の用途での使い方が必要ではないかという質問です。お願いいたします。","respondent":"曽田災害対策担当部長","answer":"発災時にドローンを使いこなすためには、操縦研修を終了しました職員に対し、購入するドローンをした使用した操縦訓練を積み重ねていく予定です。いずれにしましても、委員のご提案を参考に、平素の活用を含めたドローンの運用について検討していきたいと考えております。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"町会会館前などの外部がいいかと思いますが、町会会館前に公衆電話の増設の働きかけについてはいかがでしょうか。説明を求めました。","respondent":"中山企画部長、曽田災害対策担当部長","answer":"まず、現行の１０年スパンの長期基本計画を３カ年の総合実施計画で具体的にスケジュール化し、財政収支も想定して各年度の予算を編成しているです。できるだけ速やかに実施すべきものですけれども、安全確実に実施できる体制… これ以上の増設は難しいということでありました。避難所運営訓練における特設公衆電話の設置訓練や公衆電話の設置場所や利用方法の周知など、そういったことを進めていきたいと考えています。","id":"exchange-004"},{"speaker":"本多委員","kind":"提案","question":"款別審査で渡辺委員より、高齢者に対するネーミングで、シルバー、老人、高齢者クラブなど、品川区としてできる配慮をとの提案がされました。よい提案だと思いますとの意見を述べました。","respondent":"永尾福祉部長","answer":"区の高齢者クラブは老人福祉法に定められた老人クラブですけれども、お年寄りのイメージが強いということで、平成６年に変更をしたものです。平成３１年１月末現在では、区で把握している認知症の人数は１万２,１１５人で、高齢者人口増に伴い、今後、増加が見込まれます。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"１５年がたちました。それらの状況や見通しなど、どう情報収集をされているのか説明を求めました。","respondent":"永尾福祉部長、福内健康推進部長","answer":"保険につきましては、平成３１年度に葛飾区と中野区で導入される予定です。他の自治体の実施状況を参考に、保険内容や対象者などを検討し、組み合わせて相乗効果が得られるような形になるよう導入を考えてまいります。日本でもエーザイの候補薬が治験を開始いたしまして、治験終了までまだ時間がかかる見込みであるというふうに聞いております。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"２月３日は節分など、誰がどう伝えていくべきか、家庭や地域社会も意識を持つべきだと思います。伝えることについて説明を求めました。","respondent":"榎本総務部長","answer":"行政といたしましても、地域コミュニティの活性化に向けた支援を継続していく必要があると考えております。こうして以前いただいた善意に対しては、正確な事実や認識を伝える取組みを区としても行ってまいりたいと思います。","id":"exchange-007"},{"speaker":"本多委員","kind":"確認","question":"後世に残し伝えたい取組みを映画などでの活用はいかがでしょうか。今までの１００年、これからの１００年のほうが心配だと発言をされていましたが、その辺についての確認をさせてください。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"そして区政の動きなどは、ケーブルテレビやＹｏｕＴｕｂｅを活用いたしまして、タイムリーな情報発信に努めているところです。例えば伝統行事や町の姿を記録としてドキュメンタリー化とするなどの考えがありますので、今後… 基本的にはデジタルデータ化して、庁内の情報管理システムで保管するとともに、バックアップも行っているところです。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"人材活用の総合的なバランスが求められる点について、流入促進に向けたイメージキャラクターへの人材活用、それぞれについてお聞かせください。この点について説明を求めました。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"今後、区事業におけるイメージキャラクターへの人材の活用ですけれども、認知度向上にも有効と考えています。観光大使にふさわしい方がおりましたら、任命に向けて検討させていただきたいと考えています。 ５つの絆ですけれども、こういったものを大切にしていく安全安心な品川区を意識していくまちづくりということも、しっかり区として今後とも心がけて進めていきたいと考えております。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"地方自治体ですから、半年とか１年間とか、短期間での登用はいいのかなと思います。縁がない方でもお願いしてもいいのではないかと気持ちを述べて、要望して私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"さらに前進してほしいと思っているわけです。それから、ホームページやＳＮＳ等を活用した防災意識の向上施策等について説明を求めました。","respondent":"曽田災害対策担当部長","answer":"引き続き、さまざまな手段を活用しまして、自助の重要性を啓発してまいりたいと考えております。今後もさまざまな新たな手法を取り入れるなど、いろいろな方法でＳＮＳを活用いたしまして、防災意識が向上するよう努めていきたいと考えております。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"被災地には何十回もお伺いしました。そういうことを自助、共助の部分で展開していくことが必要だと思われますが、品川区のお考えを説明を求めました。","respondent":"福島子ども未来部長、本城教育次長、藤田防災まちづくり部長","answer":"これらは月１回以上、地震や火災などを想定した避難訓練を実施しています。消防署と連携しました子どもたちにわかりやすい防災教育の実施を行っているとこ… 都の安全教育プログラムを踏まえまして、どのように身を守るかを具体的に考えたり、疑似体験したりする避難訓練を毎月実施しています。… 平成２４年より６つの小学校、９つの町会に対しまして、津波自主避難マップの作成を支援してまいりました。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どういう行動をして、具体的にどう子どもたちや児童の命を守っていくのかということが行政に求められているわけでありますから、いかがでしょうか。答弁をお願いいたします。","respondent":"本城教育次長","answer":"学校における取組みについては、日常的な訓練に加えさまざまな可能な限りきめ細かい訓練等を実施しています。子どもたちが、その場、突発的な対応についても基本的なものとしてとても重要であると考えているところです。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"防災対策の一環として、港区でタワーマンション等で備蓄品の備蓄をするように条例化されているわけでありますから、１つ参考にすべきだと思います。そういうことを考えていきますと、例えばタワーマンション等での食料、水の備蓄の条例化についても検討すべきと思いますが、いかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"タワーマンション等での食料、水の備蓄についてですが、まずは現在啓発しております自助としての備えを引き続き求めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"条例化はしないということだと思うのですけれども、よく考えてほしいのは、自助をこれから打ち出していくことを確認されたわけであります。それが私はどうしても必要だと思われますので、タワーマンション等の備蓄等について、改めて品川区のお考えを説明を求めました。","respondent":"曽田災害対策担当部長","answer":"現在、マンション防災アドバイザー派遣事業を防災課で実施していまして、防災訓練や防災対策の指導を行っているところであります。訓練、こういったことをやっておりまして、これらのことをあわせて高層マンションの防災対策が進むよう努めていきたいと考えています。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"提案","question":"それぞれありがとうあります。やはり防災ハンドブック、これは議会からの提案で実現させていただいたわけでありますから、改めて品川区のお考えを説明を求めました。","respondent":"曽田災害対策担当部長","answer":"今年度、防災ハンドブック、防災地図を作成しておりますけれども、これは全戸配布を今年の５月中旬から予定しております。デジタルポケットとして配信いたしまして、音声読み上げだとか、多言語に対応していきたいと考えています。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"専門家の意見は、こういうストレスをためずに、自分が弱いと思い込まず、行政や医療機関に助けを求めてほしいと指摘をしていたわけであります。医師、避難生活をされる方々の悩みや苦しみを抱える避難者個々の精神的支援も具体的に検討すべきと思いますが、いかがか尋ねました。","respondent":"福内健康推進部長","answer":"発災直後から都道府県の派遣要請に基づきまして、被災地域にはＤＰＡＴ（災害派遣精神医療チーム）が支援に入ってまいります。区では、こうした取組みにより、助かった命を失うことのないよう、精神的な支援をしっかり行っていきたいと考えております。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問","question":"これも先ほどの質問に重なりますが、いかにそういう場に遭遇したときに、そういう機能がどう展開するかということであります。そしてそこでどういう相談を受けて、福島県の例で見ると、改めて品川区のお考えを説明を求めました。","respondent":"福内健康推進部長","answer":"発災後ですが、多くのチームが全国から派遣されてまいります。適切に振り分けを行い、連日、実際の状況について報告を受けながらきめ細かく対応をしていきたいと考えています。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"意見","question":"今、東日本大震災から８年たつわけでありますけれども、いまだにそのストレスを引きずっている方もたくさんおられます。今の部長の答弁は理解できるところはあるのですけれども、長期的な観点から見てどうなのだということについて、改めてお考えを説明を求めました。","respondent":"福内健康推進部長","answer":"当然、長期的に被災者の方たちに寄り添うことは必要だというふうに考えておりまして、他県から入ってくる保健師たちのチームなどとも協力し、区の職員でしっかり相談等に乗り、支援を行っていきたいと考えています。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"提案","question":"行政のＩＣＴ化に関するさまざまな提案をさせていただいて、今年度、私ども自民党の提案が展開されましたことを改めて感謝する次第です。改めて質問ですが、まず、品川区役所のＩＣＴ推進を長期基本計画等で策定すべきと考えますが、いかがか尋ねました。","respondent":"中山企画部長","answer":"その基本政策といたしまして、電子区役所の推進を掲げまして、内部事務や区民サービスの向上に向けてＩＣＴ化を進めてまいりました。その辺のレベルについては、またしっかりと策定委員会の議論を踏まえながら進めていきたいと考えているところです。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"確認","question":"災害時の安否確認等、幅広く検討すべきと思いますが、品川区のお考えをお聞かせください。お願いいたします。","respondent":"中山企画部長","answer":"それぞれの充実だとか、より一体化させていくかについては、幅広く検討していきたいというふうに考えているものです。平成３０年度は１２０の手続、利用も５,０００件を超える見込みとなっておるものです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"意見","question":"技術的な面が確立するまでの間は、あくまで客観的、１つの基準に基づいてデータを判断ができるものだけに留めるべきだと考えています。あるいはＩＣＴによって、その判断基準が明確に示せるものから始めるべきだと思いますが、品川区のお考えを説明を求めました。","respondent":"中山企画部長","answer":"こういったものをまさにツールを使ってより迅速に行い、常に新しい技術を見ながら、特に品川区は情報推進産業の集積地です。こういう観点で今後ともＩＣＴ化のさらなる推進を意識しながら進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"総括質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の１点目は、品川区長期基本計画とＳＤＧｓとの連動について伺います。そして、今後、品川区がＳＤＧｓに取組み、随時目標達成を継承していくためには、担当部署の設置が必要と考えますが、ご見解を伺います。","respondent":"中山企画部長","answer":"継続的、包括的に施策を進めるべきという考え方は、区政の目指す方向性と合致するものであるというふうに認識しているものです。ＳＤＧｓにおける担当部署の設置ということでありますけれども、それぞれの所管で認識をしていくべきものと考えますけれども、達成目標については。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の２点目は、ＳＤＧｓに取組む区内企業への支援について伺います。ご見解を求めます。","respondent":"中山企画部長","answer":"こういったものを１つの基準にもしながら、例えば製品の販路拡大等の支援を行うとともに、こういったものについても後援を行う等を行っております。今後ともこういった行動についての支援については、幅広い観点で捉えていきたい、考えていきたいというふうに考えています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の１点目は、プラスチックストローの使用見直しについて伺います。区立小中学校の児童保護者から、教育委員会として全ての学校において柔軟な対応を求める見解を出してほしいと求めましたが、いかがか尋ねました。","respondent":"本城教育次長","answer":"その後、各機関から正式な回答などはございませんが、乳業者には、他自治体などから同じような意見が寄せられているようです。現在も柔軟に対応しており、教育委員会としても、そのことを改めて教育委員会として各学校に周知してまいりたいと考えております。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"都内の公立小中学校の学校給食においては、７割以上の学校に紙パックの牛乳が供給され、プラスチックストローが使用されている。東京都から連携の呼びかけがあった際には、ぜひ真っ先に協力をしてほしいと求めましたが、いかがか尋ねました。","respondent":"本城教育次長","answer":"現時点におきましては、まだ都から動きはございませんが、今後、具体的な提案や呼びかけがあった際には、区として対応できるものかどうか精査いたしまして、可能なものについては検討してまいりたいと考えているところです。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問の２点目は、学校給食での宗教的な配慮について伺います。区内では、約２万人の小中学生のうち４６６名が除去食を食べ、そのうち４３６名が一部お弁当を食べていることを確認しました。","respondent":"本城教育次長","answer":"宗教食への対応につきましては、平成２９年に総務省が、今後の取組みの参考に調査結果を公表しています。その調査によりますと、他の自治体においても本区と同じように弁当の持参などの対応をとっているところも多いようですが。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今後、宗教上の理由での給食の配慮については、多様性を尊重して最大限の対応をとっていただきたいと考えますが、いかがでしょうか。学校、教育委員会としての配慮を求めますが、いかがか尋ねました。","respondent":"本城教育次長","answer":"外国籍の児童生徒の増加などを踏まえまして、国際理解をはじめとする多様性の尊重については、教育における重要な課題と認識しています。現在も各学校では十分留意し対応しているところではありますが、今後も引き続き力を入れて取組んでまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区民のリスク軽減の観点から、議会質問で２年間継続して法制度の実施を求めてまいりましたので、とても期待をしております。そして、保険者である品川区、民間の指定保険会社、申込者である区民の関係性について、区民にもわかりやすい形での説明をお願いいたします。","respondent":"藤田防災まちづくり部長","answer":"事業開始の初年度につきましては、約４,０００人の加入を見込んでいるものです。万が一の際には、個別に区民の皆さんが保険会社とお話をする形のものです。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"意見","question":"小さなお子さんと保護者が同乗している場合などは人数分保険に加入する必要があるのかどうか。そして申込者が品川区外で事故に遭った場合も保険対象となるのかなど、具体的にお知らせくださいとの意見を述べました。","respondent":"藤田防災まちづくり部長","answer":"１人で自転車に乗り始めたお子さん、日々、保育園等に子どもを自転車で送り迎えする方などには特に有効であるというふうに考えてあります。自転車賠償責任の部分については、国内のみの対象となっているものです。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ケーブルテレビを含め、先ほど伺ったような保険制度の概要やメリットを区民にしっかりと周知をしてほしいと求めましたが、いかがでしょうか。それを広報することが加入者を呼び込むことにつながると思いますが、ご所見を伺います。","respondent":"藤田防災まちづくり部長","answer":"警察と連携をいたしました自転車安全利用のキャンペーン等、こうしたイベントでも啓発を進めてまいりたいと考えています。引き続き、区民の安全安心の交通環境の確保に努めてまいります。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"あのとき、この保険の存在を知っていればとならないよう、区民への周知を徹底していただければと改めて要望いたします。ご清聴ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"区内の密集市街地が２０１５年からの３年間で約半減したことについて、その中で空き家の除却実績も伺います。さらなる密集市街地解消に向けた取組みについても説明を求めました。","respondent":"中村都市環境部長","answer":"こうした１つ１つの建て替えが不燃領域率を一歩一歩向上させていくものであると認識しております。不燃化１０年プロジェクトが終了予定の平成３２年度末に向けて、制度のさらなる周知の啓発に取組むという考えです。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"特に空き家について質問させていただきたいのですけれども、平成３１年度予算案で、空き家になる前の発生予防対策を新たな事業として始める予定です。売却するなど、土地の再活用が促進されるよう一層の働きかけを求めますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"さまざまな方法がありますけれども、所有者に対する積極的な働きかけで、さらに前へ進めていきたいというふうに考えてあります。現在、不動産団体と相談体制について協議を進めておりまして、各専門家団体と協力していく体制を整えていきたいと考えております。","id":"exchange-035"},{"speaker":"塚本委員","kind":"質問・要望","question":"都議会公明党の求めに対しまして、今年の都議会第１回定例会で、都内での普及啓発に努めると述べました。マイタイムライン作成を防災訓練やワークショップなどで活用してはいかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"東京都が平成３１年度、マイタイムラインの作成支援普及事業を予定していることは聞いておりますが、具体的内容まで区では承知しておりません。確実に避難する上で有効だと認識しており、都の取組みへの対応、それを踏まえて区としての対応を考えていきたいと考えております。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"マイタイムライン人材育成の考え方について、現時点で結構ですので、区のお考えをお聞かせください。都が作成した東京都防災アプリに搭載されたＧＰＳと連動して、東京都防災アプリの周知も必要と考えておりますが、見解を伺いたいと思います。","respondent":"曽田災害対策担当部長","answer":"防災リーダーをはじめといたします人材育成については、極めて重要であると考えているところであります。人材育成の取組みだとか、あるいは東京都防災アプリの周知などにつきましては、具体的な内容を踏まえまして考えていきたいというところであります。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"現在、防災行政無線の音声を品川コミュニティＦＭから発信するということは、開局時から可能であるのか伺います。品川コミュニティＦＭのスマートフォンのアプリ対応について見解を伺います。","respondent":"中山企画部長","answer":"コミュニティＦＭと防災無線情報との連動につきましては、開局の当初から実施する予定です。インターネット回線で視聴可能なスマホアプリとコミュニティＦＭとの連動、聴取ができることについても準備を進めているところです。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"区議会公明党では、障害者団体との懇談会などを通して、障害者が災害時に抱く不安や情報の共有など、意見や要望を伺っております。障害者の不安の解消や情報提供の求めに対して、区としての取組状況をお知らせください。","respondent":"永尾福祉部長、曽田災害対策担当部長","answer":"区民また職員が地域や避難所において、個々の障害特性に配慮した対応ができるよう、さらに周知を図ってまいります。障害のある方とない方がともに楽しく触れ合えるよう、ふくしまつりや作品展等を実施するなど… 地域の支援による避難行動要支援者の個別計画の作成や、避難誘導のワークショップの実施など、災害時の障害者に対するさまざまな取組みが着実に進むよう進めてまいります。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"公明党が２００６年に発表した少子社会トータルプランで掲げた幼児教育の無償化が実現するもので歓迎いたしております。現在、区として実施している認可保育園の保育料負担軽減策の内容と、その目的についてお知らせください。","respondent":"福島子ども未来部長","answer":"幼児教育の無償化ですけれども、３歳から５歳の幼児につきまして、全額無償になるです。軽減につきましては、さまざまな軽減を行っておりますけれども、例えば、多子軽減ですとか、あるいは低所得者等への軽減等を行っているところです。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"品川区として、多子家庭への支援の必要性についての見解を伺いたいと思います。これまで国や都に先立って多子家庭への支援策を拡充してきた品川区として、さらなる支援の推進を要望いたしますが、ご所見を説明を求めました。","respondent":"福島子ども未来部長","answer":"多子家庭への支援の必要性は従前から認識しています。次に、さらなる施策の推進についてですが、これは新たな財源が必要と考えられますので、都が創設します補助金の活用等を踏まえ検討してまいります。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"次に、短時間就労者の保育について伺います。通常の認可保育園に申し込んだ方の中で、就労時間が短い方の入園状況についても、０歳から５歳の年齢別にお知らせください。","respondent":"福島子ども未来部長","answer":"３歳児が６９人、４歳児が１１人、５歳児が２人です。全体の入園者数の約１割弱の状況です。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"いわゆるフルタイムでない０歳から２歳児は、５園の短時間就労枠が一方ではあいているという理由について伺いたいと思います。その際、短時間就労の方の受け入れについて、どのような変化が想定されるのかお考えをお聞きしたいと思います。","respondent":"福島子ども未来部長","answer":"短時間保育室に入っても、保育時間が長い標準時間を希望して転園する児童も増えているということが理由かと考えられます。保育園の増設と年少人口の動向によっては、乳児クラスでも短時間の方が入園できる可能性が上がっていくのではないかというふうに考えている次第です。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"介護などの理由によりフルタイムで働けない事情がある家庭の保育の必要性について、区はどのように考えているか伺います。堺市のように就労と介護を同等に捉える保育所等利用基準など、介護を必要とする家庭の事情に一層寄り添った入園審査の考え方について見解を伺います。","respondent":"福島子ども未来部長","answer":"保育の必要性を適切に捉えた審査を行っていきたいと考えております。日中８時間以上、週４０時間以上の介護を行っている場合などにつきましては、常勤と同等の指数に見直していきたいというふうに考えております。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"次に、小中学生とスマートフォン、ＳＮＳの利用について伺います。あるいは依存症にならないようにすることなどを教えていくことが大切と考えますが、区としての児童生徒に対する指導への見解について伺います。","respondent":"本城教育次長","answer":"インターネットにおけるルールやマナーについて、ＳＮＳトラブルも含めまして、具体的対処法を考え話し合う学習を実施しています。さまざまなデメリットなども検討した結果といたしまして、現時点におきましては、持ち込みが必要であるとの考えは持っているものではございません。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"最後に、災害時、緊急時に連絡手段を確保したいという中学生の保護者の声にどのようにこたえるのか、今般の社会情勢を鑑み、区としてまもるっちを中学生が持つことへの考えを伺います。","respondent":"本城教育次長","answer":"それとともに、非常時における家族の集合場所など、有事の行動について日ごろから家庭で話し合っていくことが大切であると考えております。そのような観点から、しっかりと学校あるいは教育委員会として伝えていくことが大切であると考えているものです。","id":"exchange-046"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私からは、羽田新飛行ルート計画の撤回へ品川区の反対表明を強く求め、３点伺います。そして、この計画になぜ反対しないのか伺います。","respondent":"中村都市環境部長","answer":"現在、国から騒音や落下物の対応について示されておりますけれども、具体性について十分ではないと考えているところです。区民に対しての説明も十分ではないと考えているところです。","id":"exchange-047"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私が伺ったのは、濱野区長は一度でも国土交通省に計画の中止、撤回を求めたことがあるのかないのかです。そして、なぜこの計画に反対できないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"これまで国とさまざまな協議、やりとりをする中では、国に対して、騒音や落下物などの環境影響に対する可能な限りの低減策について、具体的に示し、そして区民に丁寧に説明するよう求めることを繰り返して国交省に対して念押ししているものです。","id":"exchange-048"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私が伺っているのは、区が求めている対応が未達成なまま飛行機が飛ぶその日を迎えてしまうのか、それともいつ反対表明をするのか伺います。あわせて、そもそも飛行機が飛ぶ前に、品川区は計画についての賛否を表明する用意があるのか、考えがあるのか伺います。","respondent":"中村都市環境部長","answer":"現在、国に対して対応を求めている段階におきましては、それを引き続き強く求めていくことが必要と考えております。そして説明を受け、区民の意見もよく聞いてもらい、そして国として判断をしていくというべきものと考えております。","id":"exchange-049"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"答弁が不誠実だと思います。私が伺っているのは、区が国に求めている対応が未達成なまま飛行機が飛ぶその日を迎えてしまうのか、しっかりご答弁ください。","respondent":"中村都市環境部長","answer":"先ほども申し上げましたけれども、国は現在、まだ区民に対して説明を行っている最中です。そういった中では、まずは国の対応策をよく聞く必要性があると考えております。","id":"exchange-050"},{"speaker":"中塚副委員長","kind":"質問","question":"この計画の危険性を区がどう考えているのか改めて伺いたいと思います。そこで、もう決まってしまったことなのか、計画の決定とは、いつどのように決められるのかあわせて伺います。","respondent":"中村都市環境部長","answer":"まだまだ具体性や実効性において区として不十分であると捉えていることを国に伝え、しっかり検討し、説明するよう求めているところです。今後の予定については、国に対して求めておりますが、まだ示されていないところです。","id":"exchange-051"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"このような危険な計画に対して中止を求めなくてどうするのでしょうか。落下物が住民に当たったら、この騒音に住民が日々さらされたら、その住民はどうなるのか、区の見解を伺います。","respondent":"中村都市環境部長","answer":"区からもしっかり国に声を届けるとともに、説明会においてもさまざまなご意見を国が直接聞いていることも確認しております。より一層の丁寧な説明の必要性を感じており、引き続き、国にさらなる取組みを求めていくです。","id":"exchange-052"},{"speaker":"中塚副委員長","kind":"質問","question":"今、予見しないとご答弁がありましたが、考えるべきことだと思います。私が伺ったのは、その生活と健康はどうなるのか、しっかりと、答えるよう求めました。","respondent":"中村都市環境部長","answer":"こうしたものの実効性の担保といたしまして、国は駐機中の抜き打ち検査を行うなどをし、確保していくです。ただ、区もこれで十分とは考えておりませんので、引き続き、国に対して対応策を求めるものです。","id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問","question":"答弁がかみ合っていないのです。私が伺ったのは、その住民の生活や健康がどうなると、区はどう考えているのかしっかり、答えるよう求めました。","respondent":"中村都市環境部長","answer":"落下物の影響につきましては、国では被害を予見せずという回答です。そういったところで、航空機の飛行前の検査を国は強化するとしておりますけれども、これでは不十分と考えていることは先ほど申したとおりです。","id":"exchange-054"},{"speaker":"中塚副委員長","kind":"質問","question":"事故をゼロにするには、今までどおり羽田空港は現在の海上ルートを使用する、羽田新飛行ルート計画撤回が唯一の対策です。品川区はそう考えないのか伺います。","respondent":"中村都市環境部長","answer":"国としましても、現在、検討する中で、検査体制の強化などを掲げておりますけれども、引き続き、さらなる取組みについて求めているところです。こういった落下物に対する１つ１つの取組みが、落下物をゼロにするという取組みにつながるものであると考えております。","id":"exchange-055"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"あってはならない、ゼロを求めていると言いますが、危険やリスクをゼロにするには、羽田新飛行ルート計画撤回が唯一の対策だとなぜ思わないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"これまでオープンハウス型説明会、また区の求めに応じて教室型説明会も実現してまいりました。品川区内全域において国からの説明が行われるように求めている段階であり、現在におきましては、説明を求めるということが一番大事だと考えています。","id":"exchange-056"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"話をごまかさないでいただきたい。説明会を行っているかどうかを聞いているのではなく、計画の撤回がなぜ唯一の対策だと思わないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"現在、国では対応策をいろいろと考えているというところで提案があるところです。より一層詳しい説明を受けるというところが一番大事だというふうに考えているところです。","id":"exchange-057"},{"speaker":"中塚副委員長","kind":"質問","question":"品川区は、この区民の不安や怒りをどう理解しているのでしょうか。そして、どのような被害を与える計画だと住民は思っているのか、区の見解を伺います。","respondent":"中村都市環境部長","answer":"オープンハウス型説明会、また教室型説明会を開催していますけれども、やはり説明会の中では。区としましては、まだまだ国の丁寧な説明が必要であるという見解です。","id":"exchange-058"},{"speaker":"中塚副委員長","kind":"質問","question":"区はなぜ区民がこのように怒っていると思うのか、改めて伺います。飛行機そのものが墜落したらどうなるのか、騒音によって区民生活がどのような被害があるのか、改めて伺います。","respondent":"中村都市環境部長","answer":"区からもしっかり国に声を届けるとともに、説明会においてさまざまなご意見を国が直接聞いていることも確認しております。区としましても、騒音や落下物の対策につきまして、より一層丁寧な説明が必要と感じているところです。","id":"exchange-059"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"そこで部長も、濱野区長も、住民説明会に参加して住民の生の声を、当日の状況を把握してほしいと思いますが、いかがでしょうか。区が反対しなければ、国は理解が得られたと判断するとは思わないのか伺います。","respondent":"中村都市環境部長","answer":"説明会の出席につきましては、状況について常に情報共有を図っているところです。区として国に対しさらなる環境影響への対応策や情報提供、また区民への丁寧な説明を求めるという区としての考え方を明確に国に対して示しております。","id":"exchange-060"},{"speaker":"中塚副委員長","kind":"質問","question":"そして、品川区が反対表明しなければ、国は理解が得られたと判断するとなぜ思わないのでしょうか。そのような政権に対して反対すら表明しないということは、なおのこと国は理解が得られたと判断する、なぜそうは思わないのか改めて伺います。","respondent":"中村都市環境部長","answer":"説明会につきましては、またそれについての回答がどのようだったのか、こういったものについては関係部署の情報共有が図られているです。それは現在さらなる環境影響への可能な限りの低減策を具体的に示し、そして説明をするです。","id":"exchange-061"},{"speaker":"中塚副委員長","kind":"質問","question":"次に、２点目の区民世論について伺いたいと思います。ずばり低空飛行計画の区民世論は、反対が多いのか、賛成が多いのか、区の見解を伺います。","respondent":"中村都市環境部長","answer":"現在、説明会が開催されましても、国に対し多くの質問が出されております。区としましては、まだまだ国の丁寧な説明が区民の皆さんに対して必要であるという見解です。","id":"exchange-062"},{"speaker":"中塚副委員長","kind":"質問","question":"丁寧な説明が必要かどうかを聞いているのではなく、この計画に住民は反対が多いのか、賛成が多いのか、どちらが多いのかと、その点を伺っております。区は、賛成、反対、どちらの区民が多いと思うのか、改めて伺います。","respondent":"中村都市環境部長","answer":"区でも地域の皆さんから国に対する意見として、説明会をもっと開催してほしいという声があります。は十分な説明を経た後に、国が考える、あるいは判断するべきというふうに考えております。","id":"exchange-063"},{"speaker":"中塚副委員長","kind":"質問","question":"国が判断するかどうかを聞いているのではなく、区がどう思うのかを聞いているのです。反対している区民が多いという事実すら、なぜ認めようとしないのか伺います。","respondent":"中村都市環境部長","answer":"区としまして、さまざまな意見があることを承知しております。１つ１つの意見が尊重されるべきであり、区として国に対してさらなる環境影響の低減に向けた方策と、検討の説明を求めるものです。","id":"exchange-064"},{"speaker":"中塚副委員長","kind":"質問","question":"反対している区民が多いという事実すら、なぜ認めようとしないのですか。品川区は反対している区民が多いという事実をなぜそのように頑なに認めようとしないのか、改めて伺います。","respondent":"中村都市環境部長","answer":"新飛行経路は国が進めているものでございまして、現在、国が地域において説明を行っているところです。したがいまして、地域の理解あるいは区民のご意思につきましては、説明を行っている国が確認するべきであるというふうに考えてあります。","id":"exchange-065"},{"speaker":"中塚副委員長","kind":"提案","question":"国が確認すべきことではなく、区がどう思うのかと聞いていることに答えられない。そして、国が拒むなら、品川区が実施すべきと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"そして、引き続き、丁寧な説明をしていくとしております。区もまた国の丁寧な説明により、計画内容をより多くの方に知っていただきまして、国に対しさらなる検討を求めるというものです。","id":"exchange-066"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区は国に求めているのか、ないのだったら、区独自に実施する考えはないのかということです。、答えるよう求めました。","respondent":"中村都市環境部長","answer":"そういったご意見につきましては、国にしっかりと届けているです。国は区民に対して説明を行い、意見を聞くのは国の責任であるという考えのもと、説明を求めていかなければいけないと考えております。","id":"exchange-067"},{"speaker":"中塚副委員長","kind":"質問","question":"その声を届けているといっても、では、その声は賛成が多いのですか、反対が多いのですか、どの声を届けているのですか。ちゃんと答えてください。","respondent":"中村都市環境部長","answer":"単に賛成、反対といったご意見ではなく、騒音影響に対する不安があるというような理由を添えてご意見をいただくというものです。そういった区民の方のご意思と、そしてその理由を国へ事細かく伝えているところです。","id":"exchange-068"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"さらには住民投票の実施など、区民の期待にこたえるため、議決機関である品川区議会独自の役割が今こそ求められていると思います。羽田新飛行ルート計画撤回へ、この１点で多くの政党、幅広い住民の皆さんと一緒に力を合わせることを呼びかけて、私、中塚亮の総括質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国保料の引き下げと、子どもの国保料無料化を求めて質問いたします。そして、構造的問題は解決が必要だと考えているのか、解決が必要だと考えているのであれば、どう解決をしていくのか伺います。","respondent":"福内健康推進部長","answer":"構造的問題を含め、増大する医療費等が背景にあり、国民皆保険を将来にわたって堅持していくために、今回の法制度改革がされております。区といたしましては、財源の確保について、引き続き、特別区長会、全国市長会を通じて、国や都に対して要望をしてまいります。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この構造的な問題をどう解決していくのか、これを伺いました。経年的に見て、国保料がどれだけ値上げされてきたか伺います。","respondent":"福内健康推進部長","answer":"次に、経年的に見てどれだけ上がったかですが、年収３００万円の場合、平成２１年度は１７万９,８２９円で、平成３１年度は３６万６,９００円です。年収５００万円の場合、平成２１年度は３２万８,５０５円であり、平成３１年度は５８万４,３００円です。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この格差はなくすべきではないでしょうか。日本共産党は、全国知事会も求めています１兆円の公費投入で、そうすることで協会健保並みに引き下げられると提案を行っているところですとの意見を述べました。","respondent":"福内健康推進部長","answer":"法定外繰入金の決算ベースです。平成２８年度が１５億２,０００万円、平成２９年度は５億９,０００万円、平成３０年度は３億３,０００万円です。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、品川区は子どもの国保料均等割の無料化を国に求めておりますけれども、その求めている理由は一体どういう理由で求めているのかも伺います。改めて求めますが、いかがか尋ねました。","respondent":"福内健康推進部長","answer":"特別区では、平成３０年から６年間の解消計画を立てて、法定外繰入金を段階的に縮小する予定です。区独自の子どもの均等割無料化につきましては、その負担をさらに一般財源でまかなうこととなり、非常に困難と考えています。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めてなぜできないのか、お金の問題なのか伺います。税金の使い方として、国と区の税金の使い方の考え方にどう違いがあるのかも伺います。","respondent":"福内健康推進部長","answer":"区独自に無料化しない理由につきましては、その財源をさらに一般財源でまかなうこととなるということで難しいと考えております。子どもにかかる均等割軽減措置を含め、その制度上の課題につきましては、国が責任を持って対応すべきものと考えています。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は公平性の観点から一般財源を使うのはふさわしくないという、そのことに対してお伺いいたしました。そのことについての答弁がありませんので、ぜひお願いします。","respondent":"福内健康推進部長","answer":"国民健康保険制度は、国民健康保険法に基づいて運用されているものです。この中で税の使い方、一般財源でまかなうことについては非常に困難というふうに考えているものです。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらに、わずか２億円でできる子どもの国保料の無料化を強く求めて次の質問に移ります。昨年２月締め切りで９月までに入れた人は何点までの人が入れたのか、おおよそ入れる点数といわれる７０点以下は何人いたのか伺います。","respondent":"永尾福祉部長","answer":"１年以上２年未満が１０点、２年以上５年未満が１５点、５年以上が２０点というふうになっております。介護の状況につきましては、介護者が老年だったり、また複数の人を介護してしていたり、就労中等々により点数を加点しています。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それはなぜなのでしょうか。若くして突然倒れ、重度で在宅介護ができない場合は、どのような方法があるのか伺います。","respondent":"永尾福祉部長","answer":"例を出されました老人保健施設を探す場合もありますし、また、訪問リハというところも考えたりしているのが現状になっております。やはり７５歳以上になりますと、そういう観点からリスクが高まるということで加点をしているという制度になっております。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私はこういう若い方が突然倒れた場合、どういう方法があるのかも伺いました。林試の森隣の増設後も特養ホームの増設が必要だと、こういう認識はあるのか伺いますとの意見を述べました。","respondent":"永尾福祉部長","answer":"その環境を変えたくないということで、さまざまな場合がありますので、一概に人数だけでの比較はちょっと難しいかなというふうに思っております。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど、断るケースというのもありましたけれども、では、断るケースが何人いたのか伺いたいと思います。それなのに、なぜ増設計画をつくらないのか、直ちに待機者ゼロへの増設計画をつくるべきだと思いますけれども、いかがか尋ねました。","respondent":"永尾福祉部長","answer":"そして、それ以外にお亡くなりになった方が６５人いらっしゃいます。その方が安心して生活できるような施設のパターンはさまざまありますので、そういう施設を総合的に勘案しながら整備をしていきたいと考えております。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから東大井都営住宅跡など、特養ホームの増設計画を立てて増設すべきだと求めますけれども、いかがでしょうか。いかがか尋ねました。","respondent":"中山企画部長","answer":"公有地等を活用した施設整備につきましては、さまざまな行政需要の中、地域特性等の諸条件を勘案して総合的に判断してまいりたいと考えております。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも土地もあります、お金もあります、この区民の切実な声にこたえてほしいと求めました。大変な区民の実態に心を寄せていただいて、待機者ゼロへ直ちに計画を立てて、５００人分の特養ホームをつくるよう求めて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"木村委員","kind":"質問・要望","question":"なぜ日本政府は２０１７年７月に採択された核兵器禁止条約交渉に出席し賛成しなかったのでしょうか。配備、持ち込みを認めないと品川区民の皆さんに改めて宣言してほしいと思いますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"品川区としては、区の実施する各種平和事業を通じまして、核兵器廃絶と恒久平和のための意識啓発を継続的に行っていると考えております。３５周年記念事業への取組みも含め、宣言の趣旨をより広く区内に届けてまいりたいと考えています。","id":"exchange-082"},{"speaker":"木村委員","kind":"質問・要望","question":"親が、また近所の大人たちが手本となり教えていくことが大事と思いますけれども、行政としてのお考えをお聞かせください。これは我々大人たちにも責任があると思いますが、どのようにお考えかお聞かせほしいと求めました。","respondent":"榎本総務部長","answer":"子どもたちにもしっかりと伝わるように、親子で参加できる啓発事業等も実施しています。こういう作品を見ながら人権について感じ取り、大人が子どもを連れて一緒に参加していくという事業を続けていくことが必要だと考えております。","id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"生命の尊重とは、青少年にどのように指導をしていくのでしょうか。説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"次に、地域スポーツ支援から伺います。スポーツを強制するものではなく、スポーツに関心を持ち、積極的に参加をしてもらうために何が必要か尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"区では、充実に努めてまいりました。今後は、引き続き、地域スポーツクラブの充実に向けて支援をしてまいりますとともに、スポーツ推進計画を新たにこれから策定する予定です。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"区の障害者スポーツについてのお考え、そしてイベントや教室の拡充についてのお考えをお聞かせください。最後に、今後の本区のスポーツ推進全般にあたって、何かあればお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興部長","answer":"今後は、障害のある人もない人もともに楽しむことができるような新たな競技の開催を考えていきたいと考えています。今、そこの中に新たにスポーツ推進計画を策定することを位置づけまして、これまで以上に障害者スポーツを推進してまいりたいと考えています。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、こころの健康とは何でしょうか。どのようなこころの状態を不健康だというのか尋ねました。","respondent":"福内健康推進部長","answer":"健康な社会生活を営むためには、体の健康と同時に、こころの健康を保つことがとても大切です。気分が落ち込み、全てのことに興味が持てず、何事にも悲観的で不安感が強い状態は、こころが不健康といえます。","id":"exchange-087"},{"speaker":"木村委員","kind":"質問・要望","question":"お聞きいたしますが、早期の相談や医療機関受診をすることが、よい回復の一歩となりますが、本区での相談状況はいかがでしょうか。来年度、自殺対策計画をつくるということですが、どのような計画か尋ねました。","respondent":"福内健康推進部長","answer":"保健師、専門医等がこころの健康相談を実施しており、その約６割がご本人以外からの相談となっております。警察や消防等、関係機関との連携や全庁的な取組みにより、追い込まれて自殺する人を未然に防ぐことを目指した計画としていく予定です。","id":"exchange-088"},{"speaker":"木村委員","kind":"質問・要望","question":"これは要望で終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"大倉委員","kind":"質問","question":"シティプロモーションについて伺いたいと思います。シティプロモーションを行っていく意義について、改めてお知らせほしいと求めました。","respondent":"中山企画部長","answer":"これはあくまでもツールであって、これにつながる言葉をいかにインパクトをもって伝えていくかということが大事かと認識しています。","id":"exchange-090"},{"speaker":"大倉委員","kind":"質問・要望","question":"しながわ」のポスターの掲示箇所とか掲示状況とかというのはお伺いできなかったのですが。その辺の考え方について教えていただきたいのと、あと、今後の品川区のシティプロモーションの取組みについてもご所見をお伺いします。","respondent":"中山企画部長","answer":"こういったものをよりインパクトを持って認識していただくように、有効的にやっていくということは重要かなと認識しているものです。先ほど申し上げたような大きく２つ、総合的に広げていく、そういう観点がこれからは重要になるものと考えております。","id":"exchange-091"},{"speaker":"大倉委員","kind":"質問","question":"逗子市では、市が所有する護岸約２１８ｍをキャンバスに子どもたちと高圧洗浄器を使って海の生物を描いたという取組みがありました。こういった活用についてお伺いできればと思うのですが、こういったことができるのではないかと思っているのですが、ご所見を伺います。","respondent":"中山企画部長","answer":"私もご質問までなかなか認識できなかった方法ではありますけれども、地方の都市等で、興味ある事例があるということは認識させていただきました。","id":"exchange-092"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に、クラウドファンディングについて伺います。さまざまな成功事例もあるのですが、そういった成功事例についても研究しながら成功に向けて取組んでほしいと求めましたが、ご所見を伺います。","respondent":"福島子ども未来部長","answer":"今後に向け、食の支援の拠点や食を提供する子どもの居場所づくりの検討などを行っていく予定です。さらには、支援企業に対しまして、情報の媒体やイベントの機会に協力を求めるＰＲなどを行う予定です。","id":"exchange-093"},{"speaker":"大倉委員","kind":"質問","question":"これはこの事業ということではなくて、これからの品川区のガバメントクラウドファンディングというところで、活用について伺いたいと思います。今後、それも目的の１つとして活用されているのかと思うと、どのような事業をやっていきたいとかという方向性があれば説明を求めました。","respondent":"中山企画部長","answer":"品目的に必ずしも少ないということではありませんけれども、品川区の魅力を伝える工夫はしっかりやっていきたいと考えておるものです。基本的にはこういう多様な財源調達やＰＲの手段という観点で広げることを検討しながら進めていく、このように考えています。","id":"exchange-094"},{"speaker":"大倉委員","kind":"質問","question":"次に、賑わいの創出について伺いたいと思います。大型の商業施設や地域商店街との連携について、品川区が間に立って連携をとっていくというのは大事だと思いますが、お考えを説明を求めました。","respondent":"安藤文化スポーツ振興部長","answer":"委員ご提案の区内の観光スポットと大型商業施設または商店街との連携についてですけれども、品川区の観光振興協議会をつくってあります。は回遊性のさまざまな検討をされていますので、委員ご提案の趣旨を踏まえて、今後の検討課題とさせていただきたいと考えています。","id":"exchange-095"},{"speaker":"大倉委員","kind":"質問","question":"今現在、品川区でも商店街と連携してやられていたり、観光協会が先頭に立ってやっていたりということは伺っているので。やっぱり品川区にも申請に１回来るので、そういったところを捉えて、それについてのご見解を説明を求めました。","respondent":"安藤文化スポーツ振興部長","answer":"そして、民間事業者のイベント等の支援と申しましょうか、地元町会や商店街の理解と協力というものが非常に不可欠であると私どもの認識です。関係所管とも連携し、効果ある賑わいの創出に向けて今後も研究してまいりたいと思っています。","id":"exchange-096"},{"speaker":"大倉委員","kind":"質問・要望","question":"以前も質問させていただいたのですが、防災フェスティバルがこの間も開催されていましたが、多くのファミリー世帯の方が参加されていました。防災訓練を運動会みたいな形でやるというような、子どもが参加しやすい防災訓練について、どのようにお考えかお知らせください。","respondent":"曽田災害対策担当部長","answer":"非常に重要だと考えておりまして、総合防災訓練において親子で防災体験とか、そういったことをやりながら子どもの参加を促しているところであります。さまざまな手段で子どもを呼ぶということはこれからもいろいろ検討していきたいと考えているところであります。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"４、電気やガス、水道などのライフラインは、安定的な供給に支障がないのでしょうか。６、金融機関のＡＴＭ使用や、振り込みや、資金繰り等の借入対応は大丈夫か尋ねました。","respondent":"榎本総務部長","answer":"１０連休に対する区の対応方針ということですけれども、ごみ収集につきましては、それ以外については全て平常どおり収集するということで行います。大型連休中への対応ということで、需要の増加等、それぞれ支障がないように各省庁に指示を出しています。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問・要望","question":"そして、なぜ区の対応をもっと早く区民に公表しないのか。おそらく心配されている方も多々いらっしゃると思うのですが、この辺についてご見解だけ説明を求めました。","respondent":"榎本総務部長","answer":"それも含めまして、４月の広報でお知らせをしていきたいということで、同時にホームページでもお知らせをする予定です。それから、やはりそれぞれ国の対応等も踏まえた上での対応ですので、なるべく早めに広報については周知徹底をしていきたいと考えています。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"区では、景気が上向いているという認識をされているように聞こえますが、その根拠は何ですか。説明を求めました。","respondent":"中山企画部長","answer":"必ずしも格差が拡大している、あるいは低所得者層が増えているというふうには断定できないという状況はあります。景況の認識はさまざまの数値がありますけれども、内閣府もやや景況判断を下降の兆しがあるというような報告が出ているのは認識しておりますけれども。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"でも、区内はどうですか。区内産業、製造業や商店街もよくないということをよく認識して、それをもとに予算組みをしなければいけないのではないか尋ねました。","respondent":"中山企画部長","answer":"景況判断の数字はさまざまな指標があります。それに応じた対応といいますか、区の中での施策を長い目で考えるもの、こういう姿勢は常に持っているものです。","id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"ですが、政府が今後やっていこうとしているように、今は低所得者層の負担を減らすための救済に向けるべきではないのですか。説明を求めました。","respondent":"堀越地域振興部長","answer":"国の商品券事業として予定されているものは、商店街の振興につなげていくですので、大きな意味で景気を上げていくというふうに考えているところです。","id":"exchange-102"},{"speaker":"須貝委員","kind":"質問","question":"どうしても一部の元気な方で、そこにお金が要るわけですから、そういう人たちに販売が偏るのではないですか。結果としてそれは商店から物を買うわけですから、もう一度、その辺の意味合いについて説明を求めました。","respondent":"堀越地域振興部長","answer":"こちらを過去３年間で見ますと、大体３割を超えているというふうな、３５％ぐらいまでいっているような経済効果の試算をしております。","id":"exchange-103"},{"speaker":"須貝委員","kind":"質問・要望","question":"東京都でこの子どもたちの行く末に責任をもってもらえるのですか。子どもと接している教員の方々の人物評価はされているのか尋ねました。","respondent":"本城教育次長","answer":"例えばいじめ等の問題に対して組織的な対応が必要であると考えておりまして、ＨＥＡＲＴＳ等を組織したりして、さまざまな形で学校を支援しています。","id":"exchange-104"},{"speaker":"須貝委員","kind":"確認","question":"そしてまた別のお子さんは、先生が相談を受け、本人に確認していたにもかかわらず、自殺している事実、こういうものがあるのです。このようなことでは、先生に相談したり、信頼したりすることはできないのではないか尋ねました。","respondent":"本城教育次長","answer":"少し繰り返しになりますが、担任の教員一人だけで対応するのではなくて、組織としてしっかり対応して。それに対してどのような形で学校現場、あるいは教育委員会として対処していくかということにつきましては、組織的な対応ということだけではなくて。","id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"今日はこの人、今日はこの人、今日はこの人では、そういうことではないのではないですか。そういうじっくり１対１の対面で相談に応じる、そういう姿勢が大事ではないか尋ねました。","respondent":"本城教育次長","answer":"ただ、あるいは担任の教員だとなかなか、逆に近いから気がつかないこと等々いろいろあろうかと思います。スクールカウンセラー、あるいは養護教員等々、学校全体としてしっかりと子どもに対処していくことが必要であると考えているところです。","id":"exchange-106"},{"speaker":"須貝委員","kind":"質問・要望","question":"いじめに対する免疫を持たない子はどうすればよいのか教えてください。今はいじめを克服できる教育をすべきではないのか尋ねました。","respondent":"本城教育次長","answer":"そういう意味で、そういったものにも対処することができるようなしっかりとした、いわゆる生きる力をつけていくことが肝要であると考えております。","id":"exchange-107"},{"speaker":"須貝委員","kind":"意見","question":"現実ではこういうことがあるのです。自立し、社会に出て生き抜いていける力も養ってほしいのですが、教育委員会としてこういうことをやっていきたいという意思表示をしてくださいとの意見を述べました。","respondent":"本城教育次長","answer":"今までの回答と重なるところはあるかもしれませんけれども、現在の学校生活にしっかりと適合するとともに、将来の社会の構成員として力強い子どもたちを育てていきたいと考えているところです。","id":"exchange-108"},{"speaker":"田中委員","kind":"確認","question":"保健センターなどの受入能力を先に確認し計画を進めて、指針などに盛り込むべきではないかと生活者ネットワークは考えますが、見解を伺います。そこから導き出される帰宅困難者の数も見込み、受入能力まで想定して備えておくべきと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"帰宅困難者等の避難者に対する対応ですけれども。そういった中で、備蓄倉庫を含めたさまざまな防災の工夫について、事業者とともに協議をしながら進めているところです。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問","question":"再開発が進んでいる地域からは、区として高さや容積率を制限する条例をつくるなど対応が必要なのではないかと聞こえてきますが、区の見解を伺います。戸越公園に設置される環境館では、防災機能をどのように取り入れていくのか伺います。","respondent":"中村都市環境部長","answer":"再開発におけます上位計画との位置づけと連携についてですけれども、または整備方針、こういったものを立てて整合性を図りながら進めているです。これも周辺に対する環境や景観、そういったものに配慮する中で、さまざまな工夫を設計に取り入れる中で事業を進めているです。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"区として新ルート案を容認していないということになるのではないでしょうか。であるのなら、はっきりと白紙撤回を明言するべきと考えますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"これはやはり疑問が残るところですので、さらに国に対して対応策、新たな強化策を求めていきたいと考えているところです。こういった対応策の担保は国が考えるものですけれども、国に対して区は強くそういったものを示すように求めていきたいというふうに考えております。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"区には、区民や区民の生活や命を守る視点に立ってほしいと再度強く求めますが、見解を伺います。１８歳を超える子どもへのケアも求めますが、見解を伺います。","respondent":"中村都市環境部長、福島子ども未来部長、本城教育次長","answer":"区といたしましては、国に対してさらなる対応策を求めるべきというふうに考えてあります。そういった設計、通常考えられる環境影響に対しての対応策として… こういったさまざまな困難を抱えている子どもに対する支援を行っていきたいというふうに考えているものです。昨年… いじめ等だけではなくて、心理的、社会的に不安を抱えている状況を発見することができる重要な場の１つであると考えているところです。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"各所管で密な連携をとり、ケア者支援につなげていただきたいと強く要望いたしますが、見解を伺います。これは羽田新ルートのことも想定されてビルの設計、そしてガラスの設定とかもされていたのか、もう一度伺います。","respondent":"福島子ども未来部長、中村都市環境部長","answer":"ヤングケアラーの問題ですけれども、確かに声を上げづらい問題ではあると思いますし、また、声がこちらのほうに届きにくい問題でもあります。あるいはどのような支援が必要なのか、関係部署と十分に話し合いを行い… 特に羽田を想定しているというわけではなくて、地震や台風に対する風の耐圧性、こういったものに対して設計で対応しています。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"区として求めるものではないということでしたが、国も落下物リスクをゼロにはできないと言っているのですし、そこのところはいかがでしょうか。答弁を求めます。","respondent":"中村都市環境部長","answer":"ちょっと説明が不足していたというところがあるかもしれません。やはり、国策として取組んでいる国がさまざまな問題に対しては対応策を考えて、そして説明をする立場であるというのは。","id":"exchange-114"},{"speaker":"田中委員","kind":"提案","question":"提案する立場ではないとかではなくて、立場に立ったときに、やっぱり区としてはっきりと白紙撤回と明言するべきだと思うのです。伺いますとの意見を述べました。","respondent":"中村都市環境部長","answer":"教室型説明会も今８カ所、残り５カ所について協議していますので、区内全域にしっかりと説明がなされるように求めていきたいと考えております。地域の皆様にさらに説明をしていただきたいというような取組みが最優先であるというところは先ほど申し上げたとおりです。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどから何回も申し上げているのですが、これは区としても新ルートを容認していないとはっきり明言されたらいいのではないでしょうかと思います。シャットアウトされてしまうのか、きちんと開かれた場になるのかということもあわせて伺います。","respondent":"中村都市環境部長","answer":"説明会につきましても、残り５地区ですけれども、こちらもしっかりと区内全域に説明をしていただくように国に求めてまいります。そのときのメディアの対応についてですけれども、これは区の考えでもありますので、こういったところはしっかり国に伝えていきたいと考えております。","id":"exchange-116"},{"speaker":"田中委員","kind":"質問・要望","question":"きちんと開かれた説明会の場であることを求めますし、あと、やっぱり区として全体の政策がきちんと整合性がとれていないと思います。区には、区民の生活や命を守る姿勢に立ってほしいと再度強く求めますが、見解を伺います。","respondent":"中村都市環境部長","answer":"やはり地域の皆様に説明がなされることだと考えておりますので、そういったところでは、しっかりと説明自体は行われているという認識です。こちらのついても区内全域、これは国としてさまざまな対応策があると思いますけれども、飛行経路下における影響も大きいです。","id":"exchange-117"},{"speaker":"田中委員","kind":"質問・要望","question":"そこを伺います。そしてやはり区として新ルート案を容認していない、はっきりと白紙撤回を明言するべきと求めますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"マスコミに対して規制をしないですけれども、こういったことについては、説明者である国が最終的には判断をするというところが残念ながらあります。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会でのメディア規制について、きちんと区として申し入れてください。そのように求めますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"そういった地域の皆様からの声も届いておりますので、しっかりと伝えたいと思います。","id":"exchange-119"},{"speaker":"渡部委員","kind":"提案","question":"政策として要望、提案いたしました施策が予算に反映されており、着実に具体化されることを望みます。自民党・子ども未来１１名の委員からの要望、提案を新年度の事業実施に生かされるよう求め、品川区議会自民党・子ども未来の意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"若林委員","kind":"提案","question":"限られた予算の中で最大の事業効果を上げられるよう要望いたします。障害者の災害時支援をはじめ、款別審査での提案や意見、要望を今後の区政運営に反映されるよう求めますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２３区で最低の整備率の障害者グループホーム、区外利用者の要望をつかみ、施設増設と支援充実を求めます。安倍９条改憲や消費税１０％など、そして平和に暮らす権利を守る立場に立った区政運営を求めて、意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"石田（し）委員","kind":"提案","question":"ＡＩやＩｏＴなどの活用や、情報発信のあり方、羽田新飛行ルート、学校教育、東京２０２０大会などの課題への積極的な取組みも求めます。提案した各項目を真摯に受けとめ、予算を執行することを強く要望して、国民民主党・無所属クラブの意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問・要望","question":"不登校、自殺、児童虐待などを乗り越えられる教育と相談しやすい学校を築いていただきたい。以上で、無所属品川の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"吉田委員","kind":"提案","question":"１０月の開設に向けては、このような齟齬が起きないよう強く求めます。その他、款別審査で生活者ネットワークが指摘、提案させていただいた意見を予算執行に生かしていただくことを要望し、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/778040?Template=document&Id=1104#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":107764,"voices":291}}]);
